QT_ISI(11,{"1328":["(Sesungguhnya jalan untuk menyalahkan itu hanyalah terhadap orang-orang yang meminta izin kepadamu) untuk tidak ikut berangkat berjihad (padahal mereka itu orang-orang kaya. Mereka rela berada bersama-sama orang-orang yang tidak ikut berperang dan Allah telah mengunci mati hati mereka, maka mereka tidak mengetahui) akibat perbuatan mereka.",[["۞ إِنَّمَا","Only"],["ٱلسَّبِيلُ","the way (blame)"],["عَلَى","(is) on"],["ٱلَّذِينَ","those who"],["يَسْتَـْٔذِنُونَكَ","ask your permission"],["وَهُمْ","while they"],["أَغْنِيَآءُ ۚ","(are) rich"],["رَضُوا۟","They (are) satisfied"],["بِأَن","to"],["يَكُونُوا۟","be"],["مَعَ","with"],["ٱلْخَوَالِفِ","those who stay behind"],["وَطَبَعَ","and Allah sealed"],["ٱللَّهُ","and Allah sealed"],["عَلَىٰ","[on]"],["قُلُوبِهِمْ","their hearts"],["فَهُمْ","so they"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1329":["(Mereka mengemukakan uzurnya kepada kalian) untuk tidak pergi berperang (apabila kalian telah kembali kepada mereka) dari medan perang (Katakanlah) kepada mereka (\"Janganlah kalian mengemukakan uzur, kami tidak percaya lagi kepada kalian) kami sudah tidak mempercayai lagi kalian (karena sesungguhnya Allah telah memberitahukan kepada kami di antara berita-berita rahasia kalian) Allah telah memberitahukan kepada kami tentang hal-ihwal kalian. (Dan Allah serta Rasul-Nya akan melihat pekerjaan kalian kemudian kalian dikembalikan) melalui dibangkitkan dari dalam kubur (kepada Yang Mengetahui yang gaib dan yang nyata) yakni Allah (lalu Dia memberitahu kepada kalian apa yang telah kalian kerjakan.\") maka Dia membalasnya kepada kalian.",[["يَعْتَذِرُونَ","They will make excuses"],["إِلَيْكُمْ","to you"],["إِذَا","when"],["رَجَعْتُمْ","you (have) returned"],["إِلَيْهِمْ ۚ","to them"],["قُل","Say"],["لَّا","(Do) not"],["تَعْتَذِرُوا۟","make excuse"],["لَن","never"],["نُّؤْمِنَ","we will believe"],["لَكُمْ","you"],["قَدْ","Verily"],["نَبَّأَنَا","Allah (has) informed us"],["ٱللَّهُ","Allah (has) informed us"],["مِنْ","of"],["أَخْبَارِكُمْ ۚ","your news"],["وَسَيَرَى","and Allah will see"],["ٱللَّهُ","and Allah will see"],["عَمَلَكُمْ","your deeds"],["وَرَسُولُهُۥ","and His Messenger"],["ثُمَّ","Then"],["تُرَدُّونَ","you will be brought back"],["إِلَىٰ","to"],["عَـٰلِمِ","(the) Knower"],["ٱلْغَيْبِ","(of) the unseen"],["وَٱلشَّهَـٰدَةِ","and the seen"],["فَيُنَبِّئُكُم","then He will inform you"],["بِمَا","of what"],["كُنتُمْ","you used (to)"],["تَعْمَلُونَ","do"]]],"1330":["(Kelak mereka akan bersumpah kepada kalian dengan nama Allah, apabila kalian kembali) yakni pulang (kepada mereka) dari medan perang Tabuk untuk menunjukkan bahwa mereka benar-benar mempunyai alasan yang tepat sewaktu mereka tidak ikut berangkat (supaya kalian berpaling dari mereka) artinya supaya tidak mencela perbuatan mereka itu. (Maka berpalinglah dari mereka karena sesungguhnya mereka itu adalah najis) najis karena batin mereka kotor (dan tempat mereka Jahanam sebagai balasan atas apa yang telah mereka kerjakan.)",[["سَيَحْلِفُونَ","They will swear"],["بِٱللَّهِ","by Allah"],["لَكُمْ","to you"],["إِذَا","when"],["ٱنقَلَبْتُمْ","you returned"],["إِلَيْهِمْ","to them"],["لِتُعْرِضُوا۟","that you may turn away"],["عَنْهُمْ ۖ","from them"],["فَأَعْرِضُوا۟","So turn away"],["عَنْهُمْ ۖ","from them"],["إِنَّهُمْ","indeed, they"],["رِجْسٌۭ ۖ","(are) impure"],["وَمَأْوَىٰهُمْ","and their abode"],["جَهَنَّمُ","(is) Hell"],["جَزَآءًۢ","a recompense"],["بِمَا","for what"],["كَانُوا۟","they used (to)"],["يَكْسِبُونَ","earn"]]],"1331":["(Mereka akan bersumpah kepada kalian agar kalian rida kepada mereka. Tetapi jika sekiranya kalian rida kepada mereka, maka sesungguhnya Allah tidak rida kepada orang-orang yang fasik itu) artinya Allah tidak rela kepada mereka dan kerelaan kalian kepada mereka sedikit pun tidak akan bermanfaat buat mereka, karena Allah telah murka kepada mereka.",[["يَحْلِفُونَ","They swear"],["لَكُمْ","to you"],["لِتَرْضَوْا۟","that you may be pleased"],["عَنْهُمْ ۖ","with them"],["فَإِن","But if"],["تَرْضَوْا۟","you are pleased"],["عَنْهُمْ","with them"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["لَا","(is) not pleased"],["يَرْضَىٰ","(is) not pleased"],["عَنِ","with"],["ٱلْقَوْمِ","the people"],["ٱلْفَـٰسِقِينَ","(who are) defiantly disobedient"]]],"1332":["(Orang-orang Arab itu) yaitu penduduk daerah badui (lebih sangat kekafiran dan kemunafikannya) daripada penduduk daerah perkotaan; karena penduduk daerah badui berwatak keras dan kasar serta mereka jauh dari mendengarkan Alquran (dan lebih wajar) lebih patut (tidak mengetahui hukum-hukum yang diturunkan Allah kepada Rasul-Nya) berupa hukum-hukum dan syariat-syariat. Huruf allaa asalnya terdiri dari an dan laa kemudian keduanya digabungkan, sehingga jadilah allaa. (Dan Allah Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) di dalam mengatur penciptaan mereka.",[["ٱلْأَعْرَابُ","The bedouins"],["أَشَدُّ","(are) stronger"],["كُفْرًۭا","(in) disbelief"],["وَنِفَاقًۭا","and hypocrisy"],["وَأَجْدَرُ","and more likely"],["أَلَّا","that not"],["يَعْلَمُوا۟","they know"],["حُدُودَ","(the) limits"],["مَآ","(of) what"],["أَنزَلَ","Allah (has) revealed"],["ٱللَّهُ","Allah (has) revealed"],["عَلَىٰ","to"],["رَسُولِهِۦ ۗ","His Messenger"],["وَٱللَّهُ","And Allah"],["عَلِيمٌ","(is) All-Knower"],["حَكِيمٌۭ","All-Wise"]]],"1333":["(Di antara orang-orang Arab badui itu ada orang yang memandang apa yang dinafkahkannya) di jalan Allah (sebagai suatu kerugian) ketekoran dan kerugian sebab ia tidak mengharapkan akan pahalanya melainkan menginfakkannya karena rasa takut; mereka adalah Bani Asad dan Bani Ghathafan (dan menanti-nanti) malapetaka menimpa kalian sehingga ia bebas dari kalian (merekalah yang akan ditimpa marabahaya) dapat dibaca as-suu` dan dapat pula dibaca as-sau`, artinya azab dan kebinasaan itu justru akan menimpa mereka sendiri bukannya menimpa kalian. (Dan Allah Maha Mendengar) akan semua ucapan hamba-hamba-Nya (lagi Maha Mengetahui) perbuatan-perbuatan mereka.",[["وَمِنَ","And among"],["ٱلْأَعْرَابِ","the bedouins"],["مَن","(is he) who"],["يَتَّخِذُ","takes"],["مَا","what"],["يُنفِقُ","he spends"],["مَغْرَمًۭا","(as) a loss"],["وَيَتَرَبَّصُ","and he awaits"],["بِكُمُ","for you"],["ٱلدَّوَآئِرَ ۚ","the turns (of misfortune)"],["عَلَيْهِمْ","Upon them"],["دَآئِرَةُ","(will be) the turn"],["ٱلسَّوْءِ ۗ","(of) the evil"],["وَٱللَّهُ","And Allah"],["سَمِيعٌ","(is) All-Hearer"],["عَلِيمٌۭ","All-Knower"]]],"1334":["(Dan di antara orang-orang Arab badui itu ada orang-orang yang beriman kepada Allah dan hari kemudian) seperti kabilah Juhainah dan kabilah Muzayyanah (dan menjadikan apa yang ia infakkan) di jalan Allah (sebagai amal taqarrub) maksudnya mendekatkan diri kepada-Nya (di sisi Allah dan) sebagai jalan untuk (memperoleh selawat) yakni doa-doa (Rasul) kepadanya. (Ketahuilah, sesungguhnya nafkah itu) artinya nafkah mereka itu (merupakan amal taqarrub) dapat dibaca qurubaatun dan dapat pula dibaca qurbatun (bagi mereka) di sisi-Nya. (Kelak Allah akan memasukkan mereka ke dalam rahmat-Nya) yaitu surga-Nya. (Sesungguhnya Allah Maha Pengampun) kepada orang-orang yang taat kepada-Nya (lagi Maha Penyayang) terhadap mereka yang taat.",[["وَمِنَ","But among"],["ٱلْأَعْرَابِ","the bedouins"],["مَن","(is he) who"],["يُؤْمِنُ","believes"],["بِٱللَّهِ","in Allah"],["وَٱلْيَوْمِ","and the Day"],["ٱلْـَٔاخِرِ","the Last"],["وَيَتَّخِذُ","and takes"],["مَا","what"],["يُنفِقُ","he spends"],["قُرُبَـٰتٍ","(as) means of nearness"],["عِندَ","with"],["ٱللَّهِ","Allah"],["وَصَلَوَٰتِ","and blessings"],["ٱلرَّسُولِ ۚ","(of) the Messenger"],["أَلَآ","Behold"],["إِنَّهَا","Indeed, it"],["قُرْبَةٌۭ","(is) a means of nearness"],["لَّهُمْ ۚ","for them"],["سَيُدْخِلُهُمُ","Allah will admit them"],["ٱللَّهُ","Allah will admit them"],["فِى","to"],["رَحْمَتِهِۦٓ ۗ","His Mercy"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"1335":["(Orang-orang yang terdahulu lagi yang pertama-tama masuk Islam di antara orang-orang Muhajirin dan Ansar) mereka adalah para sahabat yang ikut perang Badar atau yang dimaksud adalah semua para sahabat (dan orang-orang yang mengikuti mereka) sampai hari kiamat (dengan baik) dalam hal amal perbuatannya. (Allah rida kepada mereka) melalui ketaatan mereka kepada-Nya (dan mereka pun rida kepada Allah) rida akan pahala-Nya (dan Allah menyediakan bagi mereka surga-surga yang mengalir sungai-sungai di bawahnya) menurut suatu qiraat lafal tahtahaa dibaca dengan memakai huruf min sebelumnya sehingga bacaannya menjadi min tahtihaa (mereka kekal di dalamnya selama-lamanya. Itulah kemenangan yang besar).",[["وَٱلسَّـٰبِقُونَ","And the forerunners"],["ٱلْأَوَّلُونَ","the first"],["مِنَ","among"],["ٱلْمُهَـٰجِرِينَ","the emigrants"],["وَٱلْأَنصَارِ","and the helpers"],["وَٱلَّذِينَ","and those who"],["ٱتَّبَعُوهُم","followed them"],["بِإِحْسَـٰنٍۢ","in righteousness"],["رَّضِىَ","Allah is pleased"],["ٱللَّهُ","Allah is pleased"],["عَنْهُمْ","with them"],["وَرَضُوا۟","and they are pleased"],["عَنْهُ","with Him"],["وَأَعَدَّ","And He has prepared"],["لَهُمْ","for them"],["جَنَّـٰتٍۢ","Gardens"],["تَجْرِى","flows"],["تَحْتَهَا","underneath it"],["ٱلْأَنْهَـٰرُ","the rivers"],["خَـٰلِدِينَ","will abide"],["فِيهَآ","in it"],["أَبَدًۭا ۚ","forever"],["ذَٰلِكَ","That"],["ٱلْفَوْزُ","(is) the success"],["ٱلْعَظِيمُ","the great"]]],"1336":["(Di antara orang-orang yang di sekeliling kalian) hai penduduk Madinah (dari kalangan orang-orang Arab badui ada orang-orang munafik) seperti orang-orang kabilah Aslam, kabilah Asyja` dan kabilah Ghiffar (dan juga di antara penduduk Madinah) ada orang-orang munafik pula. (Mereka keterlaluan dalam kemunafikannya) artinya kemunafikan mereka telah mendalam dan sudah mengakar di hati mereka. (Kamu tidak mengetahui mereka) hai Muhammad (tetapi Kamilah yang mengetahui mereka. Nanti mereka akan Kami siksa dua kali) dengan terungkapnya kemunafikan mereka, atau dibunuh di dunia dan disiksa di alam kubur (kemudian mereka akan dikembalikan) di akhirat nanti (kepada azab yang besar) yaitu siksa neraka.",[["وَمِمَّنْ","And among those"],["حَوْلَكُم","around you"],["مِّنَ","of"],["ٱلْأَعْرَابِ","the bedouins"],["مُنَـٰفِقُونَ ۖ","(are) hypocrites"],["وَمِنْ","and (also) from"],["أَهْلِ","people"],["ٱلْمَدِينَةِ ۖ","(of) the Madinah"],["مَرَدُوا۟","They persist"],["عَلَى","in"],["ٱلنِّفَاقِ","the hypocrisy"],["لَا","not"],["تَعْلَمُهُمْ ۖ","you know them"],["نَحْنُ","We"],["نَعْلَمُهُمْ ۚ","[We] know them"],["سَنُعَذِّبُهُم","We will punish them"],["مَّرَّتَيْنِ","twice"],["ثُمَّ","then"],["يُرَدُّونَ","they will be returned"],["إِلَىٰ","to"],["عَذَابٍ","a punishment"],["عَظِيمٍۢ","great"]]],"1337":["(Dan) ada pula suatu kaum (yang lain) lafal ayat ini menjadi mubtada (mereka mengakui dosa-dosa mereka) karena tidak ikut berangkat ke medan perang. Lafal ayat ini menjadi khabarnya (mereka mencampur-baurkan pekerjaan yang baik) yaitu jihad yang telah mereka lakukan sebelum peristiwa ini atau pengakuan mereka atas dosa-dosa yang telah mereka lakukan; atau dosa-dosa yang lainnya (dengan pekerjaan lain yang buruk) yaitu ketidakikutan mereka dalam berjihad kali ini. (Mudah-mudahan Allah menerima tobat mereka. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang). Ayat ini diturunkan berkenaan dengan apa yang dilakukan oleh Abu Lubabah dan segolongan orang-orang lainnya. Mereka mengikatkan diri mereka di tiang-tiang mesjid, hal ini mereka lakukan ketika mereka mendengar firman Allah swt. yang diturunkan berkenaan dengan orang-orang yang tidak berangkat berjihad, sedangkan mereka tidak ikut berangkat. Lalu mereka bersumpah bahwa ikatan mereka itu tidak akan dibuka melainkan oleh Nabi saw. sendiri. Kemudian setelah ayat ini diturunkan Nabi saw. melepaskan ikatan mereka.",[["وَءَاخَرُونَ","And others"],["ٱعْتَرَفُوا۟","(who have) acknowledged"],["بِذُنُوبِهِمْ","their sins"],["خَلَطُوا۟","They had mixed"],["عَمَلًۭا","a deed"],["صَـٰلِحًۭا","righteous"],["وَءَاخَرَ","(with) other"],["سَيِّئًا","(that was) evil"],["عَسَى","Perhaps"],["ٱللَّهُ","Allah"],["أَن","[that]"],["يَتُوبَ","will turn (in mercy)"],["عَلَيْهِمْ ۚ","to them"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌ","Most Merciful"]]],"1338":["(Ambillah sedekah dari sebagian harta mereka, dengan sedekah itu kamu membersihkan dan menyucikan mereka) dari dosa-dosa mereka, maka Nabi saw. mengambil sepertiga harta mereka kemudian menyedekahkannya (dan berdoalah untuk mereka). (Sesungguhnya doa kamu itu menjadi ketenangan jiwa) rahmat (bagi mereka) menurut suatu pendapat yang dimaksud dengan sakanun ialah ketenangan batin lantaran tobat mereka diterima. (Dan Allah Maha Mendengar lagi Maha Mengetahui).",[["خُذْ","Take"],["مِنْ","from"],["أَمْوَٰلِهِمْ","their wealth"],["صَدَقَةًۭ","a charity"],["تُطَهِّرُهُمْ","purifying them"],["وَتُزَكِّيهِم","and cause them increase"],["بِهَا","by it"],["وَصَلِّ","and bless"],["عَلَيْهِمْ ۖ","[upon] them"],["إِنَّ","Indeed"],["صَلَوٰتَكَ","your blessings"],["سَكَنٌۭ","(are a) reassurance"],["لَّهُمْ ۗ","for them"],["وَٱللَّهُ","And Allah"],["سَمِيعٌ","(is) All-Hearer"],["عَلِيمٌ","All-Knower"]]],"1339":["(Tidakkah mereka mengetahui bahwasanya Allah menerima tobat dari hamba-hamba-Nya dan mengambil) maksudnya menerima (zakat dan bahwasanya Allah Maha Penerima tobat) hamba-hamba-Nya, yakni dengan menerima tobat mereka (lagi Maha Penyayang) kepada mereka. Kata tanya pada awal ayat ini bermakna taqrir; pengertian yang dimaksud ialah untuk menggugah mereka agar mau bertobat dan berzakat atau bersedekah.",[["أَلَمْ","Do not"],["يَعْلَمُوٓا۟","they know"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["هُوَ","(is) He"],["يَقْبَلُ","(Who) accepts"],["ٱلتَّوْبَةَ","the repentance"],["عَنْ","from"],["عِبَادِهِۦ","His slaves"],["وَيَأْخُذُ","and takes"],["ٱلصَّدَقَـٰتِ","the charities"],["وَأَنَّ","and that"],["ٱللَّهَ","Allah"],["هُوَ","He"],["ٱلتَّوَّابُ","(is) the Acceptor of repentance"],["ٱلرَّحِيمُ","the Most Merciful"]]],"1340":["(Dan katakanlah) kepada mereka atau kepada manusia secara umum (\"Bekerjalah kalian) sesuka hati kalian (maka Allah dan Rasul-Nya serta orang-orang mukmin akan melihat pekerjaan kalian itu dan kalian akan dikembalikan) melalui dibangkitkan dari kubur (kepada Yang Mengetahui alam gaib dan alam nyata) yakni Allah (lalu diberikan-Nya kepada kalian apa yang telah kalian kerjakan.\") lalu Dia akan membalasnya kepada kalian.",[["وَقُلِ","And say"],["ٱعْمَلُوا۟","Do"],["فَسَيَرَى","then Allah will see"],["ٱللَّهُ","then Allah will see"],["عَمَلَكُمْ","your deed"],["وَرَسُولُهُۥ","and His Messenger"],["وَٱلْمُؤْمِنُونَ ۖ","and the believers"],["وَسَتُرَدُّونَ","And you will be brought back"],["إِلَىٰ","to"],["عَـٰلِمِ","(the) Knower"],["ٱلْغَيْبِ","(of) the unseen"],["وَٱلشَّهَـٰدَةِ","and the seen"],["فَيُنَبِّئُكُم","then He will inform you"],["بِمَا","of what"],["كُنتُمْ","you used (to)"],["تَعْمَلُونَ","do"]]],"1341":["(Dan ada pula orang-orang lain) di antara orang-orang yang tidak berangkat ke medan perang (yang ditangguhkan) dapat dibaca murjauna dan dapat pula dibaca murja'uuna; artinya tobat mereka ditangguhkan (sampai ada keputusan Allah) tentang perihal mereka sesuai dengan kehendak-Nya (adakalanya Allah akan mengazab mereka) seumpamanya mereka dimatikan oleh Allah tanpa sempat bertobat (dan adakalanya Allah akan menerima tobat mereka. Dan Allah Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) di dalam melakukan apa yang harus Ia lakukan terhadap mereka. Yang dimaksud dengan mereka ialah ketiga orang yang kedatangannya kepada Nabi saw. telah disebutkan tadi, mereka adalah Murarah bin Rabi', Kaab bin Malik dan Hilal bin Umayyah. Mereka tidak berangkat ke medan perang hanya karena malas dan cenderung kepada hidup yang serba santai dan enak, bukannya karena munafik. Dan mereka tidak mengemukakan uzurnya (alasannya) kepada Nabi saw. seperti halnya yang dilakukan oleh orang-orang lain. Akhirnya perihal mereka ditangguhkan selama lima puluh hari, selama itu mereka hidup diasingkan oleh semuanya sehingga turunlah ayat yang menjelaskan diterimanya tobat mereka.",[["وَءَاخَرُونَ","And others"],["مُرْجَوْنَ","deferred"],["لِأَمْرِ","for the Command of Allah "],["ٱللَّهِ","for the Command of Allah "],["إِمَّا","whether"],["يُعَذِّبُهُمْ","He will punish them"],["وَإِمَّا","or"],["يَتُوبُ","He will turn (in mercy)"],["عَلَيْهِمْ ۗ","to them"],["وَٱللَّهُ","And Allah"],["عَلِيمٌ","(is) All-Knower"],["حَكِيمٌۭ","All-Wise"]]],"1342":["(Dan) di antara mereka yang munafik itu (ada orang-orang yang mendirikan mesjid) jumlah mereka ada dua belas orang, semuanya orang-orang munafik (untuk menimbulkan kemudaratan) kepada orang-orang mukmin di mesjid Quba (dan karena kekafiran) karena mereka membangun mesjid itu berdasarkan perintah dari Abu Amir seorang rahib, dimaksud supaya menjadi basis pangkalan baginya dan bagi orang-orang yang berpihak kepadanya. Sedang ia (Amir) pergi untuk mendatangkan bala tentara Kaisar Romawi guna memerangi Nabi saw. (dan untuk memecah belah antara orang-orang mukmin) yang biasa salat di mesjid Quba, diharapkan sebagian dari orang-orang mukmin melakukan salat di mesjid mereka (serta menjadi tempat pemantauan) yakni tempat untuk memantau (bagi orang-orang yang memerangi Allah dan Rasul-Nya sejak dahulu) sebelum mesjid dhirar ini dibangun; yang dimaksud adalah Abu Amir tadi dan para pembantunya. (Mereka sesungguhnya bersumpah, \"Tiada lain) (kami menghendaki) dari pembangunan mesjid ini (hanyalah) untuk pekerjaan (yang baik semata.\") yaitu berlaku belas-kasihan terhadap orang-orang miskin dalam musim hujan dan musim panas, serta memberikan tempat persinggahan bagi kaum Muslimin. (Dan Allah menjadi saksi bahwa sesungguhnya mereka itu adalah pendusta) dalam sumpahnya. Mereka pernah meminta kepada Nabi saw. supaya melakukan salat di dalam mesjidnya itu, akan tetapi kemudian turunlah firman Allah berikut ini, yaitu:",[["وَٱلَّذِينَ","And those who"],["ٱتَّخَذُوا۟","take"],["مَسْجِدًۭا","a masjid"],["ضِرَارًۭا","(for causing) harm"],["وَكُفْرًۭا","and (for) disbelief"],["وَتَفْرِيقًۢا","and (for) division"],["بَيْنَ","among"],["ٱلْمُؤْمِنِينَ","the believers"],["وَإِرْصَادًۭا","and (as) a station"],["لِّمَنْ","for whoever"],["حَارَبَ","warred"],["ٱللَّهَ","(against) Allah"],["وَرَسُولَهُۥ","and His Messenger"],["مِن","before"],["قَبْلُ ۚ","before"],["وَلَيَحْلِفُنَّ","And surely they will swear"],["إِنْ","Not"],["أَرَدْنَآ","we wish"],["إِلَّا","except"],["ٱلْحُسْنَىٰ ۖ","the good"],["وَٱللَّهُ","But Allah"],["يَشْهَدُ","bears witness"],["إِنَّهُمْ","indeed, they"],["لَكَـٰذِبُونَ","(are) surely liars"]]],"1343":["(Janganlah kamu berdiri) melakukan salat (dalam mesjid itu selama-lamanya) kemudian Nabi saw. mengirimkan segolongan para sahabatnya guna merobohkan dan membakarnya. Kemudian mereka menjadikan bekas mesjid itu sebagai tempat pembuangan bangkai. (Sesungguhnya mesjid yang didirikan) dibangun dengan berlandaskan kepada pondasi (takwa, sejak hari pertama) yaitu mesjid yang didirikan oleh Nabi saw. sewaktu pertama kali beliau menginjakkan kakinya di tempat hijrahnya itu, yang dimaksud adalah mesjid Quba. Demikianlah menurut penjelasan yang telah dikemukakan oleh Imam Bukhari (adalah lebih berhak) daripada mesjid dhirar itu (kamu salat) untuk melakukan salat (di dalamnya. Di dalamnya ada orang-orang) kaum Ansar (yang ingin membersihkan diri. Dan Allah menyukai orang-orang yang bersih) artinya, Allah akan memberikan pahala kepada mereka. Lafal al-muththahhiriina asalnya ialah al-mutathahhiriina kemudian huruf ta diidgamkan kepada huruf tha yang asal, kemudian jadilah al-muththahhiriina. Ibnu Khuzaimah di dalam kitab sahihnya telah meriwayatkan sebuah hadis melalui Uwaimir bin Saidah, bahwasanya pada suatu hari Nabi saw. mendatangi mereka (para sahabat) di mesjid Quba. Kemudian beliau bersabda, \"Sesungguhnya Allah swt. telah memuji kalian dengan baik atas pembersihan diri kalian sehubungan dengan kisah mesjid kalian ini (Quba). Maka cara pembersihan apakah yang sedang kalian lakukan sekarang ini?\" Mereka menjawab, \"Demi Allah, wahai Rasulullah, kami tidak mengetahui apa-apa melainkan kami mempunyai tetangga-tetangga Yahudi; mereka lalu membasuh dubur mereka setelah buang air besar, maka kami pun melakukan pembasuhan seperti apa yang mereka lakukan.\" Menurut hadis yang lain, yang telah diriwayatkan oleh Imam Bazzar disebutkan bahwa para sahabat mengatakan, \"Akan tetapi kami memakai batu terlebih dahulu, kemudian baru kami memakai air.\" Maka Nabi saw. menjawab, \"Itulah yang benar, maka peganglah cara ini oleh kalian.\"",[["لَا","(Do) not"],["تَقُمْ","stand"],["فِيهِ","in it"],["أَبَدًۭا ۚ","ever"],["لَّمَسْجِدٌ","A masjid"],["أُسِّسَ","founded"],["عَلَى","on"],["ٱلتَّقْوَىٰ","the righteousness"],["مِنْ","from"],["أَوَّلِ","(the) first"],["يَوْمٍ","day"],["أَحَقُّ","(is) more worthy"],["أَن","that"],["تَقُومَ","you stand"],["فِيهِ ۚ","in it"],["فِيهِ","Within it"],["رِجَالٌۭ","(are) men"],["يُحِبُّونَ","who love"],["أَن","to"],["يَتَطَهَّرُوا۟ ۚ","purify themselves"],["وَٱللَّهُ","and Allah"],["يُحِبُّ","loves"],["ٱلْمُطَّهِّرِينَ","the ones who purify themselves"]]],"1344":["(Maka apakah orang-orang yang mendirikan mesjidnya di atas dasar takwa) karena takut (kepada Allah dan) selalu mengharapkan (keridaan)-Nya itu (yang lebih baik, ataukah orang-orang yang mendirikan bangunannya di tepi) dapat dibaca jurufin dan dapat pula dibaca jurfin, artinya di pinggir (jurang) yakni hampir roboh (lalu bangunannya itu jatuh bersama-sama dengan dia) maksudnya bangunannya roboh berikut orang-orang yang membangunnya (ke dalam neraka Jahanam?) ungkapan ayat ini merupakan tamtsil/perumpamaan yang paling baik, yaitu menggambarkan pembangunan mesjid yang berdasarkan bukan kepada takwa, kemudian akibat-akibat yang akan dialaminya. Kata tanya pada permulaan ayat ini mengandung makna taqrir, artinya mesjid pertamalah yang baik seperti halnya mesjid Quba. Sedangkan gambaran yang kedua adalah perumpamaan mesjid dhirar. (Dan Allah tidak memberikan petunjuk kepada orang-orang yang lalim).",[["أَفَمَنْ","Then is (one) who"],["أَسَّسَ","founded"],["بُنْيَـٰنَهُۥ","his building"],["عَلَىٰ","on"],["تَقْوَىٰ","righteousness"],["مِنَ","from"],["ٱللَّهِ","Allah"],["وَرِضْوَٰنٍ","and (His) pleasure"],["خَيْرٌ","better"],["أَم","or"],["مَّنْ","(one) who"],["أَسَّسَ","founded"],["بُنْيَـٰنَهُۥ","his building"],["عَلَىٰ","on"],["شَفَا","edge"],["جُرُفٍ","(of) a cliff"],["هَارٍۢ","(about to) collapse"],["فَٱنْهَارَ","so it collapsed"],["بِهِۦ","with him"],["فِى","in"],["نَارِ","(the) Fire"],["جَهَنَّمَ ۗ","(of) Hell"],["وَٱللَّهُ","And Allah"],["لَا","(does) not"],["يَهْدِى","guide"],["ٱلْقَوْمَ","the wrongdoing people"],["ٱلظَّـٰلِمِينَ","the wrongdoing people"]]],"1345":["(Bangunan-bangunan yang mereka dirikan itu senantiasa menjadi pangkal keraguan) yakni keragu-raguan (dalam hati mereka kecuali bila telah hancur) tercabik-cabik (hati mereka itu) lantaran mereka mati. (Dan Allah Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) dalam perlakuan-Nya terhadap makhluk-Nya.",[["لَا","Not"],["يَزَالُ","(will) cease"],["بُنْيَـٰنُهُمُ","their building"],["ٱلَّذِى","which"],["بَنَوْا۟","they built"],["رِيبَةًۭ","a (cause of) doubt"],["فِى","in"],["قُلُوبِهِمْ","their hearts"],["إِلَّآ","except"],["أَن","that"],["تَقَطَّعَ","(are) cut into pieces"],["قُلُوبُهُمْ ۗ","their hearts"],["وَٱللَّهُ","And Allah"],["عَلِيمٌ","(is) All-Knower"],["حَكِيمٌ","All-Wise"]]],"1346":["(Sesungguhnya Allah telah membeli dari orang-orang mukmin diri dan harta mereka) lantaran mereka menginfakkannya di jalan ketaatan kepada-Nya, seperti untuk berjuang di jalan-Nya (dengan memberikan surga untuk mereka. Mereka berperang pada jalan Allah lalu mereka membunuh atau dibunuh) ayat ini merupakan kalimat baru yang menjadi penafsir bagi makna yang terkandung di dalam lafal fa yuqtaluuna wa yaqtuluuna, artinya sebagian dari mereka ada yang gugur dan sebagian yang lain meneruskan pertempurannya (sebagai janji yang benar) lafal wa`dan dan haqqan keduanya berbentuk mashdar yang dinashabkan fi`ilnya masing-masing yang tidak disebutkan (di dalam Taurat, Injil dan Alquran?) artinya tiada seorang pun yang lebih menepati janjinya selain dari Allah. (Maka bergembiralah) dalam ayat ini terkandung pengertian iltifat/perpindahan pembicaraan dari gaib kepada mukhathab/dari orang ketiga kepada orang kedua (dengan jual-beli yang telah kalian lakukan itu dan yang demikian itu) yaitu jual-beli itu (adalah kemenangan yang besar) yang dapat mengantarkan kepada tujuan yang paling didambakan.",[["۞ إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["ٱشْتَرَىٰ","(has) purchased"],["مِنَ","from"],["ٱلْمُؤْمِنِينَ","the believers"],["أَنفُسَهُمْ","their lives"],["وَأَمْوَٰلَهُم","and their wealth"],["بِأَنَّ","because"],["لَهُمُ","for them"],["ٱلْجَنَّةَ ۚ","(is) Paradise"],["يُقَـٰتِلُونَ","They fight"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["فَيَقْتُلُونَ","they slay"],["وَيُقْتَلُونَ ۖ","and they are slain"],["وَعْدًا","A promise"],["عَلَيْهِ","upon Him"],["حَقًّۭا","true"],["فِى","in"],["ٱلتَّوْرَىٰةِ","the Taurat"],["وَٱلْإِنجِيلِ","and the Injeel"],["وَٱلْقُرْءَانِ ۚ","and the Quran"],["وَمَنْ","And who"],["أَوْفَىٰ","(is) more faithful"],["بِعَهْدِهِۦ","to his promise"],["مِنَ","than"],["ٱللَّهِ ۚ","Allah"],["فَٱسْتَبْشِرُوا۟","So rejoice"],["بِبَيْعِكُمُ","in your transaction"],["ٱلَّذِى","which"],["بَايَعْتُم","you have contracted"],["بِهِۦ ۚ","[with it]"],["وَذَٰلِكَ","And that"],["هُوَ","it"],["ٱلْفَوْزُ","(is) the success"],["ٱلْعَظِيمُ","the great"]]],"1347":["(Mereka itu adalah orang-orang yang bertobat) lafal at-taa'ibuuna dirafa'kan untuk tujuan memuji, yaitu dengan memperkirakan adanya mubtada sebelumnya; artinya mereka itu adalah orang-orang yang bertobat dari kemusyrikan dan kemunafikan (yang beribadah) orang-orang yang ikhlas karena Allah dalam beribadah (yang memuji) kepada Allah dalam semua kondisi (yang melawat) makna yang dimaksud adalah mereka selalu mengerjakan shaum/puasa (yang rukuk, yang sujud) artinya mereka adalah orang-orang yang salat (yang menyuruh berbuat makruf dan mencegah berbuat mungkar dan yang memelihara batasan-batasan Allah) yakni hukum-hukum-Nya dengan cara mengamalkannya. (Dan gembirakanlah orang-orang mukmin itu) dengan surga.",[["ٱلتَّـٰٓئِبُونَ","Those who turn in repentance"],["ٱلْعَـٰبِدُونَ","those who worship"],["ٱلْحَـٰمِدُونَ","those who praise"],["ٱلسَّـٰٓئِحُونَ","those who go out"],["ٱلرَّٰكِعُونَ","those who bow down"],["ٱلسَّـٰجِدُونَ","those who prostrate"],["ٱلْـَٔامِرُونَ","those who enjoin"],["بِٱلْمَعْرُوفِ","the right"],["وَٱلنَّاهُونَ","and those who forbid"],["عَنِ","[on]"],["ٱلْمُنكَرِ","the wrong"],["وَٱلْحَـٰفِظُونَ","and those who observe"],["لِحُدُودِ","(the) limits"],["ٱللَّهِ ۗ","(of) Allah"],["وَبَشِّرِ","And give glad tidings"],["ٱلْمُؤْمِنِينَ","(to) the believers"]]],"1348":["Ayat ini diturunkan berkenaan dengan permohonan ampunan Nabi saw. buat pamannya, yaitu Abu Thalib dan sekaligus berkenaan pula dengan permohonan ampunan sebagian para sahabat terhadap kedua orang-orang tua mereka masing-masing yang musyrik. (Tiadalah sepatutnya bagi Nabi dan orang-orang yang beriman memintakan ampun kepada Allah bagi orang-orang musyrik walaupun orang-orang musyrik itu kaum kerabat)nya, yakni familinya sendiri (sesudah jelas bagi mereka bahwasanya orang-orang yang musyrik itu adalah penghuni-penghuni Jahim) yakni neraka, lantaran mereka mati dalam keadaan kafir.",[["مَا","Not"],["كَانَ","(it) is"],["لِلنَّبِىِّ","for the Prophet"],["وَٱلَّذِينَ","and those who"],["ءَامَنُوٓا۟","believe"],["أَن","that"],["يَسْتَغْفِرُوا۟","they ask forgiveness"],["لِلْمُشْرِكِينَ","for the polytheists"],["وَلَوْ","even though"],["كَانُوٓا۟","they be"],["أُو۟لِى","near of kin"],["قُرْبَىٰ","near of kin"],["مِنۢ","after"],["بَعْدِ","after"],["مَا","[what]"],["تَبَيَّنَ","has become clear"],["لَهُمْ","to them"],["أَنَّهُمْ","that they"],["أَصْحَـٰبُ","(are the) companions"],["ٱلْجَحِيمِ","(of) the Hellfire"]]],"1349":["(Dan permintaan ampun dari Ibrahim kepada Allah untuk bapaknya (pamannya) tidak lain hanya karena suatu janji yang telah diikrarkannya kepada bapaknya itu) melalui perkataan Nabi Ibrahim sendiri, seperti apa yang diungkapkan oleh firman-Nya, \"Aku akan mintakan ampun bagimu kepada Rabbku.\" (Q.S. Maryam 47) Nabi Ibrahim menjanjikan demikian dengan harapan semoga bapak (paman)nya itu mau masuk Islam. (Maka tatkala jelas bagi Ibrahim bahwa bapaknya/pamannya itu adalah musuh Allah) lantaran ia mati dalam keadaan kafir (maka Ibrahim berlepas diri daripadanya) kemudian Nabi Ibrahim berhenti dari memintakan ampunannya. (Sesungguhnya Ibrahim adalah seorang yang sangat lembut) banyak merendahkan diri dan berdoa kepada Allah (lagi penyantun) sangat sabar di dalam menahan derita.",[["وَمَا","And not"],["كَانَ","was"],["ٱسْتِغْفَارُ","(the) asking of forgiveness"],["إِبْرَٰهِيمَ","(by) Ibrahim"],["لِأَبِيهِ","for his father"],["إِلَّا","except"],["عَن","because"],["مَّوْعِدَةٍۢ","(of) a promise"],["وَعَدَهَآ","he had promised it"],["إِيَّاهُ","(to) him"],["فَلَمَّا","But when"],["تَبَيَّنَ","it became clear"],["لَهُۥٓ","to him"],["أَنَّهُۥ","that he"],["عَدُوٌّۭ","(was) an enemy"],["لِّلَّهِ","to Allah"],["تَبَرَّأَ","he disassociated"],["مِنْهُ ۚ","from him"],["إِنَّ","Indeed"],["إِبْرَٰهِيمَ","Ibrahim"],["لَأَوَّٰهٌ","(was) compassionate"],["حَلِيمٌۭ","forbearing"]]],"1350":["(Dan Allah sekali-kali tidak akan menyesatkan suatu kaum, sesudah Allah memberi petunjuk kepada mereka) kepada Islam (hingga dijelaskan-Nya kepada mereka apa yang harus mereka jauhi) yakni amal-amal perbuatan mana saja yang harus mereka jauhi, akan tetapi ternyata mereka tidak menjauhinya, maka mereka layak menjadi orang-orang yang disesatkan. (Sesungguhnya Allah Maha Mengetahui segala sesuatu) antara lain ialah mengetahui siapa yang berhak untuk disesatkan dan siapa yang berhak untuk mendapat hidayah-Nya.",[["وَمَا","And not"],["كَانَ","is"],["ٱللَّهُ","(for) Allah"],["لِيُضِلَّ","that He lets go astray"],["قَوْمًۢا","a people"],["بَعْدَ","after"],["إِذْ","[when]"],["هَدَىٰهُمْ","He has guided them"],["حَتَّىٰ","until"],["يُبَيِّنَ","He makes clear"],["لَهُم","to them"],["مَّا","what"],["يَتَّقُونَ ۚ","they should fear"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["بِكُلِّ","(of) every"],["شَىْءٍ","thing"],["عَلِيمٌ","(is) All-Knower"]]],"1351":["(Sesungguhnya kepunyaan Allahlah kerajaan langit dan bumi. Dia menghidupkan dan mematikan. Dan sekali-kali tiada bagi kalian) hai umat manusia (selain dari Allah) (yang melindungi) kalian daripada-Nya (dan yang memberikan pertolongan) yang dapat mencegah diri kalian dari kepastian Allah.",[["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَهُۥ","to Him (belongs)"],["مُلْكُ","the dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ ۖ","and the earth"],["يُحْىِۦ","He gives life"],["وَيُمِيتُ ۚ","and He causes death"],["وَمَا","And not"],["لَكُم","for you"],["مِّن","besides Allah"],["دُونِ","besides Allah"],["ٱللَّهِ","besides Allah"],["مِن","any"],["وَلِىٍّۢ","protector"],["وَلَا","and not"],["نَصِيرٍۢ","any helper"]]],"1352":["(Sesungguhnya Allah telah menerima tobat) artinya Dia menerima tobat untuk selamanya (Nabi, orang-orang Muhajirin dan orang-orang Ansar yang mengikuti Nabi dalam masa kesulitan) yakni sewaktu keadaan sedang sulit-sulitnya. Hal ini terjadi sewaktu perang Tabuk; sebiji buah kurma dimakan oleh dua orang, dan sepuluh orang pasukan saling bergantian menaiki satu hewan kendaraan di antara sesama mereka, dan panas pada saat itu terik sekali sehingga mereka meminum air yang ada dalam perut unta karena persediaan air habis (setelah hampir berpaling) dapat dibaca yaziighu atau taziighu, artinya cenderung (hati segolongan dari mereka) dari mengikuti Nabi kemudian mereka bermaksud untuk kembali dan tidak ikut berperang lantaran kesulitan yang sedang mereka alami pada saat itu (kemudian Allah menerima tobat mereka itu) dengan memberikan keteguhan dan kesabaran kepada mereka. (Sesungguhnya Allah Maha Pengasih lagi Maha Penyayang).",[["لَّقَد","Verily"],["تَّابَ","Allah turned (in mercy)"],["ٱللَّهُ","Allah turned (in mercy)"],["عَلَى","to"],["ٱلنَّبِىِّ","the Prophet"],["وَٱلْمُهَـٰجِرِينَ","and the emigrants"],["وَٱلْأَنصَارِ","and the helpers"],["ٱلَّذِينَ","[those] who"],["ٱتَّبَعُوهُ","followed him"],["فِى","in"],["سَاعَةِ","(the) hour"],["ٱلْعُسْرَةِ","(of) difficulty"],["مِنۢ","after"],["بَعْدِ","after"],["مَا","[what]"],["كَادَ","had nearly"],["يَزِيغُ","deviated"],["قُلُوبُ","(the) hearts"],["فَرِيقٍۢ","(of) a party"],["مِّنْهُمْ","of them"],["ثُمَّ","then"],["تَابَ","He turned (in mercy)"],["عَلَيْهِمْ ۚ","to them"],["إِنَّهُۥ","Indeed, He"],["بِهِمْ","to them"],["رَءُوفٌۭ","(is) Most Kind"],["رَّحِيمٌۭ","Most Merciful"]]],"1353":["(Dan) Allah menerima tobat pula (terhadap tiga orang yang ditangguhkan) penerimaan tobat mereka melalui bukti yang menunjukkan hal itu (sehingga apabila bumi terasa sempit oleh mereka padahal bumi itu luas) sekalipun kenyataannya bumi itu luas lantaran mereka tidak dapat menemukan tempat yang dapat mengganti hati mereka (dan jika hati mereka pun terasa sempit pula) yakni hati mereka menjadi sempit lantaran susah dan asing disebabkan tobat mereka ditangguhkan penerimaannya sehingga hati mereka tidak gembira dan selalu tidak tenteram (serta mereka menduga) dan merasa yakin (bahwasanya) dibaca dengan takhfif, yaitu an (tidak ada tempat lari dari siksa Allah melainkan kepada-Nya saja. Kemudian Allah menerima tobat mereka) Allah memberikan taufik dan kekuatan kepada mereka untuk bertobat (agar mereka tetap dalam tobatnya. Sesungguhnya Allahlah Yang Maha Penerima tobat lagi Maha Penyayang).",[["وَعَلَى","And on"],["ٱلثَّلَـٰثَةِ","the three"],["ٱلَّذِينَ","(of) those who"],["خُلِّفُوا۟","were left behind"],["حَتَّىٰٓ","until"],["إِذَا","when"],["ضَاقَتْ","(was) straitened"],["عَلَيْهِمُ","for them"],["ٱلْأَرْضُ","the earth"],["بِمَا","though"],["رَحُبَتْ","it was vast"],["وَضَاقَتْ","And (was) straitened"],["عَلَيْهِمْ","for them"],["أَنفُسُهُمْ","their own souls"],["وَظَنُّوٓا۟","and they were certain"],["أَن","that"],["لَّا","(there is) no"],["مَلْجَأَ","refuge"],["مِنَ","from"],["ٱللَّهِ","Allah"],["إِلَّآ","except"],["إِلَيْهِ","to Him"],["ثُمَّ","Then"],["تَابَ","He turned (in mercy)"],["عَلَيْهِمْ","to them"],["لِيَتُوبُوٓا۟ ۚ","that they may repent"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["هُوَ","He"],["ٱلتَّوَّابُ","(is) the Acceptor of repentance"],["ٱلرَّحِيمُ","the Most Merciful"]]],"1354":["(Hai orang-orang yang beriman, bertakwalah kalian kepada Allah) dengan meninggalkan perbuatan-perbuatan maksiat (dan hendaklah kalian bersama orang-orang yang benar) dalam hal iman dan menepati janji untuk itu kalian harus menetapi kebenaran.",[["يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوا۟","O you who believe"],["ٱتَّقُوا۟","Fear"],["ٱللَّهَ","Allah"],["وَكُونُوا۟","and be"],["مَعَ","with"],["ٱلصَّـٰدِقِينَ","those who are truthful"]]],"1355":["(Tidaklah patut bagi penduduk Madinah dan orang-orang Arab badui yang berdiam di sekitarnya tidak turut menyertai Rasulullah) bilamana beliau pergi berperang (dan tidak patut pula bagi mereka lebih mencintai diri mereka daripada mencintai diri Rasul) yaitu dengan cara mendahulukan kepentingan apa yang menjadi keridaannya daripada kemaslahatan diri sendiri di dalam menghadapi saat-saat yang sulit. Ungkapan ayat ini merupakan nahi atau larangan, akan tetapi diungkapkan dalam bentuk kalimat khabar atau kalimat berita. (Yang demikian itu) yaitu larangan untuk tidak pergi bersama Rasulullah ke medan perang (ialah karena mereka) disebabkan (tidak ditimpa kehausan) rasa dahaga (kepayahan) keletihan (dan kelaparan) yakni rasa lapar (pada jalan Allah dan tidak pula menginjak suatu tempat) lafal mauthi'an adalah mashdar akan tetapi maknanya sama dengan lafal wath'an (yang membangkitkan amarah) artinya yang membuat marah (orang-orang kafir dan tidak menimpakan kepada musuh) Allah (sesuatu bencana) membunuh, menawan atau membegal musuh (melainkan dituliskan bagi mereka dengan yang demikian itu suatu amal saleh) dimaksud supaya mereka mau melaksanakan hal tersebut. (Sesungguhnya Allah tidak menyia-nyiakan pahala orang-orang yang berbuat baik) pahala mereka tidak akan disia-siakan-Nya, bahkan Dia akan memberi mereka pahala.",[["مَا","Not"],["كَانَ","it was"],["لِأَهْلِ","(for) the people"],["ٱلْمَدِينَةِ","of the Madinah"],["وَمَنْ","and who"],["حَوْلَهُم","were around them"],["مِّنَ","of"],["ٱلْأَعْرَابِ","the bedouins"],["أَن","that"],["يَتَخَلَّفُوا۟","they remain behind"],["عَن","after"],["رَّسُولِ","the Messenger"],["ٱللَّهِ","of Allah"],["وَلَا","and not"],["يَرْغَبُوا۟","they prefer"],["بِأَنفُسِهِمْ","their lives"],["عَن","to"],["نَّفْسِهِۦ ۚ","his life"],["ذَٰلِكَ","That is"],["بِأَنَّهُمْ","because [they]"],["لَا","(does) not"],["يُصِيبُهُمْ","afflict them"],["ظَمَأٌۭ","thirst"],["وَلَا","and not"],["نَصَبٌۭ","fatigue"],["وَلَا","and not"],["مَخْمَصَةٌۭ","hunger"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["وَلَا","and not"],["يَطَـُٔونَ","they step"],["مَوْطِئًۭا","any step"],["يَغِيظُ","that angers"],["ٱلْكُفَّارَ","the disbelievers"],["وَلَا","and not"],["يَنَالُونَ","they inflict"],["مِنْ","on"],["عَدُوٍّۢ","an enemy"],["نَّيْلًا","an infliction"],["إِلَّا","except"],["كُتِبَ","is recorded"],["لَهُم","for them"],["بِهِۦ","in it"],["عَمَلٌۭ","(as) a deed"],["صَـٰلِحٌ ۚ","righteous"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يُضِيعُ","allow to be lost"],["أَجْرَ","the reward"],["ٱلْمُحْسِنِينَ","(of) the good-doers"]]],"1356":["(Dan mereka tiada menafkahkan) dalam rangka melaksanakan hal tersebut (suatu nafkah yang kecil) sekali pun berupa sebiji buah kurma (dan tidak pula yang besar dan tidak melintasi suatu lembah) dengan berjalan kaki (melainkan dituliskan bagi mereka) amal saleh pula (karena Allah memberi balasan kepada mereka yang lebih baik dari apa yang telah mereka kerjakan) sebagai pahalanya.",[["وَلَا","And not"],["يُنفِقُونَ","they spend"],["نَفَقَةًۭ","any spending"],["صَغِيرَةًۭ","small"],["وَلَا","and not"],["كَبِيرَةًۭ","big"],["وَلَا","and not"],["يَقْطَعُونَ","they cross"],["وَادِيًا","a valley"],["إِلَّا","but"],["كُتِبَ","is recorded"],["لَهُمْ","for them"],["لِيَجْزِيَهُمُ","that Allah may reward them"],["ٱللَّهُ","that Allah may reward them"],["أَحْسَنَ","the best"],["مَا","(of) what"],["كَانُوا۟","they used (to)"],["يَعْمَلُونَ","do"]]],"1357":["Tatkala kaum Mukminin dicela oleh Allah bila tidak ikut ke medan perang kemudian Nabi saw. mengirimkan sariyahnya, akhirnya mereka berangkat ke medan perang semua tanpa ada seorang pun yang tinggal, maka turunlah firman-Nya berikut ini: (Tidak sepatutnya bagi orang-orang yang mukmin itu pergi) ke medan perang (semuanya. Mengapa tidak) (pergi dari tiap-tiap golongan) suatu kabilah (di antara mereka beberapa orang) beberapa golongan saja kemudian sisanya tetap tinggal di tempat (untuk memperdalam pengetahuan mereka) yakni tetap tinggal di tempat (mengenai agama dan untuk memberi peringatan kepada kaumnya apabila mereka telah kembali kepadanya) dari medan perang, yaitu dengan mengajarkan kepada mereka hukum-hukum agama yang telah dipelajarinya (supaya mereka itu dapat menjaga dirinya) dari siksaan Allah, yaitu dengan melaksanakan perintah-Nya dan menjauhi larangan-Nya. Sehubungan dengan ayat ini Ibnu Abbas r.a. memberikan penakwilannya bahwa ayat ini penerapannya hanya khusus untuk sariyah-sariyah, yakni bilamana pasukan itu dalam bentuk sariyah lantaran Nabi saw. tidak ikut. Sedangkan ayat sebelumnya yang juga melarang seseorang tetap tinggal di tempatnya dan tidak ikut berangkat ke medan perang, maka hal ini pengertiannya tertuju kepada bila Nabi saw. berangkat ke suatu ghazwah.",[["۞ وَمَا","And not"],["كَانَ","is"],["ٱلْمُؤْمِنُونَ","(for) the believers"],["لِيَنفِرُوا۟","that they go forth"],["كَآفَّةًۭ ۚ","all together"],["فَلَوْلَا","So if not"],["نَفَرَ","go forth"],["مِن","from"],["كُلِّ","every"],["فِرْقَةٍۢ","group"],["مِّنْهُمْ","among them"],["طَآئِفَةٌۭ","a party"],["لِّيَتَفَقَّهُوا۟","that they may obtain understanding"],["فِى","in"],["ٱلدِّينِ","the religion"],["وَلِيُنذِرُوا۟","and that they may warn"],["قَوْمَهُمْ","their people"],["إِذَا","when"],["رَجَعُوٓا۟","they return"],["إِلَيْهِمْ","to them"],["لَعَلَّهُمْ","so that they may"],["يَحْذَرُونَ","beware"]]],"1358":["(Hai orang-orang yang beriman perangilah orang-orang kafir yang ada di sekitar kalian itu) yakni mereka yang tinggal berdekatan dengan kalian, kemudian mereka yang dibilang tinggal berdekatan dengan kalian (dan hendaklah mereka menemui kekerasan daripada kalian) artinya berlaku keraslah kalian terhadap mereka (dan ketahuilah bahwasanya Allah beserta orang-orang yang bertakwa) bantuan dan pertolongan-Nya akan selalu menyertainya.",[["يَـٰٓأَيُّهَا","O you who believe"],["ٱلَّذِينَ","O you who believe"],["ءَامَنُوا۟","O you who believe"],["قَـٰتِلُوا۟","Fight"],["ٱلَّذِينَ","those who"],["يَلُونَكُم","(are) close to you"],["مِّنَ","of"],["ٱلْكُفَّارِ","the disbelievers"],["وَلْيَجِدُوا۟","and let them find"],["فِيكُمْ","in you"],["غِلْظَةًۭ ۚ","harshness"],["وَٱعْلَمُوٓا۟","And know"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["مَعَ","(is) with"],["ٱلْمُتَّقِينَ","those who fear (Him)"]]],"1359":["(Dan apabila diturunkan suatu surah) dari Alquran (maka di antara mereka) orang-orang munafik (ada yang berkata) kepada teman-temannya dengan nada mengejek (\"Siapakah di antara kalian yang bertambah imannya dengan turunnya surah ini?\") yakni kepercayaannya. Maka Allah swt. langsung berfirman menjawab perkataan mereka. (Adapun orang-orang yang beriman, maka surah ini menambah imannya) karena mereka benar-benar percaya kepadanya (sedangkan mereka merasa gembira) dengan turunnya surah ini.",[["وَإِذَا","And whenever"],["مَآ","And whenever"],["أُنزِلَتْ","is revealed"],["سُورَةٌۭ","a Surah"],["فَمِنْهُم","among them"],["مَّن","(are some) who"],["يَقُولُ","say"],["أَيُّكُمْ","Which of you"],["زَادَتْهُ","(has) increased [it]"],["هَـٰذِهِۦٓ","(by) this"],["إِيمَـٰنًۭا ۚ","(in) faith"],["فَأَمَّا","As for"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["فَزَادَتْهُمْ","then it has increased them"],["إِيمَـٰنًۭا","(in) faith"],["وَهُمْ","and they"],["يَسْتَبْشِرُونَ","rejoice"]]],"1360":["(Dan adapun orang-orang yang di dalam hati mereka ada penyakit) lemah keyakinan (maka dengan surah ini bertambah kekafiran mereka di samping kekafirannya) kekafiran mereka makin bertambah karena pada mulanya mereka sudah kafir kepada surah itu (dan mereka mati dalam keadaan kafir).",[["وَأَمَّا","But as for"],["ٱلَّذِينَ","those"],["فِى","in"],["قُلُوبِهِم","their hearts"],["مَّرَضٌۭ","(is) a disease"],["فَزَادَتْهُمْ","(it) increases them"],["رِجْسًا","(in) evil"],["إِلَىٰ","to"],["رِجْسِهِمْ","their evil"],["وَمَاتُوا۟","And they die"],["وَهُمْ","while they"],["كَـٰفِرُونَ","(are) disbelievers"]]],"1361":["(Dan tidakkah mereka memperhatikan) bila dibaca yarauna, fa'ilnya adalah orang-orang munafik, dan bila dibaca tarauna, fa`ilnya adalah orang-orang mukmin (bahwa mereka diuji) dicoba (sekali atau dua kali setiap tahun) dengan musim paceklik dan wabah penyakit (kemudian mereka tidak juga bertobat) dari kemunafikannya (dan tidak pula mengambil pelajaran) artinya pelajaran buat dirinya.",[["أَوَلَا","Do not"],["يَرَوْنَ","they see"],["أَنَّهُمْ","that they"],["يُفْتَنُونَ","are tried"],["فِى","[in]"],["كُلِّ","every"],["عَامٍۢ","year"],["مَّرَّةً","once"],["أَوْ","or"],["مَرَّتَيْنِ","twice"],["ثُمَّ","Yet"],["لَا","not"],["يَتُوبُونَ","they turn (in repentance)"],["وَلَا","and not"],["هُمْ","they"],["يَذَّكَّرُونَ","pay heed"]]],"1362":["(Dan apabila diturunkan satu surah) yang di dalamnya menyebutkan tentang perihal mereka, kemudian surah tersebut dibacakan oleh Nabi saw. (sebagian mereka memandang kepada sebagian yang lain) dengan maksud untuk lari dari tempat itu seraya berkata (\"Adakah seorang dari orang-orang Muslimin yang melihat kalian?\") bilamana kalian pergi dari tempat ini; jika ternyata tidak ada seorang pun dari kalangan kaum Muslimin yang melihat mereka, maka mereka segera beranjak pergi dari tempat itu. Apabila ternyata ada seseorang dari kaum Muslimin yang melihat mereka, maka mereka tetap di tempatnya (sesudah itu mereka pun pergi) dengan membawa kekafirannya. (Allah telah memalingkan hati mereka) dari hidayah (disebabkan mereka adalah kaum yang tidak mengerti) akan kebenaran, lantaran mereka tidak mau menggunakan pikirannya guna merenungkan kebenaran itu.",[["وَإِذَا","And whenever"],["مَآ","And whenever"],["أُنزِلَتْ","is revealed"],["سُورَةٌۭ","a Surah"],["نَّظَرَ","look"],["بَعْضُهُمْ","some of them"],["إِلَىٰ","to"],["بَعْضٍ","others"],["هَلْ","Does"],["يَرَىٰكُم","see you"],["مِّنْ","any"],["أَحَدٍۢ","one"],["ثُمَّ","Then"],["ٱنصَرَفُوا۟ ۚ","they turn away"],["صَرَفَ","Allah has turned away"],["ٱللَّهُ","Allah has turned away"],["قُلُوبَهُم","their hearts"],["بِأَنَّهُمْ","because they"],["قَوْمٌۭ","(are) a people"],["لَّا","not"],["يَفْقَهُونَ","they understand"]]],"1363":["(Sesungguhnya telah datang kepada kalian seorang rasul dari kaum kalian sendiri) dari kalangan kalian sendiri, yaitu Nabi Muhammad saw. (berat terasa) dirasa berat (olehnya apa yang kalian derita) yaitu penderitaan kalian, yang dimaksud ialah penderitaan dan musibah yang menimpa diri kalian (sangat menginginkan bagi kalian) hidayah dan keselamatan (lagi terhadap orang-orang mukmin amat belas kasihan) sangat belas kasihan (lagi penyayang) ia selalu mengharapkan kebaikan bagi mereka.",[["لَقَدْ","Certainly"],["جَآءَكُمْ","(has) come to you"],["رَسُولٌۭ","a Messenger"],["مِّنْ","from"],["أَنفُسِكُمْ","yourselves"],["عَزِيزٌ","Grievous"],["عَلَيْهِ","to him"],["مَا","(is) what"],["عَنِتُّمْ","you suffer"],["حَرِيصٌ","(he is) concerned"],["عَلَيْكُم","over you"],["بِٱلْمُؤْمِنِينَ","to the believers"],["رَءُوفٌۭ","(he is) kind"],["رَّحِيمٌۭ","(and) merciful"]]],"1364":["(Jika mereka berpaling) dari iman kepadamu (maka katakanlah, \"Cukuplah bagiku) maksudnya cukup untukku (Allah; tidak ada Tuhan selain Dia. Hanya kepada-Nya aku bertawakal) percaya dan bukan kepada selain-Nya (dan Dia adalah Rabb yang memiliki Arasy) yakni Al-Kursiy (yang agung.\") Arasy disebutkan secara khusus karena ia makhluk yang paling besar. Imam Hakim di dalam kitab Al-Mustadrak meriwayatkan sebuah atsar yang bersumber dari Ubay bin Kaab, bahwasanya Ubay bin Kaab telah mengatakan, \"Ayat yang diturunkan paling akhir ialah firman-Nya, 'Sesungguhnya telah datang kepada kalian seorang rasul.'\" (Q.S. At-Taubah 128-129). Kedua ayat akhir surah At-Taubah itulah ayat yang paling terakhir diturunkan.",[["فَإِن","But if"],["تَوَلَّوْا۟","they turn away"],["فَقُلْ","then say"],["حَسْبِىَ","Sufficient for me"],["ٱللَّهُ","(is) Allah"],["لَآ","(There is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["هُوَ ۖ","Him"],["عَلَيْهِ","On Him"],["تَوَكَّلْتُ ۖ","I put my trust"],["وَهُوَ","And He"],["رَبُّ","(is the) Lord"],["ٱلْعَرْشِ","(of) the Throne"],["ٱلْعَظِيمِ","the Great"]]],"1365":["(Alif, laam, raa) hanya Allahlah yang mengetahui maksudnya. (Inilah) artinya ayat-ayat ini (ayat-ayat Alkitab) yakni Alquran. Diidhafatkan lafal ayaatul pada lafal Alkitab mengandung makna min, yakni bagian daripada Alquran (yang mengandung hikmah) yang padat akan hikmah-hikmah.",[["الٓر ۚ","Alif Lam Ra"],["تِلْكَ","These"],["ءَايَـٰتُ","(are the) verses"],["ٱلْكِتَـٰبِ","(of) the Book"],["ٱلْحَكِيمِ","the wise"]]],"1366":["(Patutkah manusia) artinya penduduk Mekah. Istifham atau kata tanya di sini mengandung makna ingkar sedangkan jar dan majrurnya menjadi hal atau kata keterangan daripada firman selanjutnya (menjadi keheranan) lafal ini dibaca `ajaban menjadi khabar dari kaana, bila dibaca rafa` menjadi isim kaana. Menurut pendapat yang masyhur adalah sebagai khabar daripada kaana. (bahwa Kami mewahyukan) artinya pemberian wahyu Kami (kepada seorang lelaki di antara mereka) yaitu Nabi Muhammad saw. (yaitu) huruf an di sini menjadi penafsir dari lafal an auhainaa (\"Berilah peringatan) peringatkanlah (kepada manusia) yakni orang-orang kafir akan adanya siksaan buat mereka (dan gembirakanlah orang-orang beriman bahwa) bahwasanya (mereka mempunyai kedudukan) pahala (yang tinggi di sisi Rabb mereka\") dimaksud adalah pahala yang baik sebagai pembalasan dari amal-amal yang telah mereka lakukan. (Orang-orang kafir berkata, \"Sesungguhnya orang ini) yaitu Nabi Muhammad saw. (benar-benar adalah tukang sihir yang nyata.\") jelas tukang sihir. Menurut suatu qiraat lafal lasaahirun dibaca lasihrun, sedangkan musyar ilaihnya adalah Alquran yang dianggap mereka merupakan sihir.",[["أَكَانَ","Is it"],["لِلنَّاسِ","for the mankind"],["عَجَبًا","a wonder"],["أَنْ","that"],["أَوْحَيْنَآ","We revealed"],["إِلَىٰ","to"],["رَجُلٍۢ","a man"],["مِّنْهُمْ","from (among) them"],["أَنْ","that"],["أَنذِرِ","Warn"],["ٱلنَّاسَ","the mankind"],["وَبَشِّرِ","and give glad tidings"],["ٱلَّذِينَ","(to) those who"],["ءَامَنُوٓا۟","believe"],["أَنَّ","that"],["لَهُمْ","for them"],["قَدَمَ","(will be) a respectable position"],["صِدْقٍ","(will be) a respectable position"],["عِندَ","near"],["رَبِّهِمْ ۗ","their Lord"],["قَالَ","Said"],["ٱلْكَـٰفِرُونَ","the disbelievers"],["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَسَـٰحِرٌۭ","(is) surely a magician"],["مُّبِينٌ","obvious"]]],"1367":["(Sesungguhnya Rabb kalian ialah Allah yang menciptakan langit dan bumi dalam enam hari) dari hari-hari dunia, artinya dalam masa yang perkiraannya sama dengan enam hari karena sesungguhnya pada masa itu belum ada matahari dan bulan. Akan tetapi seandainya Allah berkehendak, maka Dia dapat menciptakannya dalam sekejap mata. Allah swt, tidak memakai cara tersebut dimaksud untuk memberikan pelajaran kepada makhluk-Nya tentang ketekunan dan kesabaran di dalam bertindak (kemudian Dia bersemayam di atas Arsy) bersemayamnya Allah disesuaikan dengan keagungan sifat-Nya (untuk mengatur segala urusan) di antara makhluk-makhluk-Nya (Tiada seorang pun) huruf min merupakan shilah atau penghubung (yang dapat memberikan syafaat) kepada seseorang (kecuali sesudah ada keizinan-Nya) ayat ini merupakan sanggahan terhadap perkataan orang-orang kafir yang menyatakan bahwa berhala-berhala mereka dapat memberikan syafaat kepada diri mereka. (Zat yang demikian itulah) yaitu yang menciptakan dan yang mengatur (Allah, Rabb kalian, maka sembahlah Dia) artinya tauhidkanlah Dia. (Maka apakah kalian tidak mengambil pelajaran?) lafal tadzakkaruuna asalnya tatadzakkaruuna, kemudian huruf ta yang kedua diidgamkan ke dalam huruf dzal asal kalimat, maka jadilah tadzakkaruuna.",[["إِنَّ","Indeed"],["رَبَّكُمُ","your Lord"],["ٱللَّهُ","(is) Allah"],["ٱلَّذِى","the One Who"],["خَلَقَ","created"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضَ","and the earth"],["فِى","in"],["سِتَّةِ","six"],["أَيَّامٍۢ","periods"],["ثُمَّ","then"],["ٱسْتَوَىٰ","He established"],["عَلَى","on"],["ٱلْعَرْشِ ۖ","the Throne"],["يُدَبِّرُ","disposing"],["ٱلْأَمْرَ ۖ","the affairs"],["مَا","Not"],["مِن","(is) any intercessor"],["شَفِيعٍ","(is) any intercessor"],["إِلَّا","except"],["مِنۢ","after"],["بَعْدِ","after"],["إِذْنِهِۦ ۚ","His permission"],["ذَٰلِكُمُ","That"],["ٱللَّهُ","(is) Allah"],["رَبُّكُمْ","your Lord"],["فَٱعْبُدُوهُ ۚ","so worship Him"],["أَفَلَا","Then will not"],["تَذَكَّرُونَ","you remember"]]],"1368":["(Hanya kepada-Nyalah) yaitu Allah swt. (kalian semuanya akan kembali; sebagai janji yang benar dari Allah) lafal wa'dan dan lafal haqqan keduanya merupakan mashdar yang dinashabkan oleh fi'ilnya masing-masing yang keberadaannya diperkirakan. (Sesungguhnya Allah) huruf hamzah inna dibaca kasrah karena menjadi isti'naf, sedangkan jika dibaca fatah maka memakai huruf lam yang keberadaannya diperkirakan sebelumnya (menciptakan makhluk pada permulaan) artinya Dia mulai menciptakan makhluk dengan mengadakan mereka (kemudian menghidupkannya kembali) pada hari berbangkit (agar Dia memberi pembalasan) pahala (kepada orang-orang yang beriman dan yang mengerjakan amal saleh dengan adil. Dan untuk orang-orang kafir disediakan minuman air yang panas) artinya air yang panasnya luar biasa (dan azab yang pedih) sangat menyakitkan (disebabkan kekafiran mereka) sebagai pembalasan atas kekafirannya.",[["إِلَيْهِ","To Him"],["مَرْجِعُكُمْ","(will be) your return"],["جَمِيعًۭا ۖ","[all]"],["وَعْدَ","Promise"],["ٱللَّهِ","(of) Allah"],["حَقًّا ۚ","(is) true"],["إِنَّهُۥ","Indeed, He"],["يَبْدَؤُا۟","originates"],["ٱلْخَلْقَ","the creation"],["ثُمَّ","then"],["يُعِيدُهُۥ","He repeats it"],["لِيَجْزِىَ","that He may reward"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed"],["وَعَمِلُوا۟","and did"],["ٱلصَّـٰلِحَـٰتِ","the good deeds"],["بِٱلْقِسْطِ ۚ","in justice"],["وَٱلَّذِينَ","But those who"],["كَفَرُوا۟","disbelieved"],["لَهُمْ","for them"],["شَرَابٌۭ","(will be) a drink"],["مِّنْ","of"],["حَمِيمٍۢ","boiling fluids"],["وَعَذَابٌ","and a punishment"],["أَلِيمٌۢ","painful"],["بِمَا","because"],["كَانُوا۟","they used (to)"],["يَكْفُرُونَ","disbelieve"]]],"1369":["(Dialah yang menjadikan matahari bersinar) mempunyai sinar (dan bulan bercahaya dan ditetapkan-Nya bagi bulan) dalam perjalanannya (manzilah-manzilah) selama dua puluh delapan malam untuk setiap bulan, setiap malam daripada dua puluh delapan malam itu memperoleh suatu manzilah, kemudian tidak tampak selama dua malam, jika jumlah hari bulan yang bersangkutan ada tiga puluh hari. Atau tidak tampak selama satu malam jika ternyata jumlah hari bulan yang bersangkutan ada dua puluh sembilan hari (supaya kalian mengetahui) melalui hal tersebut (bilangan tahun dan perhitungan waktu, Allah tidak menciptakan yang demikian itu) hal-hal yang telah disebutkan itu (melainkan dengan hak) bukannya main-main, Maha Suci Allah dari perbuatan tersebut (Dia menjelaskan) dapat dibaca yufashshilu dan nufashshilu, artinya Dia menerangkan atau Kami menerangkan (tanda-tanda kepada orang-orang yang mengetahui) yakni orang-orang yang mau berpikir.",[["هُوَ","He"],["ٱلَّذِى","(is) the One Who"],["جَعَلَ","made"],["ٱلشَّمْسَ","the sun"],["ضِيَآءًۭ","a shining light"],["وَٱلْقَمَرَ","and the moon"],["نُورًۭا","a reflected light"],["وَقَدَّرَهُۥ","and determined for it"],["مَنَازِلَ","phases"],["لِتَعْلَمُوا۟","that you may know"],["عَدَدَ","(the) number"],["ٱلسِّنِينَ","(of) the years"],["وَٱلْحِسَابَ ۚ","and the count (of time)"],["مَا","Not"],["خَلَقَ","created"],["ٱللَّهُ","Allah"],["ذَٰلِكَ","that"],["إِلَّا","except"],["بِٱلْحَقِّ ۚ","in truth"],["يُفَصِّلُ","He explains"],["ٱلْـَٔايَـٰتِ","the Signs"],["لِقَوْمٍۢ","for a people"],["يَعْلَمُونَ","(who) know"]]],"1370":["(Sesungguhnya pada pertukaran malam dan siang itu) silih bergantinya malam dan siang hari kemudian panjang dan pendeknya malam dan siang hari (dan pada yang diciptakan Allah di langit) yakni para malaikat, matahari, bulan dan bintang-bintang serta lain sebagainya (Dan) di (bumi) berupa margasatwa, gunung-gunung, lautan, sungai-sungai, pohon-pohon dan lain sebagainya (benar-benar terdapat tanda-tanda) yang menunjukkan kepada kekuasaan-Nya (bagi orang-orang yang bertakwa) kepada-Nya kemudian mereka beriman. Allah secara khusus menyebutkan orang-orang yang bertakwa karena sesungguhnya merekalah yang dapat memanfaatkan keberadaan tanda-tanda tersebut.",[["إِنَّ","Indeed"],["فِى","in"],["ٱخْتِلَـٰفِ","(the) alternation"],["ٱلَّيْلِ","(of) the night"],["وَٱلنَّهَارِ","and the day"],["وَمَا","and what"],["خَلَقَ","(has been) created"],["ٱللَّهُ","(by) Allah"],["فِى","in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ","and the earth"],["لَـَٔايَـٰتٍۢ","(are) Signs"],["لِّقَوْمٍۢ","for a people"],["يَتَّقُونَ","who are God conscious"]]],"1371":["(Sesungguhnya orang-orang yang tidak mengharapkan/tidak percaya akan pertemuan dengan Kami) pada hari berbangkit nanti (dan mereka merasa puas dengan kehidupan dunia) sebagai ganti daripada kehidupan akhirat karena mereka tidak mempercayai adanya hari akhirat itu (serta merasa tenteram dengan kehidupan itu) merasa tenang dengan kehidupan dunia (dan orang-orang yang terhadap ayat-ayat Kami) bukti-bukti yang menunjukkan kepada keesaan Kami (mereka melalaikan) mereka sama sekali tidak mau memikirkannya.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يَرْجُونَ","expect"],["لِقَآءَنَا","the meeting with Us"],["وَرَضُوا۟","and are pleased"],["بِٱلْحَيَوٰةِ","with the life"],["ٱلدُّنْيَا","(of) the world"],["وَٱطْمَأَنُّوا۟","and feel satisfied"],["بِهَا","with it"],["وَٱلَّذِينَ","and those "],["هُمْ","they"],["عَنْ","(are) of"],["ءَايَـٰتِنَا","Our Signs"],["غَـٰفِلُونَ","heedless"]]],"1372":["(Mereka itu tempatnya ialah neraka disebabkan apa yang selalu mereka kerjakan) berupa kemusyrikan dan perbuatan-perbuatan maksiat.",[["أُو۟لَـٰٓئِكَ","Those "],["مَأْوَىٰهُمُ","their abode"],["ٱلنَّارُ","(will be) the Fire"],["بِمَا","for what"],["كَانُوا۟","they used (to)"],["يَكْسِبُونَ","earn"]]],"1373":["(Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal saleh, mereka diberi petunjuk) diberi bimbingan (oleh Rabb mereka karena keimanannya) kepada-Nya; kelak pada hari kiamat Allah swt. akan menjadikan bagi mereka cahaya dengan cahaya itu mereka mendapat petunjuk (di bawah mereka mengalir sungai-sungai di dalam surga yang penuh kenikmatan).",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed"],["وَعَمِلُوا۟","and did"],["ٱلصَّـٰلِحَـٰتِ","good deeds"],["يَهْدِيهِمْ","(will) guide them"],["رَبُّهُم","their Lord"],["بِإِيمَـٰنِهِمْ ۖ","by their faith"],["تَجْرِى","Will flow"],["مِن","from"],["تَحْتِهِمُ","underneath them"],["ٱلْأَنْهَـٰرُ","the rivers"],["فِى","in"],["جَنَّـٰتِ","Gardens"],["ٱلنَّعِيمِ","(of) Delight"]]],"1374":["(Doa mereka di dalamnya) sewaktu mereka meminta apa yang mereka inginkan di dalam surga hanya tinggal mengatakan (Subhaanakallaahumma) artinya Maha Suci Engkau ya Allah. Bilamana mereka telah memintanya maka mereka menemukan apa yang mereka inginkan telah berada di hadapan mereka (dan salam penghormatan mereka) di antara sesama mereka (di dalam surga ialah salam. Dan penutup doa mereka ialah) huruf an di sini adalah kata penafsir (alhamdulillaahi rabbil aalamiin) segala puji bagi Allah Rabb alam semesta. Ayat ini diturunkan sewaktu orang-orang musyrik meminta disegerakan turunnya azab.",[["دَعْوَىٰهُمْ","Their prayer"],["فِيهَا","therein"],["سُبْحَـٰنَكَ","(will be), \"Glory be to You"],["ٱللَّهُمَّ","O Allah"],["وَتَحِيَّتُهُمْ","And their greeting"],["فِيهَا","therein (will be)"],["سَلَـٰمٌۭ ۚ","Peace"],["وَءَاخِرُ","And the last"],["دَعْوَىٰهُمْ","(of) their call"],["أَنِ","(will be) [that]"],["ٱلْحَمْدُ","All the Praise be"],["لِلَّهِ","to Allah"],["رَبِّ","Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"1375":["(Dan kalau sekiranya Allah menyegerakan kejahatan bagi manusia seperti permintaan mereka untuk menyegerakan) artinya sama seperti mereka meminta mendapatkan dengan segera (kebaikan, pastilah diakhiri) boleh dibaca laqudhiya atau laqadha (umur mereka) lafal ajaluhum dapat dibaca rafa` yakni menjadi ajaluhum dan dapat pula dibaca nashab hingga menjadi ajalahum; seumpamanya Allah membinasakan mereka dengan segera akan tetapi ternyata Allah menangguhkan (Maka Kami biarkan) Kami tinggalkan (orang-orang yang tidak mengharapkan pertemuan dengan Kami bergelimang di dalam kesesatan mereka) mereka hidup diselimuti oleh keraguan yang membingungkan.",[["۞ وَلَوْ","And if"],["يُعَجِّلُ","hastens"],["ٱللَّهُ","(by) Allah"],["لِلنَّاسِ","for the mankind"],["ٱلشَّرَّ","the evil"],["ٱسْتِعْجَالَهُم","(as) He hastens for them"],["بِٱلْخَيْرِ","the good"],["لَقُضِىَ","surely, would have been decreed"],["إِلَيْهِمْ","for them"],["أَجَلُهُمْ ۖ","their term"],["فَنَذَرُ","But We leave"],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يَرْجُونَ","expect"],["لِقَآءَنَا","the meeting with Us"],["فِى","in"],["طُغْيَـٰنِهِمْ","their transgression"],["يَعْمَهُونَ","wandering blindly"]]],"1376":["(Dan apabila manusia ditimpa) yang dimaksud adalah orang kafir (bahaya) berupa penyakit dan kefakiran (dia berdoa kepada Kami dalam keadaan berbaring) membaringkan diri (atau duduk, atau berdiri) artinya dalam semua keadaan (tetapi setelah Kami hilangkan bahaya itu daripadanya dia kembali) kepada kekafirannya (seolah-olah) lafal ka-an berasal dari ka-anna yang ditakhfifkan sedangkan isimnya tidak disebutkan. Lengkapnya ka-annahu, artinya seolah-olah dia (tidak pernah berdoa kepada Kami untuk menghilangkan bahaya yang telah menimpanya. Begitulah) sifat orang kafir, yaitu berdoa di kala tertimpa bahaya dan berpaling di kala hidup sejahtera (orang-orang yang melampaui batas itu memandang baik) yang dimaksud adalah orang-orang musyrik (apa yang selalu mereka kerjakan).",[["وَإِذَا","And when"],["مَسَّ","touches"],["ٱلْإِنسَـٰنَ","the man"],["ٱلضُّرُّ","the affliction"],["دَعَانَا","he calls Us"],["لِجَنۢبِهِۦٓ","(lying) on his side"],["أَوْ","or"],["قَاعِدًا","sitting"],["أَوْ","or"],["قَآئِمًۭا","standing"],["فَلَمَّا","But when"],["كَشَفْنَا","We remove"],["عَنْهُ","from him"],["ضُرَّهُۥ","his affliction"],["مَرَّ","he passes on"],["كَأَن","as if he"],["لَّمْ","(had) not"],["يَدْعُنَآ","called Us"],["إِلَىٰ","for"],["ضُرٍّۢ","(the) affliction"],["مَّسَّهُۥ ۚ","(that) touched him"],["كَذَٰلِكَ","Thus"],["زُيِّنَ","(it) is made fair seeming"],["لِلْمُسْرِفِينَ","to the extravagant"],["مَا","what"],["كَانُوا۟","they used (to)"],["يَعْمَلُونَ","do"]]],"1377":["(Dan sesungguhnya Kami telah membinasakan umat-umat) generasi-generasi (yang sebelum kalian) hai penduduk Mekah (ketika mereka berbuat kelaliman) yaitu dengan melakukan kemusyrikan (padahal) sungguh (telah datang kepada mereka rasul-rasul mereka dengan membawa keterangan-keterangan yang nyata) bukti-bukti yang menunjukkan kebenaran risalah mereka (tetapi mereka sekali-kali tidak hendak beriman) kalimat ayat ini di'athafkan pada lafal lammaa zhalamuu. (Demikianlah) seperti yang telah Kami binasakan mereka (Kami memberi pembalasan kepada orang-orang yang berbuat dosa) yaitu orang-orang kafir.",[["وَلَقَدْ","And verily"],["أَهْلَكْنَا","We destroyed"],["ٱلْقُرُونَ","the generations"],["مِن","before you"],["قَبْلِكُمْ","before you"],["لَمَّا","when"],["ظَلَمُوا۟ ۙ","they wronged"],["وَجَآءَتْهُمْ","and came to them"],["رُسُلُهُم","their Messengers"],["بِٱلْبَيِّنَـٰتِ","with clear proofs"],["وَمَا","but not"],["كَانُوا۟","they were"],["لِيُؤْمِنُوا۟ ۚ","to believe"],["كَذَٰلِكَ","Thus"],["نَجْزِى","We recompense"],["ٱلْقَوْمَ","the people"],["ٱلْمُجْرِمِينَ","(who are) criminals"]]],"1378":["(Kemudian Kami jadikan kalian) hai penduduk Mekah (pengganti-pengganti) lafal khalaaif adalah bentuk jamak dari lafal khaliifah (di muka bumi sesudah mereka supaya Kami memperhatikan bagaimana kalian berbuat) di muka bumi; apakah kalian mau mengambil pelajaran dari umat-umat terdahulu itu sehingga kalian mau percaya kepada rasul-rasul Kami.",[["ثُمَّ","Then"],["جَعَلْنَـٰكُمْ","We made you"],["خَلَـٰٓئِفَ","successors"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["مِنۢ","after them"],["بَعْدِهِمْ","after them"],["لِنَنظُرَ","so that We may see"],["كَيْفَ","how"],["تَعْمَلُونَ","you do"]]],"1379":["(Dan apabila dibacakan kepada mereka ayat-ayat Kami) yakni Alquran (yang nyata) yang jelas; lafal bayyinaatin kedudukannya menjadi hal atau kata keterangan keadaan (orang-orang yang tidak mengharapkan pertemuan dengan Kami berkata) mereka adalah orang-orang yang tidak takut akan adanya hari pembalasan (\"Datangkanlah Alquran yang lain dari ini) yang isinya tidak mengandung celaan kepada tuhan-tuhan kami (atau gantilah dia.\") dengan buatanmu sendiri (Katakanlah,) kepada mereka (\"Tidaklah pantas) tidak layak (bagiku menggantinya dari pihak) berdasarkan kemauan (diriku sendiri. Aku tidak) tiada lain (hanya mengikuti apa yang diwahyukan kepadaku. Sesungguhnya aku takut jika mendurhakai Rabbku) oleh sebab menggantikan Alquran (kepada siksa hari yang besar.\") yaitu hari kiamat.",[["وَإِذَا","And when"],["تُتْلَىٰ","are recited"],["عَلَيْهِمْ","to them"],["ءَايَاتُنَا","Our Verses"],["بَيِّنَـٰتٍۢ ۙ","(as) clear proofs"],["قَالَ","said"],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يَرْجُونَ","hope"],["لِقَآءَنَا","(for the) meeting (with) Us"],["ٱئْتِ","Bring us"],["بِقُرْءَانٍ","a Quran"],["غَيْرِ","other (than)"],["هَـٰذَآ","this"],["أَوْ","or"],["بَدِّلْهُ ۚ","change it"],["قُلْ","Say"],["مَا","Not"],["يَكُونُ","(it) is"],["لِىٓ","for me"],["أَنْ","that"],["أُبَدِّلَهُۥ","I change it"],["مِن","of"],["تِلْقَآئِ","my own accord"],["نَفْسِىٓ ۖ","my own accord"],["إِنْ","Not"],["أَتَّبِعُ","I follow"],["إِلَّا","except"],["مَا","what"],["يُوحَىٰٓ","is revealed"],["إِلَىَّ ۖ","to me"],["إِنِّىٓ","Indeed, I"],["أَخَافُ","[I] fear"],["إِنْ","if"],["عَصَيْتُ","I were to disobey"],["رَبِّى","my Lord"],["عَذَابَ","(the) punishment"],["يَوْمٍ","(of) a Day"],["عَظِيمٍۢ","Great"]]],"1380":["(Katakanlah, \"Jika Allah menghendaki, niscaya aku tidak membacakannya kepada kalian dan aku tidak pula memberitahukan kepada kalian) mengajarkan kepada kalian (mengenainya) huruf laa di sini bermakna nafi atau meniadakan, kemudian diathafkan kepada nafi yang sebelumnya. Menurut qiraat yang lain dianggap sebagai lam yang menjadi jawab daripada huruf lau, dengan demikian berarti niscaya aku akan mengajarkannya kepada kalian dengan bahasa yang bukan bahasaku (Sesungguhnya aku telah tinggal) diam (bersama dengan kalian beberapa lama) yaitu empat puluh tahun (sebelumnya.\") selama itu aku belum pernah menceritakan sesuatu kepada kalian (Maka apakah kalian tidak memikirkannya?) bahwasanya Alquran itu bukanlah buatanku sendiri.",[["قُل","Say"],["لَّوْ","If"],["شَآءَ","(had) willed"],["ٱللَّهُ","Allah"],["مَا","not"],["تَلَوْتُهُۥ","I (would) have recited it"],["عَلَيْكُمْ","to you"],["وَلَآ","and not"],["أَدْرَىٰكُم","He (would) have made it known to you"],["بِهِۦ ۖ","He (would) have made it known to you"],["فَقَدْ","Verily"],["لَبِثْتُ","I have stayed"],["فِيكُمْ","among you"],["عُمُرًۭا","a lifetime"],["مِّن","before it"],["قَبْلِهِۦٓ ۚ","before it"],["أَفَلَا","Then will not"],["تَعْقِلُونَ","you use reason"]]],"1381":["(Maka siapakah) artinya, tiada seorang pun (yang lebih lalim daripada orang yang mengada-adakan kedustaan terhadap Allah) yaitu dengan melakukan kemusyrikan terhadap Allah (atau mendustakan ayat-ayat-Nya?) yakni Alquran. (Sesungguhnya) pada kenyataannya (tiadalah beruntung) tiadalah berbahagia (orang-orang yang berbuat dosa) yaitu orang-orang musyrik.",[["فَمَنْ","So who"],["أَظْلَمُ","(is) more wrong"],["مِمَّنِ","than he who"],["ٱفْتَرَىٰ","invents"],["عَلَى","against"],["ٱللَّهِ","Allah"],["كَذِبًا","a lie"],["أَوْ","or"],["كَذَّبَ","denies"],["بِـَٔايَـٰتِهِۦٓ ۚ","His Signs"],["إِنَّهُۥ","Indeed"],["لَا","not"],["يُفْلِحُ","will succeed"],["ٱلْمُجْرِمُونَ","the criminals"]]],"1382":["(Dan mereka menyembah selain daripada Allah) (apa yang tidak dapat mendatangkan kemudaratan) jika mereka tidak menyembahnya (dan tidak pula kemanfaatan) jika mereka menyembahnya, yang dimaksud adalah berhala-berhala yang mereka sembah itu (dan mereka berkata,) tentang berhala-berhala itu (\"Mereka itu adalah pemberi syafaat kepada kami di sisi Allah.\" Katakanlah) kepada mereka (\"Apakah kalian mengabarkan kepada Allah) menceritakan kepada-Nya (apa yang tidak diketahui-Nya di langit dan tidak pula di bumi?\") Istifham atau kata tanya di sini mengandung makna ingkar, karena seandainya Dia mempunyai sekutu niscaya Dia akan mengetahui sekutunya itu karena sesungguhnya tiada sesuatu pun yang samar bagi-Nya. (Maha Suci Allah) dari hal-hal yang tidak layak bagi-Nya (dan Maha Tinggi daripada apa yang mereka persekutukan itu) bersama Allah.",[["وَيَعْبُدُونَ","And they worship"],["مِن","from"],["دُونِ","other than"],["ٱللَّهِ","Allah"],["مَا","that (which)"],["لَا","(does) not"],["يَضُرُّهُمْ","harm them"],["وَلَا","and not"],["يَنفَعُهُمْ","benefit them"],["وَيَقُولُونَ","and they say"],["هَـٰٓؤُلَآءِ","These"],["شُفَعَـٰٓؤُنَا","(are) our intercessors"],["عِندَ","with"],["ٱللَّهِ ۚ","Allah"],["قُلْ","Say"],["أَتُنَبِّـُٔونَ","Do you inform"],["ٱللَّهَ","Allah"],["بِمَا","of what"],["لَا","not"],["يَعْلَمُ","he knows"],["فِى","in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَلَا","and not"],["فِى","in"],["ٱلْأَرْضِ ۚ","the earth"],["سُبْحَـٰنَهُۥ","Glorified is He"],["وَتَعَـٰلَىٰ","and Exalted"],["عَمَّا","above what"],["يُشْرِكُونَ","they associate (with Him)"]]],"1383":["(Manusia dahulunya hanyalah satu umat) satu agama yaitu agama Islam, sejak dari zaman Nabi Adam sampai dengan zaman Nabi Nuh. Menurut pendapat yang lain dikatakan mulai dari zaman Nabi Ibrahim sampai dengan zamannya Amr bin Luhay (kemudian mereka berselisih) disebabkan sebagian daripada mereka tetap iman sedangkan sebagian yang lainnya kafir. (Kalau tidaklah karena suatu ketetapan yang telah ada dari Rabbmu dahulu) dengan menangguhkan pembalasan hingga hari kiamat (pastilah diberi keputusan di antara mereka) yaitu di antara manusia di dunia (tentang apa yang mereka perselisihkan itu) dalam masalah agama, yaitu dengan mengazab orang-orang kafir.",[["وَمَا","And not"],["كَانَ","was"],["ٱلنَّاسُ","the mankind"],["إِلَّآ","but"],["أُمَّةًۭ","a community"],["وَٰحِدَةًۭ","one"],["فَٱخْتَلَفُوا۟ ۚ","then they differed"],["وَلَوْلَا","And had (it) not been"],["كَلِمَةٌۭ","a word"],["سَبَقَتْ","(that) preceded"],["مِن","from"],["رَّبِّكَ","your Lord"],["لَقُضِىَ","surely, it (would) have been judged"],["بَيْنَهُمْ","between them"],["فِيمَا","concerning what"],["فِيهِ","[therein]"],["يَخْتَلِفُونَ","they differ"]]],"1384":["(Dan mereka berkata,) yakni penduduk Mekah (\"Mengapa tidak) kenapa tidak (diturunkan kepadanya) dimaksud kepada Nabi Muhammad saw. (suatu keterangan dari Rabbnya?\") sebagaimana yang telah diberikan kepada para nabi lainnya, seperti mukjizat unta, mukjizat tongkat dan mukjizat tangan (Maka katakanlah,) kepada mereka (\"Sesungguhnya yang gaib itu) hal-hal yang gaib dari mata hamba-hamba Allah (kepunyaan Allah) antara lain ialah mukjizat-mukjizat, maka mukjizat-mukjizat itu tidak ada yang dapat mendatangkannya melainkan hanya seizin Allah. Sesungguhnya tugasku hanyalah menyampaikan (sebab itu tunggu sajalah oleh kalian) datangnya azab jika kalian tidak mau beriman (sesungguhnya aku bersama kalian termasuk orang-orang yang menunggu.\")",[["وَيَقُولُونَ","And they say"],["لَوْلَآ","Why not"],["أُنزِلَ","is sent down"],["عَلَيْهِ","to him"],["ءَايَةٌۭ","a Sign"],["مِّن","from"],["رَّبِّهِۦ ۖ","his Lord"],["فَقُلْ","So say"],["إِنَّمَا","Only"],["ٱلْغَيْبُ","the unseen"],["لِلَّهِ","(is) for Allah"],["فَٱنتَظِرُوٓا۟","so wait"],["إِنِّى","indeed, I am"],["مَعَكُم","with you"],["مِّنَ","among"],["ٱلْمُنتَظِرِينَ","the ones who wait"]]],"1385":["(Dan apabila Kami merasakan kepada manusia) kepada orang-orang kafir Mekah (suatu rahmat) berupa hujan dan kesuburan (sesudah datangnya bahaya) kesengsaraan dan kekeringan (menimpa mereka, tiba-tiba mereka mempunyai tipu daya dalam menentang tanda-tanda kekuasaan Kami) dengan memperolok-olokkannya dan mendustakannya. (Katakanlah,) kepada mereka (\"Allah lebih cepat dalam membuat tipu daya\") sebagai pembalasan dari-Nya. (Sesungguhnya utusan-utusan Kami) yaitu para malaikat (menuliskan tipu daya kalian) lafal tamkuruuna dapat dibaca dengan memakai huruf ta sehingga menjadi tamkuruuna, dapat pula dibaca dengan huruf ya sehingga bacaannya menjadi yamkuruuna.",[["وَإِذَآ","And when"],["أَذَقْنَا","We let [the] mankind taste"],["ٱلنَّاسَ","We let [the] mankind taste"],["رَحْمَةًۭ","mercy"],["مِّنۢ","after"],["بَعْدِ","after"],["ضَرَّآءَ","adversity"],["مَسَّتْهُمْ","has touched them"],["إِذَا","behold"],["لَهُم","They have"],["مَّكْرٌۭ","a plot"],["فِىٓ","against"],["ءَايَاتِنَا ۚ","Our Verses"],["قُلِ","Say"],["ٱللَّهُ","Allah"],["أَسْرَعُ","(is) more swift"],["مَكْرًا ۚ","(in) planning"],["إِنَّ","Indeed"],["رُسُلَنَا","Our Messengers"],["يَكْتُبُونَ","write down"],["مَا","what"],["تَمْكُرُونَ","you plot"]]],"1386":["(Dialah Tuhan yang menjadikan kalian dapat berjalan) menurut suatu qiraat yansyurukum bukannya yusayyirukum (di daratan, berlayar di laut. Sehingga apabila kalian berada di dalam bahtera) di dalam perahu-perahu (dan meluncurlah bahtera itu membawa orang-orang yang di dalamnya) di dalam lafal ini terkandung pengertian iltifat dari mukhathab menjadi ghaib (dengan tiupan angin yang baik) angin yang lembut (dan mereka bergembira karenanya, datanglah angin badai) angin yang kencang tiupannya dan dapat menghancurkan segala sesuatu yang dilandanya (dan gelombang dari segenap penjuru menimpanya, dan mereka yakin bahwa mereka telah dikepung bahaya) mereka pasti binasa (maka mereka berdoa kepada Allah dengan mengikhlaskan ketaatan kepada-Nya semata-mata) yakni berseru (\"Sesungguhnya jika) huruf lam di sini bermakna qasam atau sumpah (Engkau menyelamatkan kami dari bahaya ini) dari malapetaka ini (pastilah kami termasuk orang-orang yang bersyukur.\") yaitu akan menjadi orang-orang yang mentauhidkan Allah.",[["هُوَ","He"],["ٱلَّذِى","(is) the One Who"],["يُسَيِّرُكُمْ","enables you to travel"],["فِى","in"],["ٱلْبَرِّ","the land"],["وَٱلْبَحْرِ ۖ","and the sea"],["حَتَّىٰٓ","until"],["إِذَا","when"],["كُنتُمْ","you are"],["فِى","in"],["ٱلْفُلْكِ","the ships"],["وَجَرَيْنَ","and they sail"],["بِهِم","with them"],["بِرِيحٍۢ","with a wind"],["طَيِّبَةٍۢ","good"],["وَفَرِحُوا۟","and they rejoice"],["بِهَا","therein"],["جَآءَتْهَا","comes to it"],["رِيحٌ","a wind"],["عَاصِفٌۭ","stormy"],["وَجَآءَهُمُ","and comes to them"],["ٱلْمَوْجُ","the waves"],["مِن","from"],["كُلِّ","every"],["مَكَانٍۢ","place"],["وَظَنُّوٓا۟","and they assume"],["أَنَّهُمْ","that they"],["أُحِيطَ","are surrounded"],["بِهِمْ ۙ","with them"],["دَعَوُا۟","They call"],["ٱللَّهَ","Allah"],["مُخْلِصِينَ","sincerely"],["لَهُ","to Him"],["ٱلدِّينَ","(in) the religion"],["لَئِنْ","(saying), \"If"],["أَنجَيْتَنَا","You save us"],["مِنْ","from"],["هَـٰذِهِۦ","this"],["لَنَكُونَنَّ","surely we will be"],["مِنَ","among"],["ٱلشَّـٰكِرِينَ","the thankful"]]],"1387":["(Maha setelah Allah menyelamatkan mereka, tiba-tiba mereka membuat kelaliman di muka bumi tanpa alasan yang benar) mereka melakukan kemusyrikan. (Hai manusia, sesungguhnya perbuatan kelewat batas kalian) perbuatan kelaliman kalian (akan menimpa diri kalian sendiri) karena sesungguhnya yang menanggung dosanya adalah diri kalian sendiri (hal itu hanyalah kenikmatan duniawi) kalian bersenang-senang dengannya dalam waktu yang sedikit. (Kemudian kepada Kamilah kembali kalian) sesudah mati (lalu Kami kabarkan kepada kalian apa yang telah kalian kerjakan) maka Kami membalas kalian berdasarkannya. Menurut suatu qiraat lafal mataa'un dibaca nashab sehingga menjadi mataa'an, artinya kalian bersenang-senang.",[["فَلَمَّآ","But when"],["أَنجَىٰهُمْ","He saved them"],["إِذَا","behold"],["هُمْ","They"],["يَبْغُونَ","rebel"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["بِغَيْرِ","without"],["ٱلْحَقِّ ۗ","[the] right"],["يَـٰٓأَيُّهَا","O mankind"],["ٱلنَّاسُ","O mankind"],["إِنَّمَا","Only"],["بَغْيُكُمْ","your rebellion"],["عَلَىٰٓ","(is) against"],["أَنفُسِكُم ۖ","yourselves"],["مَّتَـٰعَ","(the) enjoyment"],["ٱلْحَيَوٰةِ","(of) the life"],["ٱلدُّنْيَا ۖ","(of) the world"],["ثُمَّ","Then"],["إِلَيْنَا","to Us"],["مَرْجِعُكُمْ","(is) your return"],["فَنُنَبِّئُكُم","and We will inform you"],["بِمَا","of what"],["كُنتُمْ","you used (to)"],["تَعْمَلُونَ","do"]]],"1388":["(Sesungguhnya perumpamaan) gambaran (kehidupan duniawi itu adalah seperti air) hujan (yang Kami turunkan dari langit lalu tumbuhlah berkat air itu dengan suburnya) oleh sebab air itu (tanaman-tanaman bumi) sehingga sebagian di antaranya tampak bersatu dengan sebagian yang lain karena rimbunnya (di antaranya ada yang dimakan manusia) berupa biji jawawut, biji gandum dan lain sebagainya (dan binatang ternak) yaitu berupa rerumputan dan dedaunan. (Hingga apabila bumi itu telah sempurna keindahannya) menampakkan keindahannya berkat tumbuh-tumbuhannya (dan memakai pula perhiasannya) karena bunga-bungaannya. Asal kata wazzayyanat adalah tazayyanat, kemudian huruf ta diganti dengan huruf za, yang selanjutnya huruf za yang pengganti ini diidghamkan atau dimasukkan ke dalam huruf za asal, sehingga jadilah izzayyanat (dan pemilik-pemiliknya mengira bahwa mereka pasti menguasainya) mereka merasa pasti akan dapat memetik hasilnya (tiba-tiba datanglah kepadanya perkara Kami) kepastian atau azab Kami (di waktu malam hari atau siang, lalu Kami jadikan ia) yakni tanam-tanamannya (laksana tanam-tanaman yang sudah disabit) sudah dipanen dengan memakai sabit (seakan-akan) lafal ka-an adalah mukhaffafah dari lafal ka-anna, artinya seakan-akan ia (belum pernah tumbuh) belum pernah berujud (kemarin. Demikianlah Kami menjelaskan) Kami terangkan (tanda-tanda kekuasaan Kami kepada orang-orang yang berpikir).",[["إِنَّمَا","Only"],["مَثَلُ","(the) example"],["ٱلْحَيَوٰةِ","(of) the life"],["ٱلدُّنْيَا","(of) the world"],["كَمَآءٍ","(is) like (the) water"],["أَنزَلْنَـٰهُ","which We sent down"],["مِنَ","from"],["ٱلسَّمَآءِ","the sky"],["فَٱخْتَلَطَ","so absorbs"],["بِهِۦ","[with] it"],["نَبَاتُ","(the) plants"],["ٱلْأَرْضِ","(of) the earth"],["مِمَّا","from which"],["يَأْكُلُ","eat"],["ٱلنَّاسُ","the men"],["وَٱلْأَنْعَـٰمُ","and the cattle"],["حَتَّىٰٓ","until"],["إِذَآ","when"],["أَخَذَتِ","takes"],["ٱلْأَرْضُ","the earth"],["زُخْرُفَهَا","its adornment"],["وَٱزَّيَّنَتْ","and is beautified"],["وَظَنَّ","and think"],["أَهْلُهَآ","its people"],["أَنَّهُمْ","that they"],["قَـٰدِرُونَ","have the power"],["عَلَيْهَآ","over it"],["أَتَىٰهَآ","comes (to) it"],["أَمْرُنَا","Our command"],["لَيْلًا","(by) night"],["أَوْ","or"],["نَهَارًۭا","(by) day"],["فَجَعَلْنَـٰهَا","and We make it"],["حَصِيدًۭا","a harvest clean-mown"],["كَأَن","as if"],["لَّمْ","not"],["تَغْنَ","it had flourished"],["بِٱلْأَمْسِ ۚ","yesterday"],["كَذَٰلِكَ","Thus"],["نُفَصِّلُ","We explain"],["ٱلْـَٔايَـٰتِ","the Signs"],["لِقَوْمٍۢ","for a people"],["يَتَفَكَّرُونَ","who reflect"]]],"1389":["(Allah menyeru ke darussalam) kepada jalan keselamatan, yaitu surga; Dia menyeru manusia pada keimanan (dan menunjuki orang yang dikehendaki-Nya) untuk mendapat petunjuk (kepada jalan yang lurus) yakni agama Islam.",[["وَٱللَّهُ","And Allah"],["يَدْعُوٓا۟","calls"],["إِلَىٰ","to"],["دَارِ","(the) Home"],["ٱلسَّلَـٰمِ","(of) the Peace"],["وَيَهْدِى","and guides"],["مَن","whom"],["يَشَآءُ","He wills"],["إِلَىٰ","to"],["صِرَٰطٍۢ","(the) straight path"],["مُّسْتَقِيمٍۢ","(the) straight path"]]],"1390":["(Bagi orang-orang yang berbuat baik) dengan keimanannya (ada pahala yang terbaik) yaitu surga (dan tambahannya) yaitu dapat melihat Allah swt. sebagaimana yang telah diterangkan di dalam hadis sahih Muslim. (Dan tidak pernah layu) tidak pernah tertutup (wajah mereka oleh kekelaman) kesusahan yang kelam (dan tidak pula oleh kehinaan) kesedihan. (Mereka itulah penghuni surga, mereka kekal di dalamnya.)",[["۞ لِّلَّذِينَ","For those who"],["أَحْسَنُوا۟","do good"],["ٱلْحُسْنَىٰ","(is) the best"],["وَزِيَادَةٌۭ ۖ","and more"],["وَلَا","And not"],["يَرْهَقُ","(will) cover"],["وُجُوهَهُمْ","their faces"],["قَتَرٌۭ","dust"],["وَلَا","and not"],["ذِلَّةٌ ۚ","humiliation"],["أُو۟لَـٰٓئِكَ","Those"],["أَصْحَـٰبُ","(are the) companions"],["ٱلْجَنَّةِ ۖ","(of) Paradise"],["هُمْ","they"],["فِيهَا","in it"],["خَـٰلِدُونَ","(will) abide forever"]]],"1391":["(Dan orang-orang) lafal ayat ini diathafkan kepada lafal alladziina ahsanuu yang ada pada ayat sebelumnya; artinya dan bagi orang-orang (yang mengerjakan keburukan) orang-orang yang mengerjakan kemusyrikan (mendapat balasan yang setimpal dan mereka ditutupi oleh kehinaan. Tidak ada bagi mereka, dari azab Allah) huruf min pada ayat ini adalah huruf zaidah atau tambahan (seorang pelindung pun) yang dapat mencegahnya (seakan-akan tertutupi) diselimuti (muka mereka oleh kepingan-kepingan) dapat dibaca qitha`an dan dapat pula dibaca qith`an (malam yang gelap-gulita. Mereka itulah penghuni neraka; mereka kekal di dalamnya).",[["وَٱلَّذِينَ","And those who"],["كَسَبُوا۟","earned"],["ٱلسَّيِّـَٔاتِ","the evil deeds"],["جَزَآءُ","(the) recompense"],["سَيِّئَةٍۭ","(of) an evil deed"],["بِمِثْلِهَا","(is) like it"],["وَتَرْهَقُهُمْ","and (will) cover them"],["ذِلَّةٌۭ ۖ","humiliation"],["مَّا","They will not have"],["لَهُم","They will not have"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["مِنْ","any"],["عَاصِمٍۢ ۖ","defender"],["كَأَنَّمَآ","As if"],["أُغْشِيَتْ","had been covered"],["وُجُوهُهُمْ","their faces"],["قِطَعًۭا","(with) pieces"],["مِّنَ","from"],["ٱلَّيْلِ","the darkness (of) night"],["مُظْلِمًا ۚ","the darkness (of) night"],["أُو۟لَـٰٓئِكَ","Those"],["أَصْحَـٰبُ","(are the) companions"],["ٱلنَّارِ ۖ","(of) the Fire"],["هُمْ","they"],["فِيهَا","in it"],["خَـٰلِدُونَ","(will) abide forever"]]],"1392":["(Dan) ingatlah (suatu hari, ketika itu Kami mengumpulkan mereka) yakni semua makhluk (semuanya, kemudian Kami berkata kepada orang-orang yang mempersekutukan Tuhan, \"Tetaplah pada tempat kalian) lafal makaanakum dinashabkan oleh ilzamuu yang keberadaannya diperkirakan pada sebelumnya (kalian semuanya) lafal ini bersifat mengukuhkan dhamir mustatar yang terkandung di dalam fi'il yang keberadaannya diperkirakan tadi, kemudian diathafkan kepadanya (bersama dengan sekutu-sekutu kalian) yakni berhala-berhala sesembahan kalian. (Lalu Kami pisahkan) Kami bedakan (antara mereka\") dan orang-orang yang beriman, sebagaimana yang telah disebutkan dalam ayat: (Dan dikatakan kepada orang-orang kafir), 'Berpisahlah kalian (dari orang-orang mukmin) pada hari ini, hai orang-orang yang berbuat jahat. (Yasin 59). (Dan berkatalah) kepada mereka (sekutu-sekutu mereka, \"Kalian sekali-kali tidak pernah menyembah kami) huruf maa bermakna nafi, kemudian maf'ul didahulukan demi untuk fashilah.",[["وَيَوْمَ","And (the) Day"],["نَحْشُرُهُمْ","We will gather them"],["جَمِيعًۭا","all together"],["ثُمَّ","then"],["نَقُولُ","We will say"],["لِلَّذِينَ","to those who"],["أَشْرَكُوا۟","associate partners (with Allah)"],["مَكَانَكُمْ","(Remain in) your place"],["أَنتُمْ","you"],["وَشُرَكَآؤُكُمْ ۚ","and your partners"],["فَزَيَّلْنَا","Then We will separate"],["بَيْنَهُمْ ۖ","[between] them"],["وَقَالَ","and (will) say"],["شُرَكَآؤُهُم","their partners"],["مَّا","Not"],["كُنتُمْ","you used (to)"],["إِيَّانَا","worship us"],["تَعْبُدُونَ","worship us"]]],"1393":["(Dan cukuplah Allah menjadi saksi antara kami dengan kalian, sesungguhnya) huruf in adalah mukhaffafah dari inna (kami tidak tahu-menahu tentang penyembahan kalian kepada kami.\")",[["فَكَفَىٰ","So sufficient"],["بِٱللَّهِ","(is) Allah"],["شَهِيدًۢا","(as) a witness"],["بَيْنَنَا","between us"],["وَبَيْنَكُمْ","and between you"],["إِن","that"],["كُنَّا","we were"],["عَنْ","of"],["عِبَادَتِكُمْ","your worship"],["لَغَـٰفِلِينَ","certainly unaware"]]],"1394":["(Di tempat itu) yakni pada hari itu (akan merasakan pembalasan) lafal tabluu berasal dari mashdar al-balwaa. Akan tetapi menurut qiraat lainnya dibaca tatluu berasal dari mashdar tilaawah; artinya dibacakan (tiap-tiap diri dari apa yang telah dikerjakannya dahulu) amal-amal perbuatan yang telah mereka kerjakan di dunia (dan mereka dikembalikan kepada Allah Pelindung mereka yang sebenarnya) pelindung yang hak dan yang selama-lamanya (dan lenyaplah) hilanglah (dari mereka apa yang mereka ada-adakan) terhadap Allah swt. yaitu berupa sekutu-sekutu yang mereka sembah itu.",[["هُنَالِكَ","There"],["تَبْلُوا۟","will be put to trial"],["كُلُّ","every"],["نَفْسٍۢ","soul"],["مَّآ","(for) what"],["أَسْلَفَتْ ۚ","it did previously"],["وَرُدُّوٓا۟","and they will be returned"],["إِلَى","to"],["ٱللَّهِ","Allah"],["مَوْلَىٰهُمُ","their Lord"],["ٱلْحَقِّ ۖ","the true"],["وَضَلَّ","and will be lost"],["عَنْهُم","from them"],["مَّا","what"],["كَانُوا۟","they used (to)"],["يَفْتَرُونَ","invent"]]],"1395":["(Katakanlah,) kepada mereka (\"Siapakah yang memberi rezeki kepada kalian dari langit) yaitu melalui hujan (dan bumi) yaitu melalui tumbuh-tumbuhan (atau siapakah yang kuasa menciptakan pendengaran) lafal as-sam`u di sini bermakna al-asma`; artinya yang menciptakan pendengaran (dan penglihatan dan siapakah yang mengeluarkan yang hidup dari yang mati dan mengeluarkan yang mati dari yang hidup dan siapakah yang mengatur segala urusan?\") di antara makhluk semuanya. (Maka mereka katakan,) bahwa Dia (\"Allah.\" Maka katakanlah,) kepada mereka (\"Mengapa kalian tidak bertakwa.\") kepada-Nya, oleh sebab itu berimanlah kalian.",[["قُلْ","Say"],["مَن","Who"],["يَرْزُقُكُم","provides for you"],["مِّنَ","from"],["ٱلسَّمَآءِ","the sky"],["وَٱلْأَرْضِ","and the earth"],["أَمَّن","Or who"],["يَمْلِكُ","controls"],["ٱلسَّمْعَ","the hearing"],["وَٱلْأَبْصَـٰرَ","and the sight"],["وَمَن","And who"],["يُخْرِجُ","brings out"],["ٱلْحَىَّ","the living"],["مِنَ","from"],["ٱلْمَيِّتِ","the dead"],["وَيُخْرِجُ","and brings forth"],["ٱلْمَيِّتَ","the dead"],["مِنَ","from"],["ٱلْحَىِّ","the living"],["وَمَن","And who"],["يُدَبِّرُ","disposes"],["ٱلْأَمْرَ ۚ","the affairs"],["فَسَيَقُولُونَ","Then they will say"],["ٱللَّهُ ۚ","Allah"],["فَقُلْ","Then say"],["أَفَلَا","Then will not"],["تَتَّقُونَ","you fear (Him)"]]],"1396":["(Maka yang demikian itu) Zat Yang menciptakan segala sesuatu itu (adalah Allah, Rabb kalian yang sebenarnya) yang tetap dan wajib kalian sembah (maka tidak ada sesudah kebenaran itu melainkan kesesatan) Istifham atau kata tanya di sini bermakna menetapkan; artinya tidak ada sesudah kebenaran itu melainkan hanya kesesatan belaka. Barang siapa yang menyimpang dari kebenaran yaitu menyembah selain kepada Allah berarti ia terjerumus ke dalam kesesatan (Maka bagaimanakah) mengapa (kalian dipalingkan?) dari keimanan padahal bukti-bukti kebenaran telah cukup ada.",[["فَذَٰلِكُمُ","For that"],["ٱللَّهُ","(is) Allah"],["رَبُّكُمُ","your Lord"],["ٱلْحَقُّ ۖ","the true"],["فَمَاذَا","So what (can be)"],["بَعْدَ","after"],["ٱلْحَقِّ","the truth"],["إِلَّا","except"],["ٱلضَّلَـٰلُ ۖ","the error"],["فَأَنَّىٰ","So how"],["تُصْرَفُونَ","(are) you turned away"]]],"1397":["(Demikianlah) sebagaimana mereka berpaling daripada iman (telah tetap hukuman Rabbmu terhadap orang-orang yang fasik) yakni orang-orang kafir, seperti yang diungkapkan oleh firman Allah yang lain, yaitu: \"Benar-benar Aku akan mengisi neraka Jahanam...\" (Q.S. Al-A`raf 18, Hud 119, As-Sajdah 32, Shad 85), atau hukuman Allah itu disebabkan (karena mereka tidak beriman.)",[["كَذَٰلِكَ","Thus"],["حَقَّتْ","(is) proved true"],["كَلِمَتُ","(the) Word"],["رَبِّكَ","(of) your Lord"],["عَلَى","upon"],["ٱلَّذِينَ","those who"],["فَسَقُوٓا۟","defiantly disobeyed"],["أَنَّهُمْ","that they"],["لَا","(will) not"],["يُؤْمِنُونَ","believe"]]],"1398":["(Katakanlah, \"Apakah di antara sekutu-sekutu kalian ada yang dapat memulai penciptaan makhluk, kemudian mengulanginya atau menghidupkannya kembali?\" Katakanlah, \"Allahlah yang memulai penciptaan makhluk kemudian mengulanginya atau menghidupkannya kembali; maka bagaimanakah kalian dipalingkan?\") dari menyembah Allah swt. padahal bukti-bukti yang menunjukkan Allah disembah sudah ada.",[["قُلْ","Say"],["هَلْ","Is (there)"],["مِن","of"],["شُرَكَآئِكُم","your partners"],["مَّن","(any) who"],["يَبْدَؤُا۟","originates"],["ٱلْخَلْقَ","the creation"],["ثُمَّ","then"],["يُعِيدُهُۥ ۚ","repeats it"],["قُلِ","Say"],["ٱللَّهُ","Allah"],["يَبْدَؤُا۟","originates"],["ٱلْخَلْقَ","the creation"],["ثُمَّ","then"],["يُعِيدُهُۥ ۖ","repeats it"],["فَأَنَّىٰ","So how"],["تُؤْفَكُونَ","you are deluded"]]],"1399":["(Katakanlah, \"Apakah di antara sekutu-sekutu kalian ada yang dapat menunjuki kepada kebenaran?\") dengan menegakkan hujah-hujah dan memberikan petunjuk (Katakanlah, \"Allahlah yang menunjuki kepada kebenaran.\" Maka apakah Zat yang menunjuki kepada kebenaran itu) yang dimaksud adalah Allah (lebih berhak diikuti ataukah orang yang tidak dapat memberi petunjuk) lafal yahiddiy asalnya yahtadii; artinya mendapat petunjuk (kecuali bila diberi petunjuk?) lebih berhak untuk diikuti? Kata tanya di sini mengandung makna mengukuhkan dan sekaligus sebagai celaan, makna yang dimaksud ialah bahwa yang pertamalah yang lebih berhak untuk diikuti (Mengapa kalian berbuat demikian? Bagaimanakah kalian mengambil keputusan) dengan keputusan yang rusak ini, yaitu mengikuti orang-orang yang tidak berhak untuk diikuti.",[["قُلْ","Say"],["هَلْ","Is (there)"],["مِن","of"],["شُرَكَآئِكُم","your partners"],["مَّن","(any) who"],["يَهْدِىٓ","guides"],["إِلَى","to"],["ٱلْحَقِّ ۚ","the truth"],["قُلِ","Say"],["ٱللَّهُ","Allah"],["يَهْدِى","guides"],["لِلْحَقِّ ۗ","to the truth"],["أَفَمَن","Is then (he) who"],["يَهْدِىٓ","guides"],["إِلَى","to"],["ٱلْحَقِّ","the truth"],["أَحَقُّ","more worthy"],["أَن","that"],["يُتَّبَعَ","he should be followed"],["أَمَّن","or (he) who"],["لَّا","(does) not"],["يَهِدِّىٓ","guide"],["إِلَّآ","unless"],["أَن","[that]"],["يُهْدَىٰ ۖ","he is guided"],["فَمَا","Then what"],["لَكُمْ","(is) for you"],["كَيْفَ","how"],["تَحْكُمُونَ","you judge"]]],"1400":["(Dan kebanyakan mereka tidak mengikuti) di dalam penyembahan mereka terhadap berhala-berhala (kecuali persangkaan saja) dalam hal ini mereka hanya menirukan apa yang telah diperbuat oleh nenek-moyang mereka (Sesungguhnya prasangka itu tidak sedikit pun berguna untuk mencapai kebenaran) yang membutuhkan ilmu pengetahuan tentangnya (Sesungguhnya Allah Maha Mengetahui apa yang mereka kerjakan) oleh sebab itu maka Dia membalas semua amal perbuatan yang telah mereka kerjakan itu.",[["وَمَا","And not"],["يَتَّبِعُ","follow"],["أَكْثَرُهُمْ","most of them"],["إِلَّا","except"],["ظَنًّا ۚ","assumption"],["إِنَّ","Indeed"],["ٱلظَّنَّ","the assumption"],["لَا","(does) not"],["يُغْنِى","avail"],["مِنَ","against"],["ٱلْحَقِّ","the truth"],["شَيْـًٔا ۚ","anything"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَلِيمٌۢ","(is) All-Knower"],["بِمَا","of what"],["يَفْعَلُونَ","they do"]]],"1401":["(Tidaklah mungkin Alquran ini dibuat) artinya dibuat-buat (oleh selain Allah) hanya Dialah yang membuatnya bukan selainnya (akan tetapi) Alquran itu diturunkan (membenarkan apa-apa yang sebelumnya) yaitu berupa kitab-kitab sebelumnya (dan menjelaskan hukum-hukum yang telah ditetapkan-Nya) artinya Alquran itu menjelaskan hukum-hukum yang telah ditentukan oleh Allah dan masalah-masalah lainnya (tidak ada keraguan) tidak ada syakwasangka lagi (di dalamnya, diturunkan dari Rabb semesta alam) lafal min rabbil `aalamiina berkaitan dengan lafal tashdiiqan, atau berkaitan dengan lafal unzila yang tidak disebutkan. Lafal tashdiiqan dan lafal tafshiilan dapat pula dibaca rafa' sehingga menjadi tashdiiqun dan tafshiilun akan tetapi berdasarkan perkiraan adanya lafal huwa sebelumnya.",[["وَمَا","And not"],["كَانَ","is"],["هَـٰذَا","this"],["ٱلْقُرْءَانُ","the Quran"],["أَن","that"],["يُفْتَرَىٰ","(it could be) produced"],["مِن","by"],["دُونِ","other than Allah"],["ٱللَّهِ","other than Allah"],["وَلَـٰكِن","but"],["تَصْدِيقَ","(it is) a confirmation"],["ٱلَّذِى","(of that) which"],["بَيْنَ","(was) before it"],["يَدَيْهِ","(was) before it"],["وَتَفْصِيلَ","and a detailed explanation"],["ٱلْكِتَـٰبِ","(of) the Book"],["لَا","(there is) no"],["رَيْبَ","doubt"],["فِيهِ","in it"],["مِن","from"],["رَّبِّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"1402":["(Atau) patutkah (mereka mengatakan, \"Muhammad membuat-buatnya.\") yakni Nabi Muhammad saw. telah membuatnya sendiri. (Katakanlah, \"Kalau benar yang kalian katakan itu, maka cobalah datangkan sebuah surah seumpamanya) dalam hal kefasihan dan keparamasastraannya yang kalian buat sendiri, bukankah kalian itu adalah orang-orang Arab yang fasih dalam berbahasa sama denganku (dan panggillah) untuk membantu dalam hal ini (siapa-siapa yang dapat kalian panggil selain Allah) selain daripada Allah (jika kalian orang-orang yang benar\") bahwasanya Alquran itu adalah buatan belaka, niscaya kalian tidak akan mampu melakukannya. Selanjutnya Allah berfirman:",[["أَمْ","Or"],["يَقُولُونَ","(do) they say"],["ٱفْتَرَىٰهُ ۖ","He has invented it"],["قُلْ","Say"],["فَأْتُوا۟","Then bring"],["بِسُورَةٍۢ","a Surah"],["مِّثْلِهِۦ","like it"],["وَٱدْعُوا۟","and call"],["مَنِ","whoever"],["ٱسْتَطَعْتُم","you can"],["مِّن","besides Allah"],["دُونِ","besides Allah"],["ٱللَّهِ","besides Allah"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"1403":["(Yang sebenarnya, mereka mendustakan apa yang mereka belum mengetahuinya dengan sempurna) subjek yang dimaksud adalah Alquran; mereka sama sekali tidak mau memikirkan tentangnya (dan belum pernah) tidak pernah (datang kepada mereka penjelasannya) akibat dari apa yang terkandung di dalamnya, yaitu berupa ancaman. (Demikianlah) yakni kedustaan itu (orang-orang yang sebelum mereka telah mendustakan) rasul-rasul mereka (Maka perhatikanlah bagaimana akibat orang-orang yang lalim itu) yaitu mereka yang mendustakan para rasul, makna yang dimaksud ialah kebinasaan yang telah menimpa mereka, demikian pula Kami akan membinasakan mereka yang mendustakannya.",[["بَلْ","Nay"],["كَذَّبُوا۟","they denied"],["بِمَا","what"],["لَمْ","not"],["يُحِيطُوا۟","they could encompass"],["بِعِلْمِهِۦ","(of) its knowledge"],["وَلَمَّا","and not"],["يَأْتِهِمْ","has come (to) them"],["تَأْوِيلُهُۥ ۚ","its interpretation"],["كَذَٰلِكَ","Thus"],["كَذَّبَ","denied"],["ٱلَّذِينَ","those"],["مِن","before them"],["قَبْلِهِمْ ۖ","before them"],["فَٱنظُرْ","then see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلظَّـٰلِمِينَ","(of) the wrongdoers"]]],"1404":["(Di antara mereka) penduduk Mekah (ada arang-orang yang beriman kepada Alquran) hal ini diketahui oleh Allah (dan di antara mereka ada pula orang-orang yang tidak beriman kepadanya) untuk selama-lamanya. (Rabbmu lebih mengetahui tentang orang-orang yang berbuat kerusakan) hal ini merupakan ancaman yang ditujukan kepada mereka yang tidak beriman kepadanya,",[["وَمِنْهُم","And of them"],["مَّن","(is one) who"],["يُؤْمِنُ","believes"],["بِهِۦ","in it"],["وَمِنْهُم","and of them"],["مَّن","(is one) who"],["لَّا","(does) not"],["يُؤْمِنُ","believe"],["بِهِۦ ۚ","in it"],["وَرَبُّكَ","And your Lord"],["أَعْلَمُ","(is) All-Knower"],["بِٱلْمُفْسِدِينَ","of the corrupters"]]],"1405":["(Jika mereka mendustakan kamu, maka katakanlah,) kepada mereka (\"Bagiku pekerjaanku dan bagi kalian pekerjaan kalian) artinya bagi masing-masing pihak menanggung akibat perbuatannya sendiri. Kalian berlepas diri terhadap apa yang aku kerjakan dan aku berlepas diri terhadap apa yang kalian kerjakan.\") akan tetapi ayat itu dinasakh oleh ayatus-saif atau ayat yang menganjurkan memerangi mereka.",[["وَإِن","And if"],["كَذَّبُوكَ","they deny you"],["فَقُل","then say"],["لِّى","For me"],["عَمَلِى","(are) my deeds"],["وَلَكُمْ","and for you"],["عَمَلُكُمْ ۖ","(are) your deeds"],["أَنتُم","You"],["بَرِيٓـُٔونَ","(are) disassociated"],["مِمَّآ","from what"],["أَعْمَلُ","I do"],["وَأَنَا۠","and I am"],["بَرِىٓءٌۭ","disassociated"],["مِّمَّا","from what"],["تَعْمَلُونَ","you do"]]],"1406":["(Dan di antara mereka ada orang yang mendengarkanmu) jika kamu membacakan Alquran (apakah kamu dapat menjadikan orang-orang tuli itu mendengar) keadaan mereka yang tidak mau mengambil manfaat daripada Alquran yang dibacakan kepada mereka diserupakan dengan keadaan orang-orang yang tuli (walaupun keadaan mereka) di samping tuli itu (tidak mengerti) tidak mau berpikir.",[["وَمِنْهُم","And among them"],["مَّن","(are some) who"],["يَسْتَمِعُونَ","listen"],["إِلَيْكَ ۚ","to you"],["أَفَأَنتَ","But (can) you"],["تُسْمِعُ","cause the deaf to hear"],["ٱلصُّمَّ","cause the deaf to hear"],["وَلَوْ","even though"],["كَانُوا۟","they [were]"],["لَا","(do) not"],["يَعْقِلُونَ","use reason"]]],"1407":["(Dan di antara mereka ada orang yang melihat kepadamu, apakah dapat kamu memberi petunjuk kepada orang-orang yang buta, walaupun mereka tidak dapat memperhatikan) Allah swt. menyerupakan keadaan mereka dengan keadaan orang-orang yang tidak dapat melihat, karena mereka tidak mau mengambil petunjuk dari apa yang mereka lihat. Bahkan keadaan mereka lebih parah lagi; gambaran ini diungkapkan pula di dalam firman-Nya yang lain, yaitu, \"Karena sesungguhnya bukanlah mata itu yang buta, tetapi yang buta ialah hati yang di dalam dada.\" (Al-Hajj 46).",[["وَمِنْهُم","And among them"],["مَّن","(are some) who"],["يَنظُرُ","look"],["إِلَيْكَ ۚ","at you"],["أَفَأَنتَ","But (can) you"],["تَهْدِى","guide"],["ٱلْعُمْىَ","the blind"],["وَلَوْ","even though"],["كَانُوا۟","they [were]"],["لَا","(do) not"],["يُبْصِرُونَ","see"]]],"1408":["(Sesungguhnya Allah tidak berbuat lalim kepada manusia sedikit pun, akan tetapi manusia itulah yang berbuat lalim kepada diri mereka sendiri).",[["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَظْلِمُ","wrong"],["ٱلنَّاسَ","the people"],["شَيْـًۭٔا","(in) anything"],["وَلَـٰكِنَّ","but"],["ٱلنَّاسَ","the people"],["أَنفُسَهُمْ","wrong themselves"],["يَظْلِمُونَ","wrong themselves"]]],"1409":["(Dan di hari ketika Allah mengumpulkan mereka, seakan-akan) artinya keadaan mereka seolah-olah (tidak pernah tinggal) di dunia atau di alam kubur (melainkan hanya sesaat saja di siang hari) mengingat kengerian yang mereka lihat pada saat itu. Jumlah tasybih atau kalimat ka-allam yalbatsuu illaa saa'atan minan nahaar menjadi hal atau kata keterangan daripada dhamir maf'ul yang terdapat di dalam lafal yahsyuruhum (mereka saling berkenalan di antara sesama mereka) sebagian di antara mereka berkenalan dengan sebagian yang lain bila mereka dibangkitkan dari alam kubur, kemudian terputuslah perkenalan mereka mengingat ngerinya keadaan yang sedang mereka hadapi. Kalimat ayat ini menjadi jumlah hal yang muqaddarah atau berta'alluq pada zharaf. (Sesungguhnya rugilah orang-orang yang mendustakan pertemuan mereka dengan Allah) yaitu mereka yang tidak mempercayai adanya hari berbangkit (dan mereka tidak mendapat petunjuk).",[["وَيَوْمَ","And the Day"],["يَحْشُرُهُمْ","He will gather them"],["كَأَن","as if"],["لَّمْ","they had not remained"],["يَلْبَثُوٓا۟","they had not remained"],["إِلَّا","except"],["سَاعَةًۭ","an hour"],["مِّنَ","of"],["ٱلنَّهَارِ","the day"],["يَتَعَارَفُونَ","they will recognize each other"],["بَيْنَهُمْ ۚ","between them"],["قَدْ","Certainly"],["خَسِرَ","(will have) lost"],["ٱلَّذِينَ","those who"],["كَذَّبُوا۟","denied"],["بِلِقَآءِ","the meeting"],["ٱللَّهِ","(with) Allah"],["وَمَا","and not"],["كَانُوا۟","they were"],["مُهْتَدِينَ","the guided ones"]]],"1410":["(Dan jika) lafal immaa ini asalnya adalah terdiri dari in syarthiyah dan maa zaidah yang digabungkan menjadi satu (Kami perlihatkan kepadamu sebagian dari apa yang Kami ancamkan kepada mereka) berupa azab, di dalam hidupmu. Jawab syarath dibuang, lengkapnya adalah fadzaaka, artinya tentulah kamu dapat menyaksikannya (atau jika Kami wafatkan kamu) sebelum mereka tertimpa azab (maka kepada Kamilah mereka kembali, dan Allah menjadi saksi) selalu melihat (atas apa yang mereka kerjakan) berupa kedustaan mereka dan kekafiran yang mereka lakukan itu, kelak Allah akan mengazab mereka dengan siksaan yang amat keras.",[["وَإِمَّا","And whether"],["نُرِيَنَّكَ","We show you"],["بَعْضَ","some"],["ٱلَّذِى","(of) that which"],["نَعِدُهُمْ","We promised them"],["أَوْ","or"],["نَتَوَفَّيَنَّكَ","We cause you to die"],["فَإِلَيْنَا","then to Us"],["مَرْجِعُهُمْ","(is) their return"],["ثُمَّ","then"],["ٱللَّهُ","Allah"],["شَهِيدٌ","(is) a Witness"],["عَلَىٰ","over"],["مَا","what"],["يَفْعَلُونَ","they do"]]],"1411":["(Tiap-tiap umat) dari umat-umat semuanya (mempunyai rasul, maka apabila telah datang rasul mereka) kepadanya mereka mendustakannya (diberikanlah keputusan antara mereka dengan adil) secara adil; untuk itu Allah mengazab mereka dan menyelamatkan rasul-Nya bersama orang-orang yang beriman kepadanya (dan mereka sedikit pun tidak dianiaya) seumpamanya mereka diazab tanpa dosa. Demikianlah Kami melakukan hal yang serupa terhadap mereka.",[["وَلِكُلِّ","And for every"],["أُمَّةٍۢ","nation"],["رَّسُولٌۭ ۖ","(is) a Messenger"],["فَإِذَا","So when"],["جَآءَ","comes"],["رَسُولُهُمْ","their Messenger"],["قُضِىَ","it will be judged"],["بَيْنَهُم","between them"],["بِٱلْقِسْطِ","in justice"],["وَهُمْ","and they"],["لَا","(will) not"],["يُظْلَمُونَ","be wronged"]]],"1412":["(Mereka mengatakan, \"Bilakah datangnya ancaman itu) siksaan itu (jika memang kalian orang-orang yang benar?\") dalam hal ini.",[["وَيَقُولُونَ","And they say"],["مَتَىٰ","When"],["هَـٰذَا","(will) this"],["ٱلْوَعْدُ","the promise (be fulfilled)"],["إِن","if"],["كُنتُمْ","you are"],["صَـٰدِقِينَ","truthful"]]],"1413":["(Katakanlah, \"Aku tidak berkuasa untuk mendatangkan kemudaratan kepada diriku) yang aku dapat menolaknya (dan tidak pula kemanfaatan) yang aku dapat menariknya (melainkan apa yang dikehendaki Allah?\") bila memang Allah telah memastikannya terhadap diriku. Bagaimana aku dapat berkuasa untuk menurunkan azab kepada kalian. (Tiap-tiap umat mempunyai ajal) masa yang telah dimaklumi bagi kebinasaan mereka. (Maka apabila telah datang ajal mereka, maka mereka tidak dapat menangguhkannya) tidak dapat menangguhkan kedatangan azab itu (barang sedikit pun dan tidak pula mendahulukannya) menyegerakan datangnya azab itu.",[["قُل","Say"],["لَّآ","Not"],["أَمْلِكُ","I have power"],["لِنَفْسِى","for myself"],["ضَرًّۭا","(for) any harm"],["وَلَا","and not"],["نَفْعًا","(for) any profit"],["إِلَّا","except"],["مَا","what"],["شَآءَ","Allah wills"],["ٱللَّهُ ۗ","Allah wills"],["لِكُلِّ","For every"],["أُمَّةٍ","nation"],["أَجَلٌ ۚ","(is) a term"],["إِذَا","When"],["جَآءَ","comes"],["أَجَلُهُمْ","their term"],["فَلَا","then not"],["يَسْتَـْٔخِرُونَ","they remain behind"],["سَاعَةًۭ ۖ","an hour"],["وَلَا","and not"],["يَسْتَقْدِمُونَ","they can precede (it)"]]],"1414":["(Katakanlah, \"Terangkanlah) ceritakanlah kepadaku (jika datang kepada kalian siksaan-Nya) yakni azab Allah (di waktu malam hari) (atau di siang hari, apakah) benar (minta disegerakan juga datangnya azab itu) siksaan itu (oleh orang-orang yang berdosa?\") yakni orang-orang musyrik. Di dalam ayat ini terkandung ungkapan meletakkan isim zhahir pada tempat isim dhamir. Jumlah istifham dalam ayat ini merupakan jawab syarat; perihalnya sama dengan ucapan anda, \"idzaa ataituka madzaa tu'thiiniy?\" (Jika aku datang berkunjung kepadamu, apakah yang akan engkau berikan kepadaku). Adapun pengertian yang dimaksud daripada makna ayat ini ialah menggambarkan kengerian; atau dengan kata lain, alangkah ngerinya apa yang mereka minta supaya disegerakan.",[["قُلْ","Say"],["أَرَءَيْتُمْ","Do you see"],["إِنْ","if"],["أَتَىٰكُمْ","comes to you"],["عَذَابُهُۥ","His punishment"],["بَيَـٰتًا","(by) night"],["أَوْ","or"],["نَهَارًۭا","(by) day"],["مَّاذَا","what (portion)"],["يَسْتَعْجِلُ","of it would (wish to) hasten"],["مِنْهُ","of it would (wish to) hasten"],["ٱلْمُجْرِمُونَ","the criminals"]]],"1415":["(Kemudian apakah setelah terjadinya azab itu) setelah siksaan menimpa kalian (kemudian itu kalian baru mempercayainya?) percaya kepada Allah atau percaya kepada azab-Nya sewaktu azab itu diturunkan. Hamzah di sini mengandung makna mengingkari adanya penangguhan azab. Kala itu iman kalian tidak dapat diterima, kemudian akan dikatakan kepada kalian (Apakah baru sekarang) kalian mempercayainya? (padahal sebelumnya kalian selalu meminta supaya disegerakan) kalimat ayat ini mengandung arti cemoohan.",[["أَثُمَّ","Is (it) then"],["إِذَا","when"],["مَا","when"],["وَقَعَ","(it had) occurred"],["ءَامَنتُم","you (will) believe"],["بِهِۦٓ ۚ","in it"],["ءَآلْـَٔـٰنَ","Now"],["وَقَدْ","And certainly"],["كُنتُم","you were"],["بِهِۦ","seeking to hasten it"],["تَسْتَعْجِلُونَ","seeking to hasten it"]]],"1416":["(Kemudian dikatakan kepada orang-orang yang lalim atau musyrik itu, \"Rasakanlah oleh kalian siksaan yang kekal) artinya siksaan yang kalian kekal di dalamnya (tidaklah) (kalian diberi balasan melainkan) pembalasan (dengan apa yang telah kalian kerjakan\").",[["ثُمَّ","Then"],["قِيلَ","it will be said"],["لِلَّذِينَ","to those who"],["ظَلَمُوا۟","wronged"],["ذُوقُوا۟","Taste"],["عَذَابَ","punishment"],["ٱلْخُلْدِ","the everlasting"],["هَلْ","Are you (being) recompensed"],["تُجْزَوْنَ","Are you (being) recompensed"],["إِلَّا","except"],["بِمَا","for what"],["كُنتُمْ","you used (to)"],["تَكْسِبُونَ","earn"]]],"1417":["(Dan mereka menanyakan kepadamu) meminta penjelasan darimu (\"Benarkah hal itu?\") artinya apa yang telah engkau ancamkan kepada kami berupa siksaan dan dibangkitkan dari kubur itu? (Katakanlah, \"Ya,) benar (demi Rabbku, sesungguhnya azab itu adalah benar dan kalian sekali-kali tidak dapat luput.\") tidak dapat selamat daripadanya.",[["۞ وَيَسْتَنۢبِـُٔونَكَ","And they ask you to inform"],["أَحَقٌّ","Is it true"],["هُوَ ۖ","Is it true"],["قُلْ","Say"],["إِى","Yes"],["وَرَبِّىٓ","by my Lord"],["إِنَّهُۥ","Indeed, it"],["لَحَقٌّۭ ۖ","(is) surely the truth"],["وَمَآ","and not"],["أَنتُم","you"],["بِمُعْجِزِينَ","(can) escape (it)"]]],"1418":["(Dan kalau setiap diri yang lalim itu) yang kafir itu (mempunyai segala apa yang ada di bumi ini) kekayaan yang terdapat di bumi ini (tentu dia menebus dirinya dengan itu) demi menyelamatkan diri dari azab di hari kiamat (dan mereka menyembunyikan penyesalannya) karena tidak mau beriman (ketika mereka telah menyaksikan azab itu) para pemimpin orang-orang musyrik itu dengan sengaja menyembunyikan rasa penyesalannya dari mata orang-orang lemah mereka yang telah mereka sesatkan, karena mereka takut mendapatkan celaan. (Dan telah diberikan keputusan di antara mereka) yakni di antara makhluk (dengan adil) secara adil (sedangkan mereka tidak dianiaya) sedikit pun.",[["وَلَوْ","And if"],["أَنَّ","that"],["لِكُلِّ","for every"],["نَفْسٍۢ","soul"],["ظَلَمَتْ","(that) wronged"],["مَا","whatever"],["فِى","(is) in"],["ٱلْأَرْضِ","the earth"],["لَٱفْتَدَتْ","it (would) seek to ransom"],["بِهِۦ ۗ","with it"],["وَأَسَرُّوا۟","and they (will) confide"],["ٱلنَّدَامَةَ","the regret"],["لَمَّا","when"],["رَأَوُا۟","they see"],["ٱلْعَذَابَ ۖ","the punishment"],["وَقُضِىَ","But will be judged"],["بَيْنَهُم","between them"],["بِٱلْقِسْطِ ۚ","in justice"],["وَهُمْ","and they"],["لَا","(will) not"],["يُظْلَمُونَ","(be) wronged"]]],"1419":["(Ingatlah, sesungguhnya kepunyaan Allah apa yang ada di langit dan di bumi. Ingatlah sesungguhnya janji Allah itu) mengenai hari berbangkit dan hari pembalasan (benar) pasti (tetapi kebanyakan mereka) manusia (tidak mengetahui) hal itu.",[["أَلَآ","No doubt"],["إِنَّ","indeed"],["لِلَّهِ","for Allah"],["مَا","(is) whatever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ ۗ","and the earth"],["أَلَآ","No doubt"],["إِنَّ","indeed"],["وَعْدَ","(the) Promise of Allah"],["ٱللَّهِ","(the) Promise of Allah"],["حَقٌّۭ","(is) true"],["وَلَـٰكِنَّ","But"],["أَكْثَرَهُمْ","most of them"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1420":["(Dialah yang menghidupkan dan mematikan dan hanya kepada-Nyalah kalian dikembalikan) di hari kemudian, kemudian Dia membalas kalian atas amal perbuatan kalian.",[["هُوَ","He"],["يُحْىِۦ","gives life"],["وَيُمِيتُ","and causes death"],["وَإِلَيْهِ","and to Him"],["تُرْجَعُونَ","you will be returned"]]],"1421":["(Hai manusia) yakni penduduk Mekah (sesungguhnya telah datang kepada kalian pelajaran dari Rabb kalian) berupa Alkitab yang di dalamnya dijelaskan hal-hal yang bermanfaat dan hal-hal yang mudarat bagi diri kalian, yaitu berupa kitab Alquran (dan penyembuh) penawar (bagi penyakit-penyakit yang ada di dalam dada) yakni penyakit akidah yang rusak dan keragu-raguan (dan petunjuk) dari kesesatan (serta rahmat bagi orang-orang yang beriman) kepadanya.",[["يَـٰٓأَيُّهَا","O mankind"],["ٱلنَّاسُ","O mankind"],["قَدْ","Verily"],["جَآءَتْكُم","has come to you"],["مَّوْعِظَةٌۭ","an instruction"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["وَشِفَآءٌۭ","and a healing"],["لِّمَا","for what"],["فِى","(is) in"],["ٱلصُّدُورِ","your breasts"],["وَهُدًۭى","and guidance"],["وَرَحْمَةٌۭ","and mercy"],["لِّلْمُؤْمِنِينَ","for the believers"]]],"1422":["(Katakanlah, \"Dengan karunia Allah) yaitu agama Islam (dan rahmat-Nya) yaitu Alquran (maka dengan hal itu) dengan karunia dan rahmat tersebut (hendaklah mereka bergembira. Karunia Allah dan rahmat-Nya itu adalah lebih baik daripada apa yang mereka kumpulkan.\") yaitu berupa duniawi. Lafal yajma'uuna dapat dibaca tajma'uuna.",[["قُلْ","Say"],["بِفَضْلِ","In the Bounty"],["ٱللَّهِ","(of) Allah"],["وَبِرَحْمَتِهِۦ","and in His Mercy"],["فَبِذَٰلِكَ","so in that"],["فَلْيَفْرَحُوا۟","let them rejoice"],["هُوَ","It"],["خَيْرٌۭ","(is) better"],["مِّمَّا","than what"],["يَجْمَعُونَ","they accumulate"]]],"1423":["(Katakanlah, \"Terangkanlah kepadaku) ceritakanlah kepadaku (tentang apa yang telah diturunkan oleh Allah) tentang apa yang telah diciptakan oleh-Nya (bagi kalian berupa rezeki, lalu kalian jadikan sebagiannya haram dan sebagian yang lainnya halal.\") seperti ternak bahirah, ternak saibah dan bangkai. (Katakanlah, \"Apakah Allah telah memberikan izin kepada kalian) tentang ini, yaitu tentang penghalalan dan pengharaman ini; tentu saja tidak (atau) bahkan (kalian mengada-adakan saja terhadap Allah?\") kalian telah berdusta dengan mengaitkan hal tersebut dari Allah.",[["قُلْ","Say"],["أَرَءَيْتُم","Have you seen"],["مَّآ","what"],["أَنزَلَ","(has been) sent down"],["ٱللَّهُ","(by) Allah"],["لَكُم","for you"],["مِّن","of"],["رِّزْقٍۢ","(the) provision"],["فَجَعَلْتُم","and you have made"],["مِّنْهُ","of it"],["حَرَامًۭا","unlawful"],["وَحَلَـٰلًۭا","and lawful"],["قُلْ","Say"],["ءَآللَّهُ","Has Allah"],["أَذِنَ","permitted"],["لَكُمْ ۖ","[to] you"],["أَمْ","or"],["عَلَى","about"],["ٱللَّهِ","Allah"],["تَفْتَرُونَ","you invent (lies)"]]],"1424":["(Apakah dugaan orang-orang yang mengada-adakan kebohongan terhadap Allah) maksudnya apakah dugaan mereka terhadap-Nya (pada hari kiamat) apakah mereka menduga bahwasanya Allah tidak akan menghukum mereka? Tentu saja tidak demikian. (Sesungguhnya Allah benar-benar mempunyai karunia yang dilimpahkan kepada manusia) yaitu dengan menangguhkan mereka dan selalu memberikan nikmat kepada mereka (tetapi kebanyakan mereka tidak bersyukur).",[["وَمَا","And what"],["ظَنُّ","(will be the) assumption"],["ٱلَّذِينَ","(of) those who"],["يَفْتَرُونَ","invent"],["عَلَى","against"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ","the lie"],["يَوْمَ","(on) the Day"],["ٱلْقِيَـٰمَةِ ۗ","(of) the Judgment"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَذُو","(is) surely Full (of) Bounty"],["فَضْلٍ","(is) surely Full (of) Bounty"],["عَلَى","to"],["ٱلنَّاسِ","the mankind"],["وَلَـٰكِنَّ","but"],["أَكْثَرَهُمْ","most of them"],["لَا","(are) not"],["يَشْكُرُونَ","grateful"]]],"1425":["(Kamu tidak berada) hai Muhammad! (dalam suatu keadaan) dalam suatu perkara (dan tidak membaca suatu ayat) artinya mengenai perkara tersebut atau membaca dari Allah (dari Alquran) yang diturunkan oleh-Nya kepadamu (dan kamu tidak mengerjakan) khithab ayat ini ditujukan kepada Nabi Muhammad saw. dan umatnya (suatu pekerjaan, melainkan Kami menjadi saksi atas kalian) meneliti (di waktu kalian melakukan) mengerjakan (perbuatan itu) amal perbuatan itu. (Tidak luput) tidak samar (dari pengetahuan Rabbmu hal yang sebesar) seberat (zarrah) semut yang paling kecil (di bumi atau pun di langit. Tidak ada yang lebih kecil dan tidak pula yang lebih besar dari itu melainkan semua tercatat dalam kitab yang nyata) yang jelas, yaitu Lohmahfuz.",[["وَمَا","And not"],["تَكُونُ","you are"],["فِى","[in]"],["شَأْنٍۢ","any situation"],["وَمَا","and not"],["تَتْلُوا۟","you recite"],["مِنْهُ","of it"],["مِن","from"],["قُرْءَانٍۢ","(the) Quran"],["وَلَا","and not"],["تَعْمَلُونَ","you do"],["مِنْ","any"],["عَمَلٍ","deed"],["إِلَّا","except"],["كُنَّا","We are"],["عَلَيْكُمْ","over you"],["شُهُودًا","witnesses"],["إِذْ","when"],["تُفِيضُونَ","you are engaged"],["فِيهِ ۚ","in it"],["وَمَا","And not"],["يَعْزُبُ","escapes"],["عَن","from"],["رَّبِّكَ","your Lord"],["مِن","of"],["مِّثْقَالِ","(the) weight"],["ذَرَّةٍۢ","(of) an atom"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَلَا","and not"],["فِى","in"],["ٱلسَّمَآءِ","the heavens"],["وَلَآ","and not"],["أَصْغَرَ","smaller"],["مِن","than"],["ذَٰلِكَ","that"],["وَلَآ","and not"],["أَكْبَرَ","greater"],["إِلَّا","but"],["فِى","(is) in"],["كِتَـٰبٍۢ","a Record"],["مُّبِينٍ","clear"]]],"1426":["(Ingatlah, sesungguhnya wali-wali Allah itu tidak ada kekhawatiran terhadap mereka dan tidak pula mereka bersedih hati) di akhirat nanti.",[["أَلَآ","No doubt"],["إِنَّ","Indeed"],["أَوْلِيَآءَ","(the) friends"],["ٱللَّهِ","(of) Allah"],["لَا","(there will be) no"],["خَوْفٌ","fear"],["عَلَيْهِمْ","upon then"],["وَلَا","and not"],["هُمْ","they"],["يَحْزَنُونَ","will grieve"]]],"1427":["(Yaitu orang-orang yang beriman dan mereka selalu bertakwa) kepada Allah dengan menjalankan perintah-Nya dan menjauhi larangan-Nya.",[["ٱلَّذِينَ","Those who"],["ءَامَنُوا۟","believe"],["وَكَانُوا۟","and are"],["يَتَّقُونَ","conscious (of Allah)"]]],"1428":["(Bagi mereka berita gembira di dalam kehidupan dunia) makna ayat ini ditafsirkan oleh hadis sahih yang diketengahkan oleh Imam Hakim, bahwa berita gembira ini berupa mimpi yang baik yang dilihat oleh seorang wali Allah, atau mimpi yang baik itu diperlihatkan kepadanya (dan dalam kehidupan di akhirat) mereka mendapatkan surga dan pahala. (Tidak ada perubahan bagi kalimat-kalimat Allah) janji-janji Allah tidak akan diingkari. (Yang demikian itu) hal yang telah disebutkan itu (adalah kemenangan yang besar).",[["لَهُمُ","For them"],["ٱلْبُشْرَىٰ","(are) the glad tidings"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا","(of) the world"],["وَفِى","and in"],["ٱلْـَٔاخِرَةِ ۚ","the Hereafter"],["لَا","No"],["تَبْدِيلَ","change"],["لِكَلِمَـٰتِ","(is there) in the Words"],["ٱللَّهِ ۚ","(of) Allah"],["ذَٰلِكَ","That"],["هُوَ","is"],["ٱلْفَوْزُ","the success"],["ٱلْعَظِيمُ","the great"]]],"1429":["(Janganlah kamu sedih oleh perkataan mereka) terhadap dirimu, seperti perkataan mereka, \"Engkau adalah bukan utusan Allah,\" dan lain sebagainya. (Sesungguhnya) huruf inna di sini merupakan pertanda isti'naf atau kalimat baru (kekuatan itu) kekuatan (adalah kepunyaan Allah seluruhnya. Dialah Yang Maha Mendengar) semua perkataan (lagi Maha Mengetahui) semua perbuatan, maka karenanya Dia membalas perbuatan mereka dan menolong kamu.",[["وَلَا","And (let) not"],["يَحْزُنكَ","grieve you"],["قَوْلُهُمْ ۘ","their speech"],["إِنَّ","Indeed"],["ٱلْعِزَّةَ","the honor"],["لِلَّهِ","(belongs) to Allah"],["جَمِيعًا ۚ","all"],["هُوَ","He"],["ٱلسَّمِيعُ","(is) the All-Hearer"],["ٱلْعَلِيمُ","the All-Knower"]]],"1430":["(Ingatlah, sesungguhnya kepunyaan Allah semua yang ada di langit dan semua yang ada di bumi) sebagai hamba-Nya, milik-Nya dan sebagai makhluk-Nya. (Dan tidaklah mengikuti orang-orang yang menyeru) yang menyembah (selain daripada Allah) selain Allah, yaitu berupa berhala-berhala (berupa sekutu-sekutu) bagi-Nya secara nyata, Maha Suci Allah dari sekutu-sekutu (tidaklah) tiada lain (mereka mengikuti) dalam hal tersebut (melainkan hanya dugaan saja) mereka menduga bahwa berhala-berhala sesembahan mereka itu adalah tuhan yang dapat memberikan syafaat terhadap diri mereka (dan tidaklah) tiadalah (keadaan mereka melainkan hanya berdusta belaka) yakni berbuat dusta dalam hal tersebut.",[["أَلَآ","No doubt"],["إِنَّ","Indeed"],["لِلَّهِ","to Allah (belongs)"],["مَن","whoever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَمَن","and whoever"],["فِى","(is) in"],["ٱلْأَرْضِ ۗ","the earth"],["وَمَا","And not"],["يَتَّبِعُ","follow"],["ٱلَّذِينَ","those who"],["يَدْعُونَ","invoke"],["مِن","other than Allah"],["دُونِ","other than Allah"],["ٱللَّهِ","other than Allah"],["شُرَكَآءَ ۚ","partners"],["إِن","Not"],["يَتَّبِعُونَ","they follow"],["إِلَّا","but"],["ٱلظَّنَّ","the assumption"],["وَإِنْ","and not"],["هُمْ","they"],["إِلَّا","but"],["يَخْرُصُونَ","guess"]]],"1431":["(Dialah yang menjadikan malam hari bagi kalian supaya kalian beristirahat padanya dan menjadikan siang terang) diisnadkannya lafal al-ibshaar yang artinya melihat kepada lafal an-nahaar yang artinya siang hari mengandung pengertian majaz, karena seseorang dapat melihat pada siang hari. (Sesungguhnya pada yang demikian itu terdapat tanda-tanda) bukti-bukti yang menunjukkan keesaan-Nya (bagi orang-orang yang mendengar) dengan pendengaran yang dibarengi dengan perasaan mengambil pelajaran dan nasihat dari apa yang didengarnya.",[["هُوَ","He"],["ٱلَّذِى","(is) the One Who"],["جَعَلَ","made"],["لَكُمُ","for you"],["ٱلَّيْلَ","the night"],["لِتَسْكُنُوا۟","that you may rest"],["فِيهِ","in it"],["وَٱلنَّهَارَ","and the day"],["مُبْصِرًا ۚ","giving visibility"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَـٰتٍۢ","surely (are) Signs"],["لِّقَوْمٍۢ","for a people"],["يَسْمَعُونَ","(who) listen"]]],"1432":["(Mereka berkata) yang dimaksud adalah orang-orang Yahudi, orang-orang Nasrani dan orang-orang yang menduga bahwa para malaikat itu adalah anak-anak perempuan Allah (\"Allah mempunyai anak,\") maka Allah berfirman kepada mereka (Maha Suci Allah) memahasucikan Allah dari tuduhan mempunyai anak (Dialah Yang Maha Kaya) tidak membutuhkan kepada seseorang pun, dan sesungguhnya orang-orang yang meminta punya anak itu adalah orang yang membutuhkannya. (Kepunyaan-Nya apa yang ada di langit dan apa yang ada di bumi) sebagai milik-Nya, makhluk-Nya dan hamba-Nya (tidak) tiada (bagi kalian suatu hujah pun) bukti (tentang ini) seperti apa yang telah kalian katakan itu. (Pantaskah kalian mengatakan terhadap Allah apa yang kalian tidak ketahui?) kata tanya di sini mengandung pengertian cemoohan.",[["قَالُوا۟","They say"],["ٱتَّخَذَ","Allah has taken"],["ٱللَّهُ","Allah has taken"],["وَلَدًۭا ۗ","a son"],["سُبْحَـٰنَهُۥ ۖ","Glory be to Him"],["هُوَ","He"],["ٱلْغَنِىُّ ۖ","(is) the Self-sufficient"],["لَهُۥ","To Him (belongs)"],["مَا","whatever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَمَا","and whatever"],["فِى","(is) in"],["ٱلْأَرْضِ ۚ","the earth"],["إِنْ","Not"],["عِندَكُم","you have"],["مِّن","any"],["سُلْطَـٰنٍۭ","authority"],["بِهَـٰذَآ ۚ","for this"],["أَتَقُولُونَ","Do you say"],["عَلَى","about"],["ٱللَّهِ","Allah"],["مَا","what"],["لَا","not"],["تَعْلَمُونَ","you know"]]],"1433":["(Katakanlah, \"Sesungguhnya orang-orang yang mengada-adakan kebohongan terhadap Allah) dengan menisbatkan mempunyai anak kepada-Nya (tidak beruntung.\") tidak bahagia.",[["قُلْ","Say"],["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَفْتَرُونَ","invent"],["عَلَى","against"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ","the lie"],["لَا","they will not succeed"],["يُفْلِحُونَ","they will not succeed"]]],"1434":["Bagi mereka (kesenangan) yang sedikit atau sementara (di dunia) yang mereka bersenang-senang dengannya selama hidup mereka di dunia (kemudian kepada Kamilah mereka kembali) dengan dimatikannya mereka (kemudian Kami rasakan kepada mereka siksa yang berat) sesudah mati (disebabkan kekafiran mereka).",[["مَتَـٰعٌۭ","An enjoyment"],["فِى","in"],["ٱلدُّنْيَا","the world"],["ثُمَّ","then"],["إِلَيْنَا","to Us"],["مَرْجِعُهُمْ","(is) their return"],["ثُمَّ","then"],["نُذِيقُهُمُ","We will make them taste"],["ٱلْعَذَابَ","the punishment"],["ٱلشَّدِيدَ","the severe"],["بِمَا","because"],["كَانُوا۟","they used to"],["يَكْفُرُونَ","disbelieve"]]],"1435":["(Dan bacakanlah) hai Muhammad (kepada mereka) orang-orang kafir Mekah (berita penting) cerita penting (tentang Nuh) yaitu (di waktu dia berkata kepada kaumnya, \"Hai kaumku, jika terasa berat) keberatan (bagi kalian tinggal bersamaku) aku berdiam di antara kalian (dan peringatanku) nasihatku terhadap kalian (dengan ayat-ayat Allah, maka kepada Allahlah aku bertawakal, karena itu bulatkanlah keputusan kalian) bulatkanlah tekad kalian tentang perkara yang akan kalian lakukan terhadap diriku (bersama dengan sekutu-sekutu kalian) wawu di sini bermakna ma'a. (Kemudian janganlah keputusan kalian itu dirahasiakan) disembunyikan, akan tetapi tampakkanlah dan berterus-teranglah kepadaku tentang hal itu (lalu lakukanlah terhadap diriku) laksanakanlah apa yang telah kalian kehendaki itu (dan janganlah kalian memberi tangguh kepadaku) menangguh-nangguhkannya, karena sesungguhnya aku tidak akan mempedulikan kalian lagi.",[["۞ وَٱتْلُ","And recite"],["عَلَيْهِمْ","to them"],["نَبَأَ","the news"],["نُوحٍ","(of) Nuh"],["إِذْ","when"],["قَالَ","he said"],["لِقَوْمِهِۦ","to his people"],["يَـٰقَوْمِ","O my people"],["إِن","If"],["كَانَ","is"],["كَبُرَ","hard"],["عَلَيْكُم","on you"],["مَّقَامِى","my stay"],["وَتَذْكِيرِى","and my reminding"],["بِـَٔايَـٰتِ","the Signs of Allah"],["ٱللَّهِ","the Signs of Allah"],["فَعَلَى","then on"],["ٱللَّهِ","Allah"],["تَوَكَّلْتُ","I put my trust"],["فَأَجْمِعُوٓا۟","So you all resolve"],["أَمْرَكُمْ","your plan"],["وَشُرَكَآءَكُمْ","and your partners"],["ثُمَّ","Then"],["لَا","let not be"],["يَكُنْ","let not be"],["أَمْرُكُمْ","(in) your plan"],["عَلَيْكُمْ","for you"],["غُمَّةًۭ","any doubt"],["ثُمَّ","Then"],["ٱقْضُوٓا۟","carry (it out)"],["إِلَىَّ","upon me"],["وَلَا","and (do) not"],["تُنظِرُونِ","give me respite"]]],"1436":["(Jika kalian berpaling) dari peringatanku (aku tidak meminta upah sedikit pun daripada kalian) sebagai imbalan dan upah atas jerih payahku itu, maka berpalinglah kalian (tiada lain) tidak lain (upahku) pahalaku (hanyalah dari Allah belaka dan aku disuruh supaya aku termasuk golongan orang-orang yang berserah diri) kepada-Nya.",[["فَإِن","But if"],["تَوَلَّيْتُمْ","you turn away"],["فَمَا","then not"],["سَأَلْتُكُم","I have asked you"],["مِّنْ","any"],["أَجْرٍ ۖ","reward"],["إِنْ","Not"],["أَجْرِىَ","(is) my reward"],["إِلَّا","but"],["عَلَى","on"],["ٱللَّهِ ۖ","Allah"],["وَأُمِرْتُ","and I have been commanded"],["أَنْ","that"],["أَكُونَ","I be"],["مِنَ","of"],["ٱلْمُسْلِمِينَ","the Muslims"]]],"1437":["(Lalu mereka mendustakan Nuh, maka Kami selamatkan dia dan orang-orang yang bersamanya di dalam bahtera) perahu (dan Kami jadikan mereka itu) orang-orang yang bersama dengan Nabi Nuh (pemegang kekuasaan) di muka bumi (dan Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami) dengan banjir besar (Maka perhatikanlah bagaimana kesudahan orang-orang yang diberi peringatan itu) yaitu dengan binasanya mereka; maka demikian pula Kami akan berlaku sama terhadap orang yang mendustakan rasul.",[["فَكَذَّبُوهُ","But they denied him"],["فَنَجَّيْنَـٰهُ","so We saved him"],["وَمَن","and (those) who"],["مَّعَهُۥ","(were) with him"],["فِى","in"],["ٱلْفُلْكِ","the ship"],["وَجَعَلْنَـٰهُمْ","and We made them"],["خَلَـٰٓئِفَ","successors"],["وَأَغْرَقْنَا","and We drowned"],["ٱلَّذِينَ","those who"],["كَذَّبُوا۟","denied"],["بِـَٔايَـٰتِنَا ۖ","Our Signs"],["فَٱنظُرْ","Then see"],["كَيْفَ","how"],["كَانَ","was"],["عَـٰقِبَةُ","(the) end"],["ٱلْمُنذَرِينَ","(of) those who were warned"]]],"1438":["(Kemudian sesudahnya Kami utus) yakni sesudah Nabi Nuh (beberapa rasul kepada kaum mereka) seperti Nabi Ibrahim, Nabi Hud dan Nabi Saleh (maka rasul-rasul itu datang kepada mereka dengan membawa keterangan-keterangan yang nyata), yakni mukjizat-mukjizat (tetapi mereka tidak hendak beriman karena mereka dahulu telah biasa mendustakannya) sebelum rasul-rasul diutus kepada mereka. (Demikianlah Kami mengunci mati) menutup rapat-rapat (hati orang-orang yang melampaui batas) sehingga hati mereka tidak mau menerima iman, seperti Kami mengunci mati hati mereka yang melampaui batas.",[["ثُمَّ","Then"],["بَعَثْنَا","We sent"],["مِنۢ","after him"],["بَعْدِهِۦ","after him"],["رُسُلًا","Messengers"],["إِلَىٰ","to"],["قَوْمِهِمْ","their people"],["فَجَآءُوهُم","and they came to them"],["بِٱلْبَيِّنَـٰتِ","with clear proofs"],["فَمَا","But not"],["كَانُوا۟","they were"],["لِيُؤْمِنُوا۟","to believe"],["بِمَا","what"],["كَذَّبُوا۟","they had denied"],["بِهِۦ","[it]"],["مِن","before"],["قَبْلُ ۚ","before"],["كَذَٰلِكَ","Thus"],["نَطْبَعُ","We seal"],["عَلَىٰ","[on]"],["قُلُوبِ","the hearts"],["ٱلْمُعْتَدِينَ","(of) the transgressors"]]],"1439":["(Kemudian sesudah rasul-rasul itu, Kami utus Musa dan Harun kepada Firaun dan pemuka-pemuka kaumnya) kaumnya Firaun (dengan membawa ayat-ayat Kami) yang berjumlah sembilan buah ayat (maka mereka menyombongkan diri) tidak mau beriman kepadanya (dan mereka adalah orang-orang yang berdosa).",[["ثُمَّ","Then"],["بَعَثْنَا","We sent"],["مِنۢ","after them"],["بَعْدِهِم","after them"],["مُّوسَىٰ","Musa"],["وَهَـٰرُونَ","and Harun"],["إِلَىٰ","to"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦ","and his chiefs"],["بِـَٔايَـٰتِنَا","with Our Signs"],["فَٱسْتَكْبَرُوا۟","but they were arrogant"],["وَكَانُوا۟","and were"],["قَوْمًۭا","a people"],["مُّجْرِمِينَ","criminal"]]],"1440":["(Dan tatkala telah datang kepada mereka kebenaran dari sisi Kami, mereka berkata, \"Sesungguhnya ini adalah sihir yang nyata.\") jelas dan gamblang.",[["فَلَمَّا","So when"],["جَآءَهُمُ","came to them"],["ٱلْحَقُّ","the truth"],["مِنْ","from Us"],["عِندِنَا","from Us"],["قَالُوٓا۟","they said"],["إِنَّ","Indeed"],["هَـٰذَا","this"],["لَسِحْرٌۭ","(is) surely, a magic"],["مُّبِينٌۭ","clear"]]],"1441":["(Musa berkata, \"Apakah kalian mengatakan terhadap kebenaran waktu ia datang kepada kalian) sesungguhnya adalah sihir (sihirkah ini?) padahal sungguh telah mendapat kemenangan orang yang mendatangkannya dan kalahlah sihir yang dilakukan oleh para ahli tenung (dan sungguh ahli sihir itu tidaklah mendapat kemenangan.\") kedua kata tanya yang terdapat di dalam ayat ini mengandung makna ingkar.",[["قَالَ","Musa said"],["مُوسَىٰٓ","Musa said"],["أَتَقُولُونَ","Do you say"],["لِلْحَقِّ","about the truth"],["لَمَّا","when"],["جَآءَكُمْ ۖ","it has come to you"],["أَسِحْرٌ","Is this magic"],["هَـٰذَا","Is this magic"],["وَلَا","But (will) not"],["يُفْلِحُ","succeed"],["ٱلسَّـٰحِرُونَ","the magicians"]]],"1442":["(Mereka berkata, \"Apakah kamu datang kepada kami untuk memalingkan kami) untuk membuat kami murtad (dari apa yang kami dapati nenek moyang kami mengerjakannya dan supaya kamu berdua mempunyai kekuasaan) kerajaan (di muka bumi?) yang dimaksud adalah negeri Mesir (Kami tidak akan mempercayai kamu berdua.\") tidak mau beriman.",[["قَالُوٓا۟","They said"],["أَجِئْتَنَا","Have you come to us"],["لِتَلْفِتَنَا","to turn us away"],["عَمَّا","from that"],["وَجَدْنَا","we found"],["عَلَيْهِ","on it"],["ءَابَآءَنَا","our forefathers"],["وَتَكُونَ","and you two (may) have"],["لَكُمَا","and you two (may) have"],["ٱلْكِبْرِيَآءُ","the greatness"],["فِى","in"],["ٱلْأَرْضِ","the land"],["وَمَا","And we (are) not"],["نَحْنُ","And we (are) not"],["لَكُمَا","(in) you two"],["بِمُؤْمِنِينَ","believers"]]],"1443":["(Firaun berkata, \"Datangkanlah kepadaku semua ahli-ahli sihir yang pandai.\") yang mahir di dalam ilmu sihir.",[["وَقَالَ","And Firaun said"],["فِرْعَوْنُ","And Firaun said"],["ٱئْتُونِى","Bring to me"],["بِكُلِّ","every"],["سَـٰحِرٍ","magician"],["عَلِيمٍۢ","learned"]]],"1444":["(Maka tatkala ahli-ahli sihir itu datang, Musa berkata kepada mereka,) sesudah mereka mengatakan kepadanya, \"Kamukah yang akan melemparkan terlebih dahulu ataukah kami yang akan melemparkan?\" (Al-A`raf 115) (\"Lemparkanlah apa yang hendak kalian lemparkan.\")",[["فَلَمَّا","So when"],["جَآءَ","came"],["ٱلسَّحَرَةُ","the magicians"],["قَالَ","said"],["لَهُم","to them"],["مُّوسَىٰٓ","Musa"],["أَلْقُوا۟","Throw"],["مَآ","whatever"],["أَنتُم","you"],["مُّلْقُونَ","(wish to) throw"]]],"1445":["(Maka setelah mereka lemparkan) tali-tali dan tongkat-tongkat mereka (Musa berkata, \"Apa) huruf maa di sini bermakna istifham sekaligus menjadi mubtada sedangkan khabarnya ialah berikutnya (yang kalian datangkan itu itulah sihir) lafal as-sihr menjadi badal. Sedangkan menurut qiraat yang lain dengan memakai hamzah, berarti keduanya menjadi khabar, dan maa bukannya istifhamiyah melainkan maushul dan sekaligus menjadi mubtada. (Sesungguhnya Allah akan menampakkan ketidakbenarannya.\") Allah akan melenyapkannya (Sesungguhnya Allah tidak akan membiarkan terus berlangsungnya pekerjaan orang-orang yang membuat kerusakan).",[["فَلَمَّآ","Then when"],["أَلْقَوْا۟","they (had) thrown"],["قَالَ","Musa said"],["مُوسَىٰ","Musa said"],["مَا","What"],["جِئْتُم","you have brought"],["بِهِ","[it]"],["ٱلسِّحْرُ ۖ","(is) the magic"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["سَيُبْطِلُهُۥٓ ۖ","will nullify it"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يُصْلِحُ","amend"],["عَمَلَ","the work"],["ٱلْمُفْسِدِينَ","(of) the corrupters"]]],"1446":["(Dan Allah akan mengukuhkan) meneguhkan dan memenangkan (yang benar dengan kalimat-kalimat-Nya) yakni janji-janji-Nya (walaupun orang-orang yang berbuat dosa tidak menyukainya.)",[["وَيُحِقُّ","And Allah will establish"],["ٱللَّهُ","And Allah will establish"],["ٱلْحَقَّ","the truth"],["بِكَلِمَـٰتِهِۦ","by His words"],["وَلَوْ","even if"],["كَرِهَ","dislike it"],["ٱلْمُجْرِمُونَ","the criminals"]]],"1447":["(Maka tidak ada yang beriman kepada Musa melainkan pemuda-pemuda) segolongan orang (dari) anak-anak (kaumnya) kaumnya Firaun (dalam keadaan takut bahwa Firaun dan pemuka-pemuka kaumnya akan menyiksa mereka.) dalam upayanya untuk memalingkan mereka dari agama Nabi Musa melalui siksaan (Sesungguhnya Firaun itu berbuat sewenang-wenang) berlaku sombong (di muka bumi.) negeri Mesir (Dan sesungguhnya dia termasuk orang-orang yang melampaui batas) dia sudah sangat keterlaluan karena mengaku menjadi tuhan.",[["فَمَآ","But none"],["ءَامَنَ","believed"],["لِمُوسَىٰٓ","Musa"],["إِلَّا","except"],["ذُرِّيَّةٌۭ","(the) offspring"],["مِّن","among"],["قَوْمِهِۦ","his people"],["عَلَىٰ","for"],["خَوْفٍۢ","fear"],["مِّن","of"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِمْ","and their chiefs"],["أَن","lest"],["يَفْتِنَهُمْ ۚ","they persecute them"],["وَإِنَّ","And indeed"],["فِرْعَوْنَ","Firaun"],["لَعَالٍۢ","(was) a tyrant"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَإِنَّهُۥ","and indeed, he"],["لَمِنَ","(was) of"],["ٱلْمُسْرِفِينَ","the ones who commit excesses"]]],"1448":["(Berkata Musa, \"Hai kaumku! Jika kalian beriman kepada Allah, maka bertawakallah kepada-Nya saja jika kalian benar-benar orang-orang yang berserah diri.\")",[["وَقَالَ","And Musa said"],["مُوسَىٰ","And Musa said"],["يَـٰقَوْمِ","O my people"],["إِن","If"],["كُنتُمْ","you have"],["ءَامَنتُم","believed"],["بِٱللَّهِ","in Allah"],["فَعَلَيْهِ","then on Him"],["تَوَكَّلُوٓا۟","put your trust"],["إِن","if"],["كُنتُم","you are"],["مُّسْلِمِينَ","Muslims"]]],"1449":["(Lalu mereka berkata, \"Kepada Allahlah kami bertawakal. Ya Rabb kami! Janganlah Engkau jadikan kami sasaran fitnah bagi kaum yang zalim) artinya janganlah Engkau membuat mereka menang atas diri kami sehingga mereka menduga bahwa mereka berada dalam jalan yang benar lalu mereka berani menyiksa kami.",[["فَقَالُوا۟","Then they said"],["عَلَى","Upon"],["ٱللَّهِ","Allah"],["تَوَكَّلْنَا","we put our trust"],["رَبَّنَا","Our Lord"],["لَا","(Do) not"],["تَجْعَلْنَا","make us"],["فِتْنَةًۭ","a trial"],["لِّلْقَوْمِ","for the people "],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"1450":["(Dan selamatkanlah kami dengan rahmat Engkau dari tipu daya orang-orang kafir.\")",[["وَنَجِّنَا","And save us"],["بِرَحْمَتِكَ","by Your Mercy"],["مِنَ","from"],["ٱلْقَوْمِ","the people "],["ٱلْكَـٰفِرِينَ","the disbelievers"]]],"1451":["(Dan Kami wahyukan kepada Musa dan saudaranya, \"Ambillah oleh kamu berdua) tempatilah oleh kamu berdua (beberapa buah rumah di Mesir untuk tempat tinggal bagi kaummu dan jadikanlah olehmu rumah-rumah itu tempat untuk salat) sebagai mushalla tempat kalian melakukan salat di dalamnya supaya kalian merasa aman dari ketakutan, dan tersebutlah bahwa Firaun melarang mereka melakukan salat (dan dirikanlah oleh kalian salat) sempurnakanlah salat itu oleh kalian (serta gembirakanlah orang-orang yang beriman.\") bahwa mereka akan mendapatkan pertolongan dan surga.",[["وَأَوْحَيْنَآ","And We inspired"],["إِلَىٰ","to"],["مُوسَىٰ","Musa"],["وَأَخِيهِ","and his brother"],["أَن","that"],["تَبَوَّءَا","Settle"],["لِقَوْمِكُمَا","your people"],["بِمِصْرَ","in Egypt"],["بُيُوتًۭا","(in) houses"],["وَٱجْعَلُوا۟","and make"],["بُيُوتَكُمْ","your houses"],["قِبْلَةًۭ","(as) places of worship"],["وَأَقِيمُوا۟","and establish"],["ٱلصَّلَوٰةَ ۗ","the prayer"],["وَبَشِّرِ","And give glad tidings"],["ٱلْمُؤْمِنِينَ","(to) the believers"]]],"1452":["(Musa berkata, \"Ya Rabb kami! Sesungguhnya Engkau telah memberi kepada Firaun dan pemuka-pemuka kaumnya perhiasan dan harta kekayaan dalam kehidupan dunia. Ya Rabb kami) Engkau telah memberikan mereka hal-hal tersebut (yang akhirnya mereka menyesatkan) pada kesudahannya mereka menyesatkan manusia (dari jalan Engkau) agama Engkau. (Ya Rabb kami, binasakanlah harta benda mereka) lenyapkanlah harta benda mereka (dan kunci matilah hati mereka) artinya tutuplah rapat-rapat hati mereka (maka mereka tidak beriman hingga mereka melihat siksaan yang pedih) yang menyakitkan. Nabi Musa berdoa mengutuk Firaun dan pemuka-pemuka kaumnya, sedangkan Nabi Harun mengamini doanya.",[["وَقَالَ","And Musa said"],["مُوسَىٰ","And Musa said"],["رَبَّنَآ","Our Lord"],["إِنَّكَ","Indeed, You"],["ءَاتَيْتَ","have given"],["فِرْعَوْنَ","Firaun"],["وَمَلَأَهُۥ","and his chiefs"],["زِينَةًۭ","splendor"],["وَأَمْوَٰلًۭا","and wealth"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا","(of) the world"],["رَبَّنَا","Our Lord"],["لِيُضِلُّوا۟","That they may lead astray"],["عَن","from"],["سَبِيلِكَ ۖ","Your way"],["رَبَّنَا","Our Lord"],["ٱطْمِسْ","Destroy"],["عَلَىٰٓ","[on]"],["أَمْوَٰلِهِمْ","their wealth"],["وَٱشْدُدْ","and harden"],["عَلَىٰ","[on]"],["قُلُوبِهِمْ","their hearts"],["فَلَا","so (that) not"],["يُؤْمِنُوا۟","they believe"],["حَتَّىٰ","until"],["يَرَوُا۟","they see"],["ٱلْعَذَابَ","the punishment "],["ٱلْأَلِيمَ","the painful"]]],"1453":["(Allah berfirman,) Maha Tinggi Allah (\"Sesungguhnya telah diperkenankan permohonan kamu berdua) akhirnya harta benda milik Firaun diserapah menjadi batu, dan Firaun masih tetap belum mau beriman hingga ia mati tenggelam (sebab itu tetaplah kamu berdua pada jalan yang lurus) menunaikan risalah dan dakwah sampai datang azab atas mereka (dan janganlah sekali-kali kamu mengikuti jalan orang-orang yang tidak mengetahui\") bahwa keputusan-Ku akan disegerakan. Diriwayatkan bahwa setelah peristiwa itu Nabi Musa tinggal di negeri Mesir selama empat puluh tahun.",[["قَالَ","He said"],["قَدْ","Verily"],["أُجِيبَت","has been answered"],["دَّعْوَتُكُمَا","(the) invocation of both of you"],["فَٱسْتَقِيمَا","So you two (keep to the) straight way"],["وَلَا","And (do) not"],["تَتَّبِعَآنِّ","follow"],["سَبِيلَ","(the) way"],["ٱلَّذِينَ","(of) those who"],["لَا","(do) not"],["يَعْلَمُونَ","know"]]],"1454":["(Dan Kami memungkinkan Bani Israel melintasi laut lalu mereka diikuti) disusul dan dikejar (oleh Firaun dan bala tentaranya, karena hendak menganiaya dan menindas) mereka, lafal baghyan dan `adwan menjadi maf'ul lah (hingga bila Firaun itu telah hampir tenggelam berkata dia, \"Saya percaya bahwa) bahwasanya; dan menurut suatu qiraat lafal annahu dibaca innahu sebagai jumlah isti'naf (tidak ada Tuhan melainkan Tuhan yang dipercayai oleh Bani Israil, dan saya termasuk orang-orang yang berserah diri.\") Firaun sengaja mengulang-ulang perkataannya itu supaya diterima oleh Allah, akan tetapi Allah tidak mau menerimanya. Kemudian malaikat Jibril menyumbat mulutnya dengan lumpur laut, karena merasa khawatir Firaun akan mendapatkan rahmat dari Allah. Lalu Allah berfirman kepadanya:",[["۞ وَجَـٰوَزْنَا","And We took across"],["بِبَنِىٓ","(the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel "],["ٱلْبَحْرَ","the sea"],["فَأَتْبَعَهُمْ","and followed them"],["فِرْعَوْنُ","Firaun"],["وَجُنُودُهُۥ","and his hosts"],["بَغْيًۭا","(in) rebellion"],["وَعَدْوًا ۖ","and enmity"],["حَتَّىٰٓ","until"],["إِذَآ","when"],["أَدْرَكَهُ","overtook him"],["ٱلْغَرَقُ","the drowning"],["قَالَ","he said"],["ءَامَنتُ","I believe"],["أَنَّهُۥ","that"],["لَآ","(there is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["ٱلَّذِىٓ","the One"],["ءَامَنَتْ","in Whom believe"],["بِهِۦ","in Whom believe"],["بَنُوٓا۟","the Children of Israel"],["إِسْرَٰٓءِيلَ","the Children of Israel"],["وَأَنَا۠","and I am"],["مِنَ","of"],["ٱلْمُسْلِمِينَ","the Muslims"]]],"1455":["(Apakah sekarang) baru kamu percaya (padahal sesungguhnya kamu telah durhaka sejak dahulu, dan kamu termasuk orang-orang yang berbuat kerusakan) karena kesesatanmu dan penyesatan yang kamu lakukan dari jalan keimanan.",[["ءَآلْـَٔـٰنَ","Now"],["وَقَدْ","And verily"],["عَصَيْتَ","you (had) disobeyed"],["قَبْلُ","before"],["وَكُنتَ","and you were"],["مِنَ","of"],["ٱلْمُفْسِدِينَ","the corrupters"]]],"1456":["(Maka pada hari ini Kami selamatkan) Kami keluarkan dari laut (badanmu) jasadmu yang sudah tidak bernyawa (supaya kamu dijadikan oleh orang-orang yang datang sesudahmu) generasi sesudahmu (sebagai pelajaran) bahan pelajaran, sehingga mereka mengetahui sifat kehambaanmu. Dengan demikian mereka tidak akan berani lagi melakukan perbuatan seperti yang pernah dilakukan olehmu. Ibnu Abbas r.a. menceritakan, bahwa sebagian orang-orang Bani Israel merasa ragu-ragu akan kematian Firaun, maka dikeluarkan-Nyalah mayat Firaun dari laut supaya mereka melihat dan menyaksikannya dengan mata kepala sendiri (dan sesungguhnya kebanyakan dari manusia) penduduk Mekah (lengah dari tanda-tanda kekuasaan-Ku) artinya mereka tidak mau mengambil pelajaran daripadanya.",[["فَٱلْيَوْمَ","So today"],["نُنَجِّيكَ","We will save you"],["بِبَدَنِكَ","in your body"],["لِتَكُونَ","that you may be"],["لِمَنْ","for (those) who"],["خَلْفَكَ","succeed you"],["ءَايَةًۭ ۚ","a sign"],["وَإِنَّ","And indeed"],["كَثِيرًۭا","many"],["مِّنَ","among"],["ٱلنَّاسِ","the mankind"],["عَنْ","of"],["ءَايَـٰتِنَا","Our Signs"],["لَغَـٰفِلُونَ","(are) surely heedless"]]],"1457":["(Dan sesungguhnya Kami telah menempatkan) memberikan tempat (Bani Israel di tempat kediaman yang bagus) tempat yang terhormat, yaitu negeri Syam dan negeri Mesir (dan Kami beri mereka rezeki dari yang baik-baik. Maka mereka tidak berselisih) sekalipun sebagian di antara mereka beriman dan sebagian yang lain kafir (kecuali setelah datang kepada mereka pengetahuan, yang tersebut dalam Taurat. Sesungguhnya Rabb kamu akan memutuskan antara mereka di hari kiamat tentang apa yang mereka perselisihkan itu) dalam masalah agama, yaitu dengan menyelamatkan orang-orang beriman dan mengazab orang-orang kafir.",[["وَلَقَدْ","And verily"],["بَوَّأْنَا","We settled"],["بَنِىٓ","(the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"],["مُبَوَّأَ","(in) a settlement"],["صِدْقٍۢ","honorable"],["وَرَزَقْنَـٰهُم","and We provided them"],["مِّنَ","with"],["ٱلطَّيِّبَـٰتِ","the good things"],["فَمَا","and not"],["ٱخْتَلَفُوا۟","they differ"],["حَتَّىٰ","until"],["جَآءَهُمُ","came to them"],["ٱلْعِلْمُ ۚ","the knowledge"],["إِنَّ","Indeed"],["رَبَّكَ","your Lord"],["يَقْضِى","will judge"],["بَيْنَهُمْ","between them"],["يَوْمَ","(on) the Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["فِيمَا","concerning what"],["كَانُوا۟","they used (to)"],["فِيهِ","[in it]"],["يَخْتَلِفُونَ","differ"]]],"1458":["(Maka jika kamu) hai Muhammad (berada dalam keragu-raguan tentang apa yang Kami turunkan kepadamu) yaitu berupa kisah-kisah, seumpamanya (maka tanyakanlah kepada orang-orang yang telah membaca kitab) Taurat (sebelum kamu) maka sesungguhnya hal itu telah tertera di dalam kitab mereka, mereka akan memberitakannya kepadamu sesuai dengannya; untuk itu maka Rasulullah saw. bersabda, \"Aku tidak ragu dan tidak menanyakannya.\" (Sesungguhnya telah datang kebenaran kepadamu dari Rabbmu, sebab itu janganlah sekali-kali kamu termasuk orang-orang yang ragu) menaruh keraguan padanya.",[["فَإِن","So if"],["كُنتَ","you are"],["فِى","in"],["شَكٍّۢ","doubt"],["مِّمَّآ","of what"],["أَنزَلْنَآ","We have revealed"],["إِلَيْكَ","to you"],["فَسْـَٔلِ","then ask"],["ٱلَّذِينَ","those who"],["يَقْرَءُونَ","(have been) reading"],["ٱلْكِتَـٰبَ","the Book"],["مِن","before you"],["قَبْلِكَ ۚ","before you"],["لَقَدْ","Verily"],["جَآءَكَ","has come to you"],["ٱلْحَقُّ","the truth"],["مِن","from"],["رَّبِّكَ","your Lord"],["فَلَا","so (do) not"],["تَكُونَنَّ","be"],["مِنَ","among"],["ٱلْمُمْتَرِينَ","the doubters"]]],"1459":["(Dan sekali-kali janganlah kamu termasuk orang-orang yang mendustakan ayat-ayat Allah yang menyebabkan kamu termasuk orang-orang yang rugi).",[["وَلَا","And (do) not"],["تَكُونَنَّ","be"],["مِنَ","of"],["ٱلَّذِينَ","those who"],["كَذَّبُوا۟","deny"],["بِـَٔايَـٰتِ","(the) Signs of Allah"],["ٱللَّهِ","(the) Signs of Allah"],["فَتَكُونَ","then you will be"],["مِنَ","among"],["ٱلْخَـٰسِرِينَ","the losers"]]],"1460":["(Sesungguhnya orang-orang yang telah pasti) telah dipastikan (terhadap mereka kalimat Rabbmu) yaitu azab Allah telah pasti atas mereka (tidaklah akan beriman).",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those [whom]"],["حَقَّتْ","has become due"],["عَلَيْهِمْ","on them"],["كَلِمَتُ","(the) Word"],["رَبِّكَ","(of) your Lord"],["لَا","will not"],["يُؤْمِنُونَ","believe"]]],"1461":["(Meskipun datang kepada mereka segala macam keterangan hingga mereka menyaksikan azab yang pedih) maka pada saat itu tidak bermanfaat lagi keimanan mereka.",[["وَلَوْ","Even if"],["جَآءَتْهُمْ","comes to them"],["كُلُّ","every"],["ءَايَةٍ","Sign"],["حَتَّىٰ","until"],["يَرَوُا۟","they see"],["ٱلْعَذَابَ","the punishment "],["ٱلْأَلِيمَ","the painful"]]],"1462":["(Dan mengapa tidak) hendaknyalah (ada suatu kota) yakni penduduknya (yang beriman) sebelum azab turun atas mereka (lalu imannya itu bermanfaat kepadanya selain kaum Yunus. Tatkala mereka beriman) yaitu sewaktu mereka melihat adanya tanda-tanda azab lalu mereka segera beriman sebelum azab diturunkan atas diri mereka (Kami hilangkan dari mereka azab yang menghinakan dalam kehidupan dunia dan Kami beri kesenangan kepada mereka sampai pada waktu yang tertentu) sampai ajal mereka tiba.",[["فَلَوْلَا","So why not"],["كَانَتْ","was"],["قَرْيَةٌ","any town"],["ءَامَنَتْ","that believed"],["فَنَفَعَهَآ","and benefited it"],["إِيمَـٰنُهَآ","its faith"],["إِلَّا","except"],["قَوْمَ","the people"],["يُونُسَ","(of) Yunus"],["لَمَّآ","When"],["ءَامَنُوا۟","they believed"],["كَشَفْنَا","We removed"],["عَنْهُمْ","from them"],["عَذَابَ","(the) punishment"],["ٱلْخِزْىِ","(of) the disgrace"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا","of the world"],["وَمَتَّعْنَـٰهُمْ","and We granted them enjoyment"],["إِلَىٰ","for"],["حِينٍۢ","a time"]]],"1463":["(Dan jika Rabbmu menghendaki tentulah beriman semua orang yang di muka bumi seluruhnya. Maka apakah kamu hendak memaksa manusia) terhadap apa yang Allah tidak kehendaki mereka untuk melakukannya (supaya mereka menjadi orang-orang yang beriman semuanya?) tentu saja tidak.",[["وَلَوْ","And if"],["شَآءَ","(had) willed"],["رَبُّكَ","your Lord"],["لَـَٔامَنَ","surely, (would) have believed"],["مَن","who"],["فِى","(are) in"],["ٱلْأَرْضِ","the earth"],["كُلُّهُمْ","all of them"],["جَمِيعًا ۚ","together"],["أَفَأَنتَ","Then, will you"],["تُكْرِهُ","compel"],["ٱلنَّاسَ","the mankind"],["حَتَّىٰ","until"],["يَكُونُوا۟","they become"],["مُؤْمِنِينَ","believers"]]],"1464":["(Dan tidak ada seorang pun akan beriman kecuali dengan izin Allah) dengan kehendak-Nya (dan Allah menimpakan kemurkaan) azab-Nya (kepada orang-orang yang tidak mempergunakan akalnya) yaitu orang-orang yang tidak mau memikirkan ayat-ayat Allah.",[["وَمَا","And not"],["كَانَ","is"],["لِنَفْسٍ","for a soul"],["أَن","to"],["تُؤْمِنَ","believe"],["إِلَّا","except"],["بِإِذْنِ","by (the) permission"],["ٱللَّهِ ۚ","(of) Allah"],["وَيَجْعَلُ","And He will place"],["ٱلرِّجْسَ","the wrath"],["عَلَى","on"],["ٱلَّذِينَ","those who"],["لَا","(do) not"],["يَعْقِلُونَ","use reason"]]],"1465":["(Katakanlah,) kepada orang-orang kafir Mekah (\"Perhatikanlah apa) apa-apa (yang ada di langit dan di bumi) yaitu tanda-tanda yang menunjukkan akan keesaan Allah swt. (Tidaklah bermanfaat tanda kekuasaan Allah dan rasul-rasul yang memberi peringatan) lafal an-nudzur adalah bentuk jamak dari kata tunggal nadzir yang artinya para rasul (bagi orang-orang yang tidak beriman.\") yang hal ini diketahui oleh Allah swt. atau dengan kata lain, hal-hal tersebut tidak ada manfaatnya bagi mereka.",[["قُلِ","Say"],["ٱنظُرُوا۟","See"],["مَاذَا","what"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["وَمَا","But not"],["تُغْنِى","will avail"],["ٱلْـَٔايَـٰتُ","the Signs"],["وَٱلنُّذُرُ","and the warners"],["عَن","to"],["قَوْمٍۢ","a people"],["لَّا","(who do) not"],["يُؤْمِنُونَ","believe"]]],"1466":["(Tiada) tidak ada (yang mereka tunggu-tunggu) dengan perbuatan mereka yang mendustakan kamu (melainkan kejadian-kejadian yang sama dengan kejadian-kejadian yang menimpa orang-orang terdahulu sebelum mereka) umat-umat terdahulu. Artinya, mereka akan tertimpa siksaan yang sama seperti siksaan yang menimpa umat-umat terdahulu (Katakanlah, \"Maka tunggulah) hal tersebut (sesungguhnya aku pun orang yang menunggu bersama kalian.\")",[["فَهَلْ","Then do"],["يَنتَظِرُونَ","they wait"],["إِلَّا","except"],["مِثْلَ","like"],["أَيَّامِ","the days"],["ٱلَّذِينَ","(of) those who"],["خَلَوْا۟","passed away"],["مِن","before them"],["قَبْلِهِمْ ۚ","before them"],["قُلْ","Say"],["فَٱنتَظِرُوٓا۟","Then wait"],["إِنِّى","indeed, I (am)"],["مَعَكُم","with you"],["مِّنَ","among"],["ٱلْمُنتَظِرِينَ","the ones who wait"]]],"1467":["(Kemudian Kami selamatkan) bentuk mudhari' di sini dimaksud untuk menceritakan keadaan di masa lampau (rasul-rasul Kami dan orang-orang yang beriman) dari azab (demikianlah) penyelamatan itu (menjadi kewajiban atas Kami menyelamatkan orang-orang yang beriman) Nabi dan para sahabatnya ketika orang-orang musyrik disiksa.",[["ثُمَّ","Then"],["نُنَجِّى","We will save"],["رُسُلَنَا","Our Messengers"],["وَٱلَّذِينَ","and those who"],["ءَامَنُوا۟ ۚ","believe"],["كَذَٰلِكَ","Thus"],["حَقًّا","(it is) an obligation"],["عَلَيْنَا","upon Us"],["نُنجِ","(that) We save"],["ٱلْمُؤْمِنِينَ","the believers"]]],"1468":["(Katakanlah, \"Hai manusia) hai penduduk Mekah! (Jika kalian masih dalam keragu-raguan tentang agamaku) bahwasanya agamaku itu adalah hak dan benar (maka ketahuilah aku tidak menyembah yang kalian sembah selain Allah) selain-Nya, yang dimaksud adalah berhala-berhala; hal ini merupakan pertanda bahwa kalian ragu-ragu terhadap agamaku (tetapi aku menyembah Allah yang akan mematikan kalian) yang akan mencabut ruh kalian (dan aku telah diperintah supaya) hendaknya (aku termasuk orang-orang yang beriman.\")",[["قُلْ","Say"],["يَـٰٓأَيُّهَا","O mankind"],["ٱلنَّاسُ","O mankind"],["إِن","If"],["كُنتُمْ","you are"],["فِى","in"],["شَكٍّۢ","doubt"],["مِّن","of"],["دِينِى","my religion"],["فَلَآ","then not"],["أَعْبُدُ","I worship"],["ٱلَّذِينَ","those whom"],["تَعْبُدُونَ","you worship"],["مِن","besides Allah"],["دُونِ","besides Allah"],["ٱللَّهِ","besides Allah"],["وَلَـٰكِنْ","but"],["أَعْبُدُ","I worship"],["ٱللَّهَ","Allah"],["ٱلَّذِى","the One Who"],["يَتَوَفَّىٰكُمْ ۖ","causes you to die"],["وَأُمِرْتُ","And I am commanded"],["أَنْ","that"],["أَكُونَ","I be"],["مِنَ","of"],["ٱلْمُؤْمِنِينَ","the believers"]]],"1469":["(Dan) aku diperintahkan (\"Hadapkanlah mukamu kepada agama dengan tulus dan ikhlas) dalam keadaan cenderung dan menggandrunginya (dan janganlah kamu termasuk orang-orang yang musyrik).",[["وَأَنْ","And that"],["أَقِمْ","Direct"],["وَجْهَكَ","your face"],["لِلدِّينِ","to the religion"],["حَنِيفًۭا","upright"],["وَلَا","and (do) not"],["تَكُونَنَّ","be"],["مِنَ","of"],["ٱلْمُشْرِكِينَ","the polytheists"]]],"1470":["(Dan janganlah kamu menyeru) menyembah (kepada selain Allah, yaitu apa-apa yang tidak dapat memberikan manfaat kepadamu) jika kamu menyembahnya (dan pula tidak dapat memberikan mudarat kepadamu) jika kamu tidak menyembahnya (sebab jika kamu berbuat) hal itu, umpamanya (maka sesungguhnya kamu kalau begitu termasuk orang-orang yang lalim.\")",[["وَلَا","And (do) not"],["تَدْعُ","invoke"],["مِن","besides Allah"],["دُونِ","besides Allah"],["ٱللَّهِ","besides Allah"],["مَا","what"],["لَا","(will) not"],["يَنفَعُكَ","benefit you"],["وَلَا","and not"],["يَضُرُّكَ ۖ","harm you"],["فَإِن","But if"],["فَعَلْتَ","you did so"],["فَإِنَّكَ","indeed, you"],["إِذًۭا","then (will be)"],["مِّنَ","of"],["ٱلظَّـٰلِمِينَ","the wrongdoers"]]],"1471":["(Jika Allah menimpakan kepadamu) mengenakan kepadamu (sesuatu kemudaratan) seperti kemiskinan dan sakit (maka tidak ada yang dapat menghilangkan) yang melenyapkan (hal itu kecuali Dia. Dan jika Allah menghendaki kebaikan bagi kamu, maka tak ada yang dapat menolak) menahan (karunia-Nya) yang telah Dia kehendaki buatmu (Dia memberikan hal itu) kebaikan itu (kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya dan Dialah Yang Maha Pengampun lagi Maha Penyayang.)",[["وَإِن","And if"],["يَمْسَسْكَ","Allah touches you"],["ٱللَّهُ","Allah touches you"],["بِضُرٍّۢ","with adversity"],["فَلَا","(there is) no"],["كَاشِفَ","remover"],["لَهُۥٓ","of it"],["إِلَّا","except"],["هُوَ ۖ","Him"],["وَإِن","and if"],["يُرِدْكَ","He intends for you"],["بِخَيْرٍۢ","any good"],["فَلَا","then (there is) no"],["رَآدَّ","repeller"],["لِفَضْلِهِۦ ۚ","(of) His Bounty"],["يُصِيبُ","He causes it to reach"],["بِهِۦ","He causes it to reach"],["مَن","whom"],["يَشَآءُ","He wills"],["مِنْ","of"],["عِبَادِهِۦ ۚ","His slaves"],["وَهُوَ","And He"],["ٱلْغَفُورُ","(is) the Oft-Forgiving"],["ٱلرَّحِيمُ","the Most Merciful"]]],"1472":["(Katakanlah, \"Hai manusia) yakni penduduk Mekah! (Sesungguhnya telah datang kepada kalian kebenaran dari Rabb kalian, sebab itu barang siapa yang mendapat petunjuk maka sesungguhnya petunjuk itu untuk kebaikan dirinya.) karena sesungguhnya pahala hidayahnya itu hanya dialah yang berhak menerimanya (Dan barang siapa yang sesat maka sesungguhnya kesesatannya itu untuk kecelakaan dirinya sendiri) karena akibat kesesatannya itu akan menimpa dirinya sendiri (Dan aku bukanlah seorang penjaga terhadap diri kalian.\") karenanya bagaimana aku akan memaksakan kepada kalian untuk mengikuti petunjuk.",[["قُلْ","Say"],["يَـٰٓأَيُّهَا","O mankind"],["ٱلنَّاسُ","O mankind"],["قَدْ","Verily"],["جَآءَكُمُ","has come to you"],["ٱلْحَقُّ","the truth"],["مِن","from"],["رَّبِّكُمْ ۖ","your Lord"],["فَمَنِ","So whoever"],["ٱهْتَدَىٰ","(is) guided"],["فَإِنَّمَا","then only"],["يَهْتَدِى","(he is) guided"],["لِنَفْسِهِۦ ۖ","for his soul"],["وَمَن","and whoever"],["ضَلَّ","goes astray"],["فَإِنَّمَا","then only"],["يَضِلُّ","he strays"],["عَلَيْهَا ۖ","against it"],["وَمَآ","And I am not"],["أَنَا۠","And I am not"],["عَلَيْكُم","over you"],["بِوَكِيلٍۢ","a guardian"]]],"1473":["(Dan ikutilah apa yang diwahyukan kepadamu) dari Rabbmu (dan bersabarlah) di dalam berdakwah dan menghadapi permusuhan mereka (hingga Allah memberi keputusan) terhadap mereka dengan perintah-Nya (dan Dia adalah hakim yang sebaik-baiknya) hakim yang paling adil. Ternyata Nabi saw. bersabar di dalam menghadapi kesemuanya itu, hingga Allah memberikan keputusan terhadap orang-orang musyrik, yaitu dengan memerintahkan supaya mereka diperangi dan bagi ahli Kitab supaya ditarik jizyah/upeti.",[["وَٱتَّبِعْ","And follow"],["مَا","what"],["يُوحَىٰٓ","is revealed"],["إِلَيْكَ","to you"],["وَٱصْبِرْ","and be patient"],["حَتَّىٰ","until"],["يَحْكُمَ","Allah gives judgment"],["ٱللَّهُ ۚ","Allah gives judgment"],["وَهُوَ","And He"],["خَيْرُ","(is) the Best"],["ٱلْحَـٰكِمِينَ","(of) the Judges"]]],"1474":["(Alif laam raa) hanya Allahlah yang mengetahui maksudnya; inilah (suatu Kitab yang ayat-ayatnya disusun dengan rapi) hal ini tampak pada susunan ayat-ayatnya yang memukau dan keindahan makna-maknanya (serta dijelaskan secara rinci) yang kandungannya menjelaskan tentang hukum-hukum, kisah-kisah dan nasihat-nasihat (yang diturunkan dari sisi Yang Maha Bijaksana lagi Maha Waspada) yaitu Allah.",[["الٓر ۚ","Alif Lam Ra"],["كِتَـٰبٌ","(This is) a Book"],["أُحْكِمَتْ","are perfected"],["ءَايَـٰتُهُۥ","its Verses"],["ثُمَّ","moreover"],["فُصِّلَتْ","explained in detail"],["مِن","from (he One Who)"],["لَّدُنْ","from (he One Who)"],["حَكِيمٍ","(is) All-Wise"],["خَبِيرٍ","All-Aware"]]],"1475":["(agar) supaya (kalian tidak menyembah selain Allah. Sesungguhnya aku, Muhammad, adalah pemberi peringatan kepada kalian dari-Nya) yaitu dengan azab jika kalian berbuat kekafiran (dan pembawa berita gembira) dengan pahala jika kalian beriman.",[["أَلَّا","That \"Not"],["تَعْبُدُوٓا۟","you worship"],["إِلَّا","but"],["ٱللَّهَ ۚ","Allah"],["إِنَّنِى","Indeed, I am"],["لَكُم","to you"],["مِّنْهُ","from Him"],["نَذِيرٌۭ","a warner"],["وَبَشِيرٌۭ","and a bearer of glad tidings"]]],"1476":["(Dan hendaklah kalian meminta ampun kepada Rabb kalian) dari kemusyrikan (dan bertobatlah kalian) kembalilah kalian (kepada-Nya) dengan menjalankan ketaatan (niscaya Dia akan memberi kenikmatan kepada kalian) di dunia (dengan kenikmatan yang baik) dengan kehidupan yang baik dan rezeki yang banyak (sampai pada waktu yang telah ditentukan) yaitu mati (dan Dia akan memberi) kelak di akhirat (kepada tiap-tiap orang yang mempunyai keutamaan) di dalam beramal (keutamaannya) yakni balasannya (Dan jika kalian berpaling) lafal tawallau pada asalnya adalah tatawallau kemudian salah satu dari dua huruf ta dibuang sehingga jadilah tawallau, artinya berpaling (maka sesungguhnya aku takut kalian akan ditimpa siksa di hari kiamat) yaitu hari akhir.",[["وَأَنِ","And that"],["ٱسْتَغْفِرُوا۟","Seek forgiveness"],["رَبَّكُمْ","(of) your Lord"],["ثُمَّ","and"],["تُوبُوٓا۟","turn in repentance"],["إِلَيْهِ","to Him"],["يُمَتِّعْكُم","He will let you"],["مَّتَـٰعًا","enjoy"],["حَسَنًا","a good"],["إِلَىٰٓ","for"],["أَجَلٍۢ","a term"],["مُّسَمًّۭى","appointed"],["وَيُؤْتِ","And give"],["كُلَّ","(to) every"],["ذِى","owner"],["فَضْلٍۢ","(of) grace"],["فَضْلَهُۥ ۖ","His Grace"],["وَإِن","But if"],["تَوَلَّوْا۟","you turn away"],["فَإِنِّىٓ","then indeed, I"],["أَخَافُ","fear"],["عَلَيْكُمْ","for you"],["عَذَابَ","(the) punishment"],["يَوْمٍۢ","(of) a Great Day"],["كَبِيرٍ","(of) a Great Day"]]],"1477":["(Kepada Allahlah kembali kalian, dan Dia Maha Kuasa atas segala sesuatu) antara lain ialah memberi pahala dan menentukan azab.",[["إِلَى","To"],["ٱللَّهِ","Allah"],["مَرْجِعُكُمْ ۖ","(is) your return"],["وَهُوَ","and He"],["عَلَىٰ","(is) on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌ","All-Powerful"]]],"1478":["Ayat ini seperti yang diriwayatkan oleh Imam Bukhari melalui Ibnu Abbas r.a. diturunkan berkenaan dengan orang-orang yang merasa malu untuk membuang air besar atau merasa malu berjimak karena kemaluan mereka terlihat dari atas langit. Akan tetapi menurut pendapat yang lain dikatakan bahwa ayat ini diturunkan berkenaan dengan perihal orang-orang munafik (Ingatlah sesungguhnya orang-orang munafik itu memalingkan dada mereka untuk menyembunyikan diri daripada-Nya) daripada Allah (Ingatlah, di waktu mereka menyelimuti dirinya dengan kain) menutupi dirinya dengan kain (Allah mengetahui) Maha Tinggi Allah (apa yang mereka sembunyikan dan apa yang mereka lahirkan) sehingga sembunyi mereka tidak ada gunanya lagi (sesungguhnya Allah Maha Mengetahui segala isi hati) artinya Dia mengetahui semua apa yang ada di dalam hati.",[["أَلَآ","No doubt"],["إِنَّهُمْ","They"],["يَثْنُونَ","fold up"],["صُدُورَهُمْ","their breasts"],["لِيَسْتَخْفُوا۟","that they may hide"],["مِنْهُ ۚ","from Him"],["أَلَا","Surely"],["حِينَ","when"],["يَسْتَغْشُونَ","they cover (themselves)"],["ثِيَابَهُمْ","(with) their garments"],["يَعْلَمُ","He knows"],["مَا","what"],["يُسِرُّونَ","they conceal"],["وَمَا","and what"],["يُعْلِنُونَ ۚ","they reveal"],["إِنَّهُۥ","Indeed, He"],["عَلِيمٌۢ","(is) All-Knower"],["بِذَاتِ","of what"],["ٱلصُّدُورِ","(is in) the breasts"]]]});